import { act, useState } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import Layout from '../layout';
import EditorLayout from '../m/[id]/layout';
import SendPage from '../m/[id]/send/page';

import type { FC, ReactNode } from 'react';

import ConfirmationDialog from '~/components/ConfirmationDialog';
import StyledLink from '~/components/StyledLink';
import click from '~/components/__tests__/helpers/click';
import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';
import enter from '~/components/__tests__/helpers/enter';
import { createLinkRouter, WithLinkRouter } from '~/components/__tests__/helpers/linkNavigation';
import press from '~/components/__tests__/helpers/press';
import { useConfirmation } from '~/providers/ConfirmationProvider';
import { useMessage } from '~/providers/MessageProvider';

const hoisted = vi.hoisted(() => ({
  pathname: '/message/m/4/edit',
  signedIn: false,
  push: vi.fn(),
  messages: [] as unknown[],
  saved: new Map<string, Record<string, unknown>>(),
  guild: null as null | { id: string, name: string, icon: null },
  assign: vi.fn(),
  reload: vi.fn(),
}));

vi.mock('pusher-js', () => ({
  default: function Pusher() {
    return {
      subscribe: () => ({ bind: () => undefined, unbind: () => undefined }),
      unsubscribe: () => undefined,
      disconnect: () => undefined,
    };
  },
}));
vi.mock('~/env.mjs', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', () => ({
  useRouter: () => ({
    push: hoisted.push, replace: () => undefined, refresh: () => undefined, back: () => undefined,
  }),
  usePathname: () => hoisted.pathname,
  useSearchParams: () => new URLSearchParams(''),
}));
vi.mock('next-auth/react', () => ({
  useSession: () => (hoisted.signedIn
    ? { status: 'authenticated', data: { user: { guilds: [] } } }
    : { status: 'unauthenticated', data: null }),
  signIn: () => undefined,
}));
vi.mock('next/image', () => ({ default: () => null }));
vi.mock('../../_components/Providers', () => ({ default: ({ children }: { children: ReactNode }) => children }));
vi.mock('../../_navigation/Redirects', () => ({ default: () => null }));
vi.mock('~/components/dynamics/ToastContainerWrapper', () => ({ default: () => null }));
vi.mock('~/providers/HotkeysProviderWrapper', () => ({ default: ({ children }: { children: ReactNode }) => children }));
vi.mock('~/providers/IsMobileProvider', () => ({ useIsMobile: () => false }));
vi.mock('~/providers/PartialMessagesProvider', () => ({
  usePartialMessages: () => ({ messages: hoisted.messages, refetchIfStale: () => {}, isLoading: false }),
}));
vi.mock('~/providers/GuildProvider', () => ({
  useGuild: () => ({
    webhooks: [],
    setGuildId: () => undefined,
    guild: hoisted.guild,
    guildId: hoisted.guild?.id ?? null,
    isLoading: false,
    isLoadingChannels: false,
    hasLoaded: true,
    refetchAll: () => undefined,
  }),
}));
vi.mock('~/providers/WebhookProvider', () => ({
  default: ({ children }: { children: ReactNode }) => children,
  useWebhook: () => ({
    oldMessage: null,
    threadId: '',
    threadName: '',
    selectedWebhook: null,
    setMessageIdOrUrl: () => undefined,
    setThreadId: () => undefined,
    setSelectedWebhook: () => undefined,
  }),
}));
vi.mock('../m/[id]/send/_components/EditMessageMenu', () => ({ default: () => null }));
vi.mock('../m/[id]/send/_components/WebhookMenu', () => ({ default: () => null }));
vi.mock('~/components/MessagePreview', () => ({ default: () => null }));
vi.mock('~/app/_components/NavMenu', () => ({ default: () => null }));
vi.mock('~/app/_components/ThemeToggle', () => ({ default: () => null }));
vi.mock('~/app/message/m/[id]/_components/JsonMenu', () => ({ default: () => null }));
vi.mock('~/app/message/m/[id]/_components/SaveAsMenu', () => ({ default: () => null }));
vi.mock('~/utils/api', async () => {
  const { buildApiMock } = await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps');
  return buildApiMock({
    queryData: {
      'message.getOne': () => (/\/m\/0\//.test(hoisted.pathname)
        ? undefined
        : hoisted.saved.get(hoisted.pathname.match(/\/m\/(\d+)\//)?.[1] ?? '')),
    },
  });
});

const TITLE = 'You have unsaved changes!';
let linkRouter: ReturnType<typeof createLinkRouter>;
let editor: ReturnType<typeof useMessage> | null = null;
let raiseEditorPrompt: VoidFunction = () => {};
let setEditorMounted: (mounted: boolean) => void = () => {};

const SAME_MESSAGE_LOOKALIKES: Array<[string, boolean]> = [
  ['/message/m/4/edit/', false],
  ['/message/m/4/edit?tab=1', false],
  ['http://localhost:3000/message/m/4/send', false],
  ['https://other.example/message/m/4/edit', true],
  ['/message/m/4/edit/extra', true],
  ['/message/m/new', true],
];

const Capture: FC = () => {
  editor = useMessage();
  const { showConfirmation } = useConfirmation();
  raiseEditorPrompt = () => showConfirmation({
    enabled: true, title: 'Message Update Detected', message: 'm', confirmText: 'Reload', onConfirm: hoisted.reload,
  });
  return null;
};

const EditorPage: FC<{ withDialog?: boolean }> = ({ withDialog = false }) => (
  <>
    <Capture />
    {withDialog && <ConfirmationDialog />}
    <StyledLink href="/message/f/9">inside the editor</StyledLink>
    {SAME_MESSAGE_LOOKALIKES.map(([href]) => <StyledLink key={href} href={href}>{`to ${href}`}</StyledLink>)}
  </>
);

const sendPage = (
  <>
    <Capture />
    <SendPage />
  </>
);

async function mountTree(
  withDialog = false,
  page: ReactNode = <EditorPage withDialog={withDialog} />,
) {
  const tree = await EditorLayout({ children: page });
  const Harness: FC = () => {
    const [mounted, setMounted] = useState(true);
    setEditorMounted = setMounted;
    return (
      <WithLinkRouter router={linkRouter}>
        <Layout>
          {mounted ? tree : null}
          <StyledLink href="/message/f/7">outside the editor</StyledLink>
        </Layout>
      </WithLinkRouter>
    );
  };
  mountDom(<Harness />);
  await act(async () => {});
}

const theEditor = () => editor as ReturnType<typeof useMessage>;

function edit() {
  act(() => { theEditor().updateMessage({ data: { ...theEditor().message?.data, content: 'unsaved edit' } as never }); });
}

function link(text: string) {
  const found = Array.from(document.body.querySelectorAll('a')).find((a) => a.textContent?.includes(text));
  expect(found, `no link with text "${text}"`).toBeTruthy();
  return found as HTMLAnchorElement;
}

function linkTo(href: string) {
  const found = Array.from(document.body.querySelectorAll('a')).find((a) => a.getAttribute('href') === href);
  expect(found, `no link to ${href}`).toBeTruthy();
  return found as HTMLAnchorElement;
}

function dialogButton(text: string, title: string) {
  const dialog = Array.from(document.body.querySelectorAll('[role="dialog"]')).find((d) => d.textContent?.includes(title));
  expect(dialog, `no dialog titled "${title}"`).toBeTruthy();
  const found = Array.from(dialog?.querySelectorAll('button') ?? []).find((b) => b.textContent?.includes(text));
  expect(found, `no "${text}" button`).toBeTruthy();
  return found as HTMLElement;
}

function button(label: string) {
  const found = document.body.querySelector(`button[aria-label="${label}"]`);
  expect(found, `no button labelled ${label}`).toBeTruthy();
  return found as HTMLElement;
}

function search(text: string) {
  const input = document.body.querySelector('#nav-search') as HTMLInputElement;
  act(() => {
    Reflect.set(HTMLInputElement.prototype, 'value', text, input);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  });
}

function titleOfFocusedDialog() {
  return Array.from(document.body.querySelectorAll('[role="dialog"]'))
    .find((d) => d.contains(document.activeElement))?.textContent ?? '';
}

const prompted = () => document.body.textContent?.includes(TITLE) ?? false;

beforeEach(() => {
  hoisted.pathname = '/message/m/4/edit';
  hoisted.signedIn = false;
  hoisted.guild = null;
  hoisted.assign.mockClear();
  vi.stubGlobal('location', {
    protocol: 'http:',
    hostname: 'localhost',
    port: '3000',
    origin: 'http://localhost:3000',
    href: 'http://localhost:3000/message/m/4/send',
    assign: hoisted.assign,
  });
  hoisted.push.mockClear();
  hoisted.reload.mockClear();
  hoisted.messages = [];
  hoisted.saved.clear();
  for (const id of ['0', '4', '42']) {
    hoisted.saved.set(id, {
      id, name: 'Saved', updatedAt: 1000, data: { content: 'saved copy' },
    });
  }
  linkRouter = createLinkRouter();
  window.localStorage.clear();
  window.sessionStorage.clear();
});
afterEach(() => {
  vi.unstubAllGlobals();
  unmountDom();
  editor = null;
});

describe('the editor routes, a link away with unsaved changes', () => {
  it('asks before the avatar link leaves the editor, and Cancel keeps the edits', async () => {
    await mountTree();
    edit();

    click(linkTo('/message/f/0'));
    expect(prompted()).toBe(true);
    expect(linkRouter.push).not.toHaveBeenCalled();

    press(dialogButton('Cancel', TITLE));
    await vi.waitFor(async () => {
      await act(async () => {});
      expect(prompted()).toBe(false);
    });

    expect(prompted()).toBe(false);
    expect(hoisted.push).not.toHaveBeenCalled();
    expect((theEditor().message?.data as { content?: string }).content).toBe('unsaved edit');
  });

  it('navigates to the avatar link when the prompt is confirmed', async () => {
    await mountTree();
    edit();
    click(linkTo('/message/f/0'));

    press(dialogButton('Leave Page', TITLE));

    expect(hoisted.push).toHaveBeenCalledExactlyOnceWith('/message/f/0', { scroll: undefined });
  });

  it('asks the same for a link rendered inside the editor\'s own providers', async () => {
    await mountTree();
    edit();

    click(link('inside the editor'));

    expect(prompted()).toBe(true);
    expect(linkRouter.push).not.toHaveBeenCalled();
  });

  it('asks for a link activated from the keyboard', async () => {
    await mountTree();
    edit();

    click(linkTo('/message/f/0'), { detail: 0 });

    expect(prompted()).toBe(true);
  });

  it('does not ask while nothing has changed', async () => {
    await mountTree();

    click(linkTo('/message/f/0'));

    expect(prompted()).toBe(false);
    expect(linkRouter.push).toHaveBeenCalledTimes(1);
  });

  it('does not ask for the link to the same message\'s send page', async () => {
    await mountTree();
    edit();

    click(linkTo('/message/m/4/send'));

    expect(prompted()).toBe(false);
    expect(linkRouter.push).toHaveBeenCalledTimes(1);
  });

  it.each(SAME_MESSAGE_LOOKALIKES)('link to %s: asks is %s', async (href, asks) => {
    await mountTree();
    edit();

    click(link(`to ${href}`));

    expect(prompted()).toBe(asks);
  });

  it('stops asking once the editor has unmounted', async () => {
    await mountTree();
    edit();
    act(() => { setEditorMounted(false); });

    click(link('outside the editor'));

    expect(prompted()).toBe(false);
    expect(linkRouter.push).toHaveBeenCalledTimes(1);
  });
});

describe('the send route, a link away with unsaved changes', () => {
  beforeEach(() => { hoisted.pathname = '/message/m/4/send'; });

  it.each([
    ['the sidebar logo', '/', false],
    ['the sidebar edit link', '/message/m/0/edit', false],
    ['the sidebar terms link', '/legal/terms', false],
    ['the sidebar privacy link', '/legal/privacy', false],
    ['the sidebar servers link', '/message', true],
    ['the sidebar account link', '/message/f/0', true],
  ])('asks before %s leaves the page', async (_name, href, signedIn) => {
    hoisted.signedIn = signedIn;
    await mountTree();
    edit();
    press(button('open sidebar'));

    click(linkTo(href));

    expect(prompted()).toBe(true);
    expect(linkRouter.push).not.toHaveBeenCalled();
  });

  it('does not ask for a sidebar link when nothing has changed', async () => {
    await mountTree();
    press(button('open sidebar'));

    click(linkTo('/message/m/0/edit'));

    expect(prompted()).toBe(false);
    expect(linkRouter.push).toHaveBeenCalledTimes(1);
  });

  it.each([
    ['another message whose id starts with this one', '4', '42', true],
    ['another message whose id is a prefix of this one', '42', '4', true],
    ['this message', '4', '4', false],
    ['this message, with a long id', '42', '42', false],
  ])('search result to %s: asks is %s', async (_name, current, other, asks) => {
    hoisted.pathname = `/message/m/${current}/send`;
    hoisted.messages = [{
      id: other, name: 'Alpha result', guildId: null, createdAt: 1, updatedAt: 1,
    }];
    await mountTree();
    edit();
    search('Alpha');
    await act(async () => {});

    click(linkTo(`/message/m/${other}/edit`));

    expect(prompted()).toBe(asks);
    expect(linkRouter.push).toHaveBeenCalledTimes(asks ? 0 : 1);
  });

  it('does not ask for the sidebar\'s edit link on the unsaved route', async () => {
    hoisted.pathname = '/message/m/0/send';
    await mountTree();
    edit();
    press(button('open sidebar'));

    click(linkTo('/message/m/0/edit'));

    expect(prompted()).toBe(false);
  });
});

describe('the send page\'s own links', () => {
  beforeEach(() => {
    hoisted.pathname = '/message/m/4/send';
    hoisted.signedIn = true;
  });

  const linksTo = (href: string) => Array.from(document.body.querySelectorAll(`a[href="${href}"]`));

  it('asks before the crumb to the server\'s folder leaves the page', async () => {
    hoisted.guild = { id: '123', name: 'The Guild', icon: null };
    await mountTree(false, sendPage);
    edit();

    click(linksTo('/message/f/123')[0]);

    expect(prompted()).toBe(true);
    expect(linkRouter.push).not.toHaveBeenCalled();
  });

  it('asks before either crumb to the user\'s folder leaves the page', async () => {
    await mountTree(false, sendPage);
    edit();
    expect(linksTo('/message/f/0')).toHaveLength(2);

    click(linksTo('/message/f/0')[1]);

    expect(prompted()).toBe(true);
    expect(linkRouter.push).not.toHaveBeenCalled();
  });

  it('does not ask for the links back to this message\'s editor', async () => {
    await mountTree(false, sendPage);
    edit();
    expect(linksTo('/message/m/4/edit').length).toBeGreaterThanOrEqual(2);

    for (const anchor of linksTo('/message/m/4/edit')) click(anchor);

    expect(prompted()).toBe(false);
    expect(linkRouter.push).toHaveBeenCalledTimes(linksTo('/message/m/4/edit').length);
  });

  it('asks before the bot invitation, a link to another site, leaves the page, and leaves for it once confirmed', async () => {
    Object.assign(hoisted.saved.get('4') as object, { guildId: '123' });
    await mountTree(false, sendPage);
    edit();
    const invite = Array.from(document.body.querySelectorAll('a')).find((a) => a.getAttribute('href')?.includes('guild_id=123')) as HTMLAnchorElement;
    expect(invite, 'no bot invitation link').toBeTruthy();

    click(invite);
    expect(prompted()).toBe(true);
    expect(hoisted.assign).not.toHaveBeenCalled();

    press(dialogButton('Leave Page', TITLE));

    expect(hoisted.assign).toHaveBeenCalledTimes(1);
    expect(hoisted.assign.mock.calls[0][0]).toContain('guild_id=123');
    expect(hoisted.push).not.toHaveBeenCalled();
  });
});

describe('the link prompt and the editor\'s own prompt', () => {
  it('keeps both open when raised together, each answered on its own, with a link inside the editor', async () => {
    await mountTree(true);
    edit();
    act(() => { raiseEditorPrompt(); });
    click(link('inside the editor'));

    expect(document.body.textContent).toContain('Message Update Detected');
    expect(prompted()).toBe(true);

    press(dialogButton('Cancel', TITLE));
    await vi.waitFor(async () => {
      await act(async () => {});
      expect(prompted()).toBe(false);
    });

    expect(document.body.textContent).toContain('Message Update Detected');
    expect(prompted()).toBe(false);
    expect(hoisted.push).not.toHaveBeenCalled();
  });

  it.each([
    ['the link prompt first', true],
    ['the update prompt first', false],
  ])('answers only the prompt that holds focus when Enter is pressed with both open, %s', async (_name, linkFirst) => {
    await mountTree(true);
    edit();
    if (linkFirst) {
      click(link('inside the editor'));
      act(() => { raiseEditorPrompt(); });
    } else {
      act(() => { raiseEditorPrompt(); });
      click(link('inside the editor'));
    }
    const linkHasFocus = titleOfFocusedDialog().includes(TITLE);
    expect(titleOfFocusedDialog()).toMatch(linkHasFocus ? TITLE : 'Message Update Detected');

    enter();

    expect(hoisted.push.mock.calls.length + hoisted.reload.mock.calls.length).toBe(1);
    expect(hoisted.push).toHaveBeenCalledTimes(linkHasFocus ? 1 : 0);
    expect(hoisted.reload).toHaveBeenCalledTimes(linkHasFocus ? 0 : 1);
    const updatePrompted = () => document.body.textContent?.includes('Message Update Detected') ?? false;
    await vi.waitFor(async () => {
      await act(async () => {});
      expect(prompted()).toBe(!linkHasFocus);
      expect(updatePrompted()).toBe(linkHasFocus);
    });

    press(dialogButton(linkHasFocus ? 'Reload' : 'Leave Page', linkHasFocus ? 'Message Update Detected' : TITLE));
    expect(hoisted.push.mock.calls.length + hoisted.reload.mock.calls.length).toBe(2);
  });

  it('renders no editor prompt on the send page, and still asks for its links', async () => {
    hoisted.pathname = '/message/m/4/send';
    await mountTree();
    edit();

    act(() => { raiseEditorPrompt(); });
    expect(document.body.textContent).not.toContain('Message Update Detected');

    click(link('inside the editor'));
    expect(prompted()).toBe(true);
  });
});

