import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { describe, expect, it, vi } from 'vitest';

import { EditorView } from '@codemirror/view';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

import NewMessageJsonInput from '../NewMessageJsonInput';

let container: HTMLDivElement | null = null;
let root: ReturnType<typeof createRoot> | null = null;

function unmount() {
  if (root) act(() => { root!.unmount(); });
  if (container) container.remove();
  root = null;
  container = null;
}

function mount() {
  container = document.createElement('div');
  document.body.appendChild(container);
  root = createRoot(container);
  act(() => { root!.render(<NewMessageJsonInput setMessage={() => {}} />); });
  return container;
}

// Replaces the whole CodeMirror document with `json` and lets the resulting `onChange` ->
// `useUpdateEffect` cycle settle.
async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

describe('NewMessageJsonInput — settled notice', () => {
  it('renders the settled notice for a message carrying the Components V2 flag but only classic content', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');
    unmount();
  });

  it('does not render a notice for a plain classic message', async () => {
    const el = mount();
    await type(el, JSON.stringify({ content: 'Hi' }));
    expect(el.textContent).not.toContain('saved as Classic and the flag cleared');
    unmount();
  });

  it('the notice is styled as a warning', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    const notice = Array.from(el.querySelectorAll('p'))
      .find((p) => p.textContent?.includes('saved as Classic'));
    expect(notice?.className).toContain('text-warning');
    unmount();
  });

  it('an invalid edit clears a previously settled notice and shows the parse error instead', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');

    await type(el, '{not valid json');
    expect(el.textContent).not.toContain('saved as Classic and the flag cleared');
    unmount();
  });

  it('editing back to a plain classic message clears the notice', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');

    await type(el, JSON.stringify({ content: 'Hi' }));
    expect(el.textContent).not.toContain('saved as Classic and the flag cleared');
    unmount();
  });
});

