'use client';

import {
  ArrowDownIcon, ArrowPathIcon, ArrowTopRightOnSquareIcon, ArrowUpIcon,
  BarsArrowDownIcon, CodeBracketIcon, EllipsisVerticalIcon, ListBulletIcon,
  PaperAirplaneIcon, PencilIcon, Squares2X2Icon, TrashIcon,
} from '@heroicons/react/20/solid';
import { DocumentIcon, DocumentPlusIcon } from '@heroicons/react/24/outline';
import {
  ArrowDownTrayIcon, ChatBubbleBottomCenterIcon, UserIcon,
} from '@heroicons/react/24/solid';
import classNames from 'classnames';
import copy from 'copy-to-clipboard';
import { useSession } from 'next-auth/react';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import {
  useCallback, useEffect,
  useMemo, useRef, useState,
} from 'react';
import { toast } from 'react-toastify';

import NewMessageModal from '../../_components/NewMessageModal';
import {
  Container, ContainerSection, HeaderTitle, SectionHeader,
} from '../../_layout/Container';

import type { Id } from 'react-toastify';

import DiscordIcon from '~/assets/svg/DiscordIcon';
import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import Dropdown from '~/components/Dropdown';
import InfoPanel from '~/components/InfoPanel';
import LoadingDots from '~/components/LoadingDots';
import NullableComponent from '~/components/NullableComponent';
import StyledLink from '~/components/StyledLink';
import { BLUR_DATA_URL, GUILD_FEATURES, INVITE_URL } from '~/constants';
import { useGuild } from '~/providers/GuildProvider';
import { useIsMobile } from '~/providers/IsMobileProvider';
import { useMessages } from '~/providers/MessagesProvider';
import styles from '~/styles';
import { constructGuildIcon, getPreviewImageUrl, pushSorted } from '~/utils';
import { api } from '~/utils/api';
import copyIntroMessage from '~/utils/copyIntroMessage';
import formatMessageDate from '~/utils/formatMessageDate';
import {
  useClientPreferences, useMounted, useParsePathname, useToggleState,
} from '~/utils/hooks';

import '~/utils/loadLocales';

type MessageSortProp = Extract<keyof PartialApiMessage, 'updatedAt' | 'createdAt' | 'name'>;

function compareGuildMessage(
  prop: keyof PartialApiMessage,
  asc: boolean,
  a: PartialApiMessage,
  b: PartialApiMessage,
) {
  switch (prop) {
    case 'name':
      return asc ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name);
    case 'updatedAt':
      return asc ? a.updatedAt - b.updatedAt : b.updatedAt - a.updatedAt;
    case 'createdAt':
      return asc ? a.createdAt - b.createdAt : b.createdAt - a.createdAt;
    default:
      return 0;
  }
}

const Page = () => {
  const isMobile = useIsMobile();
  const router = useRouter();
  const { data: session } = useSession();
  const { folderId, guildId } = useParsePathname();
  const {
    guild: ctxGuild,
    isLoading: isGuildLoading,
    isFetching: isGuildFetching,
    // error: guildError,
    refetchAll: refetchGuild,
  } = useGuild();

  const {
    messages: allMessages,
    isLoading: isMessagesLoading,
    refetch: refetchMessages,
  } = useMessages();

  const [newMessageModalOpen,
    { setTrue: openNewMessageModal, setFalse: closeNewMessageModal },
  ] = useToggleState();

  const localStorage = useClientPreferences();
  const {
    message_f_view: listView,
    message_f_sort: orderProp,
    message_f_order: order,
  } = localStorage.current;

  const toggleListView = useCallback(() => localStorage.update({
    message_f_view: listView === 'list' ? 'grid' : 'list',
  }), [listView, localStorage.update]);

  const handleSort = useCallback((prop: MessageSortProp) => {
    if (orderProp === prop) {
      localStorage.update({
        message_f_order: order === 'asc' ? 'desc' : 'asc',
      });
    } else if (prop === 'name') {
      localStorage.update({
        message_f_sort: prop,
        message_f_order: 'asc',
      });
    } else {
      localStorage.update({
        message_f_sort: prop,
        message_f_order: 'desc',
      });
    }
  }, [orderProp, order, localStorage.update]);

  const { mutate: upsertMessage, isPending: isMessageLoading } = api.message.upsert.useMutation({
    onSuccess: (data) => router.push(`/message/m/${data.id}/edit`),
    onError: () => {
      toast.error('Failed to create message');
    },
  });

  const loadingRef = useRef<boolean>(isGuildLoading || isMessagesLoading || isMessageLoading);
  loadingRef.current = isGuildLoading || isMessagesLoading || isMessageLoading;
  const refetch = useCallback(() => {
    if (loadingRef.current) return;
    refetchGuild();
    refetchMessages();
  }, [refetchGuild, refetchMessages]);

  const messages = useMemo(() => {
    if (!folderId) return null;
    // if (folderId === '0') return allMessages.filter((m) => !m.guildId);
    // return allMessages.filter((m) => m.guildId === folderId);
    const compare = (a: PartialApiMessage, b: PartialApiMessage) => compareGuildMessage(orderProp, order === 'asc', a, b);
    const tmp: PartialApiMessage[] = [];
    for (const msg of allMessages) {
      if ((folderId === '0' && !msg.guildId) || msg.guildId === folderId) {
        pushSorted(tmp, msg, compare);
      }
    }
    return tmp;
  }, [allMessages, folderId, orderProp, order]);

  const toastIdRef = useRef<Id>(-1);
  const {
    isPending: isDeleting, mutate: deleteMessage,
  } = api.message.delete.useMutation({
    onMutate: () => { toastIdRef.current = toast.loading('Deleting message...'); },
    onSuccess: () => {
      refetchMessages();
      toast.update(toastIdRef.current, {
        type: 'success',
        render: 'Message deleted.',
        isLoading: false,
        autoClose: null,
      });
    },
    onError: () => {
      toast.update(toastIdRef.current, {
        type: 'error',
        render: 'Error. Failed to delete message. Please try again.',
        isLoading: false,
        autoClose: null,
      });
    },
  });

  const [copyMessageId, setCopyMessageId] = useState('');
  const {
    isFetching: isCopying, data: copyData, error: copyError,
  } = api.message.getOne.useQuery(copyMessageId, {
    initialData: null,
    enabled: !!copyMessageId,
    staleTime: Infinity,
    refetchOnWindowFocus: false,
  });

  // Replaces onSuccess/onError callbacks removed in RQ5
  useEffect(() => {
    if (copyData) {
      copy(JSON.stringify(copyData, null, 2), { format: 'text/plain' });
      setCopyMessageId('');
      toast.success('Message copied!');
    }
  }, [copyData]);

  useEffect(() => {
    if (copyError) toast.error('Failed to copy message.');
  }, [copyError]);

  const mounted = useMounted();
  const guild = ctxGuild ?? session?.user.guilds.find((g) => g.id === guildId);
  if (guild === undefined && isGuildLoading) {
    return (
      <div className={styles.flex({ cx: true })}>
        <LoadingDots className="h-16 w-16" />
      </div>
    );
  }

  if (!folderId || !mounted) return null;

  let title;
  if (orderProp === 'name') {
    title = 'Messages by Name';
  } else if (orderProp === 'createdAt') {
    title = 'Messages by Creation Date';
  } else if (orderProp === 'updatedAt') {
    title = 'Messages by Last Modified';
  } else {
    title = 'Messages';
  }

  const botInviteUrl = new URL(INVITE_URL);
  botInviteUrl.searchParams.set('guild_id', guildId);

  return (
    <Container>
      <NullableComponent show={guildId && !isGuildFetching && !ctxGuild}>
        <ContainerSection>
          <InfoPanel
            text='Invite the bot to access more features'
            subText="Here's what you'll be able to do!"
            items={GUILD_FEATURES}
            backLabel="I'll do it later"
            continueLabel={(
              <>
                <DiscordIcon className='mr-2 h-6 w-6' />
                Invite
              </>
            )}
            onContinue={botInviteUrl}
          />
        </ContainerSection>
      </NullableComponent>
      <ContainerSection innerClassName={classNames(styles.flex({ cy: true, btw: true }), 'rounded-lg bg-quaternary p-4')}>
        <div className={styles.flex({ cy: true })}>
          <StyledLink href="/message" className={styles.button.underlineHover}>
            Servers
          </StyledLink>
          <span className="px-2 text-2xl">/</span>
          {guild ? (
            <span className={styles.flex({ cy: true, gap: 1 })}>
              <Image
