import { ArrowDownTrayIcon, ClipboardDocumentIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import { useEffect, useMemo, useState } from 'react';
import { z } from 'zod';

import type { ContentLossChoice, ContentLossOption } from '~/utils';

import Button from '~/components/Button';
import LoadingDots from '~/components/LoadingDots';
import NullableComponent from '~/components/NullableComponent';
import { DialogFooter } from '~/components/PresetDialog';
import StyledButtonGroup from '~/components/StyledButtonGroup';
import { useConfirmation } from '~/providers/ConfirmationProvider';
import { useMessage } from '~/providers/MessageProvider';
import {
  describeDroppedComponentTypesNotice, describeUnsupportedComponentTypes, discordMessageImportShape,
} from '~/server/api/utils/shapes';
import styles from '~/styles';
import {
  applyDisposition, computeLoadDiff, describeDropSet, describeLoadDiff, jsonModalSeed,
  noticeMessageForSettled, resolveContentLoss, validateContentRequirements,
} from '~/utils';
import { formatZodIssues } from '~/utils/formatMutationError';
import { usePassedProp } from '~/utils/hooks';
import useCodeMirror from '~/utils/hooks/useCodeMirror';
import useCopyToClipboard from '~/utils/hooks/useCopyToClipboard';

function isJSONParsable(str: string) {
  try {
    JSON.parse(str);
  } catch (e) {
    return false;
  }
  return true;
}

function toCopyText(str: string) {
  try {
    return JSON.stringify(discordMessageImportShape.parse(JSON.parse(str)), null, 2);
  } catch (e) {
    return null;
  }
}

interface Props {
  onClose: VoidFunction;
  setAllowMenuClose: (allow: boolean) => void;
}

const JsonModalBody: FC<Props> = ({ onClose, setAllowMenuClose }) => {
  const { message, updateMessage, editableState } = useMessage();
  const { withConfirmation } = useConfirmation();

  const [messageString, setMessageString] = usePassedProp(
    jsonModalSeed(message),
  );
  const [copyState, copy] = useCopyToClipboard();
  const copyText = useMemo(() => toCopyText(messageString), [messageString]);

  const [error, setError] = useState<null | string>(null);
  const [droppedComponentTypes, setDroppedComponentTypes] = useState<string[]>([]);
  const [validatedDraft, setValidatedDraft] = useState<null | MessageData>(null);
  const [settledNotice, setSettledNotice] = useState<null | string>(null);
  const [pendingChoice, setPendingChoice] = useState<null | {
    validated: MessageData;
    disposition: ContentLossChoice;
  }>(null);
  const [dismissedChoice, setDismissedChoice] = useState<null | {
    validated: MessageData;
    disposition: ContentLossChoice;
  }>(null);

  const { ref, updateDoc } = useCodeMirror({
    value: messageString,
    onChange: setMessageString,
  });

  const commitLoad = () => {
    if (!validatedDraft) return;
    const disposition = resolveContentLoss(
      validatedDraft.flags as number | undefined,
      validatedDraft.components as undefined | { type: number }[],
      validatedDraft.content,
      validatedDraft.embeds,
    );
    if (disposition.requiresChoice) return;
    const next = applyDisposition(validatedDraft);
    updateMessage({ data: next, updatedAt: Date.now() });
    editableState.setMessageMode(disposition.mode);
    setAllowMenuClose(true);
    onClose();
  };

  const commitChoice = (chosenOption: ContentLossOption) => {
    if (!pendingChoice) return;
    const next = applyDisposition(pendingChoice.validated, chosenOption.mode);
    updateDoc(JSON.stringify(next, null, 2));
    setAllowMenuClose(true);
    setPendingChoice(null);
    setDismissedChoice(null);
  };

  const cancelChoice = () => {
    if (pendingChoice) setDismissedChoice(pendingChoice);
    setPendingChoice(null);
    setAllowMenuClose(true);
  };

  const reopenChoice = () => {
    if (!dismissedChoice) return;
    setPendingChoice(dismissedChoice);
    setDismissedChoice(null);
    setAllowMenuClose(false);
  };

  let copyButtonText;
  if (copyState === 'copying') {
    copyButtonText = (
      <>
        <LoadingDots />
        Copying...
      </>
    );
  } else if (copyState === 'copied') {
    copyButtonText = 'Copied!';
  } else {
    copyButtonText = (
      <>
        <ClipboardDocumentIcon className={styles.smallIcon} />
        Copy to Clipboard
      </>
    );
  }

  useEffect(() => {
    setDismissedChoice(null);
    setSettledNotice(null);
    try {
      const rawParsed = JSON.parse(messageString) as { components?: unknown };
      setDroppedComponentTypes(describeUnsupportedComponentTypes(rawParsed.components));
      const parsed = discordMessageImportShape.parse(rawParsed) as MessageData;
      setError(null);
      const disposition = resolveContentLoss(
        parsed.flags as number | undefined,
        parsed.components as undefined | { type: number }[],
        parsed.content,
        parsed.embeds,
      );
      if (disposition.requiresChoice) {
        setDismissedChoice({ validated: parsed, disposition });
        setValidatedDraft(null);
        setAllowMenuClose(true);
        return;
      }
      setPendingChoice(null);
      setValidatedDraft(parsed);
      setSettledNotice(noticeMessageForSettled(disposition));
    } catch (err) {
      setPendingChoice(null);
      if (err instanceof z.ZodError) {
        setError(formatZodIssues(err.issues));
      } else {
        setDroppedComponentTypes([]);
        setError((err as Error).message);
      }
      setValidatedDraft(null);
    }
  }, [messageString]);

  const contentFloorError = validatedDraft
    ? validateContentRequirements(applyDisposition(validatedDraft)) : undefined;

  if (pendingChoice) {
    return (
      <div className={styles.flex({ col: true, gap: 2 })}>
        <p className="text-sm">
          This message has both Components V2 and classic content (text or embeds) — Discord
          cannot show both. Choose which to keep; nothing is saved until you choose.
        </p>
        <div className={styles.flex({ col: true, gap: 2 })}>
          {pendingChoice.disposition.options.map((option) => (
            <Button
              key={option.mode}
              preset='tertiary'
              onPress={() => commitChoice(option)}
            >
              {option.mode === 'v2' ? 'Save as Components V2' : 'Save as Classic'}
              {' — '}
              {describeDropSet(option.dropSet)}
            </Button>
          ))}
        </div>
        <DialogFooter>
          <Button preset='hyperlink' onPress={cancelChoice}>
            Cancel
          </Button>
          <span />
        </DialogFooter>
      </div>
    );
  }

  return (
    <div className={styles.flex({ col: true, gap: 2 })}>
      <div>
        <div ref={ref} className='max-h-full w-full resize-none rounded bg-tertiary p-2 text-sm' />
        {/* <code
            {...fieldProps}
