/**
 * `JsonModalBody`'s Load gate floors the RESOLVED draft (`applyDisposition(validatedDraft)`),
 * not the unresolved parsed one — otherwise every disposition-row-D member (V2 flag set +
 * classic content + no V2 components) is refused. Mounted for real and driven through the real
 * CodeMirror editor, not read as source text. The disposition logic itself
 * (`resolveContentLoss`/`applyDisposition`/`validateContentRequirements`) is covered directly in
 * `utils.rowd-load-disposition.test.ts`; this file covers only the wiring — that the Load button
 * and the floor-error notice actually track `contentFloorError` as computed from the resolved
 * draft.
 */
import { act } from 'react';
import { describe, expect, it, vi, afterEach } from 'vitest';

import { EditorView } from '@codemirror/view';

import { findButton } from '~/components/__tests__/helpers/press';
import { unmountDom } from '~/components/__tests__/helpers/dom';
import { mountInMessageProvider } from '~/providers/MessageProvider/__tests__/helpers/mountMessageProvider';

import JsonModalBody from '../JsonModalBody';

// See JsonModalBody.load-settled-notice.test.tsx for why each factory inlines its own dynamic
// import of the mock-only `messageProviderDeps` module rather than sharing a local binding.
vi.mock('~/env.mjs', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).navigationMock());
