/**
 * `JsonModalBody`'s Load gate floors the RESOLVED draft (`applyDisposition(validatedDraft)`),
 * not the unresolved parsed one — otherwise every disposition-row-D member (V2 flag set +
 * classic content + no V2 components) is refused. Mounted for real and driven through the real
 * CodeMirror editor, not read as source text. The disposition logic itself
 * (`resolveContentLoss`/`applyDisposition`/`validateContentRequirements`) is covered directly in
 * `utils.rowd-load-disposition.test.ts`; this file covers only the wiring — that the Load button
 * and the floor-error notice actually track `contentFloorError` as computed from the resolved
 * draft.
 */
import { act } from 'react';
import { describe, expect, it, vi, afterEach } from 'vitest';

import { EditorView } from '@codemirror/view';

import { findButton } from '~/components/__tests__/helpers/press';
import { unmountDom } from '~/components/__tests__/helpers/dom';
import { mountInMessageProvider } from '~/providers/MessageProvider/__tests__/helpers/mountMessageProvider';

// See JsonModalBody.load-settled-notice.test.tsx for why each factory inlines its own dynamic
// import of the mock-only `messageProviderDeps` module rather than sharing a local binding.
vi.mock('~/env.mjs', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).navigationMock());
vi.mock('next-auth/react', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).AUTH_MOCK);
vi.mock('~/utils/api', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).buildApiMock());
vi.mock('~/providers/GuildProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).GUILD_PROVIDER_MOCK);
vi.mock('~/providers/WebhookProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).WEBHOOK_PROVIDER_MOCK);
vi.mock('~/providers/ConfirmationProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).CONFIRMATION_PROVIDER_MOCK);

import JsonModalBody from '../JsonModalBody';

afterEach(unmountDom);

const FLAG = 1 << 15;
const ACTION_ROW = { type: 1, components: [{ type: 2, style: 5, label: 'x', url: 'https://e.co' }] };

function mount() {
  return mountInMessageProvider(
    <JsonModalBody onClose={() => {}} setAllowMenuClose={() => {}} />,
  );
}

// Replaces the whole CodeMirror document with `json` and lets the resulting parsing effect settle.
async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

describe('JsonModalBody — Load floors the RESOLVED draft, not the unresolved one', () => {
  it('a row D draft (V2 flag + classic content, no V2 components) enables Load with no floor error shown', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'hi', flags: FLAG, embeds: [], components: [],
    }));

    const loadBtn = findButton(el, 'Load') as HTMLButtonElement;
    expect(loadBtn.disabled).toBe(false);
    expect(el.textContent).not.toContain('Message must have content, embeds, or components.');
  });

  it('a row D draft carrying a non-V2 action row also enables Load', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'hi', flags: FLAG, embeds: [], components: [ACTION_ROW],
    }));

    const loadBtn = findButton(el, 'Load') as HTMLButtonElement;
    expect(loadBtn.disabled).toBe(false);
  });

  it('control: a genuinely empty draft leaves Load disabled and shows the floor error', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: '', flags: 0, embeds: [], components: [],
    }));

    const loadBtn = findButton(el, 'Load') as HTMLButtonElement;
    expect(loadBtn.disabled).toBe(true);
    expect(el.textContent).toContain('Message must have content, embeds, or components.');
  });
});

