import JsonModalBody from '../JsonModalBody';

afterEach(unmountDom);

function mount() {
  return mountInMessageProvider(
    <JsonModalBody onClose={() => {}} setAllowMenuClose={() => {}} />,
  );
}

async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

describe('JsonModalBody — Load-site settled notice', () => {
  it('renders the settled notice inline as the JSON is edited, before Load is ever pressed', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');
  });

  it('never fires toast.warn for the settled notice', async () => {
    const warn = vi.spyOn(toast, 'warn').mockImplementation(() => 'id');
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');
    expect(warn).not.toHaveBeenCalled();
    warn.mockRestore();
  });

  it('an edit that no longer settles-with-notice clears the previous notice', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');

    await type(el, JSON.stringify({ content: 'Hi' }));
    expect(el.textContent).not.toContain('saved as Classic and the flag cleared');
  });

  it('an invalid edit clears a previously settled notice and shows the parse error instead', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      content: 'Hi', flags: 32768, embeds: [], components: [],
    }));
    expect(el.textContent).toContain('saved as Classic and the flag cleared');

    await type(el, '{not valid json');
    expect(el.textContent).not.toContain('saved as Classic and the flag cleared');
  });
});

