function constructGuildLabel(
  foundGuild: UserGuild,
  webhook: Webhook | null | undefined,
  threadId: string,
) {
  const channel = webhook?.channel;
  const thread = channel?.threads?.find((t) => t.id === threadId);
  const Icon = channel && getChannelIcon(channel.type);

  const elements: ReactNode[] = [];
  if (foundGuild) {
    elements.push(
      <div key="guild" className={styles.flex({ cy: true, gap: 1.5 })}>
        <Image
          className="rounded-full"
          src={constructGuildIcon(foundGuild, 16)}
          alt={foundGuild.name}
          width={16}
          height={16}
          unoptimized
        />
        <span>{foundGuild.name}</span>
      </div>,
    );
  }
  if (webhook) {
    elements.push(
      <div key="webhook" className={styles.flex({ cy: true, gap: 1 })}>
        {Icon && <Icon className="h-4 w-4" />}
        {channel?.name ?? webhook?.channel_id}
      </div>,
    );
  }

  if (thread) {
    elements.push(thread?.name ?? threadId);
  }

  for (let i = elements.length - 1; i > 0; i -= 1) {
    elements.splice(i, 0, <ChevronRightIcon key={i} className="h-4 w-4 stroke-text-mute stroke-1" />);
  }

  return (
    <div className={classNames(styles.flex({ cy: true, gap: 1 }), styles.subLabel)}>
      {elements}
    </div>
  );
}

const WebhookMenu: FC = () => {
  const { status, data: session } = useSession();
  const { isLoading: isLoadingMessage } = useMessage();
  const {
    guild, channels, webhooks, isFetchingChannels, guildId,
  } = useGuild();
