  const categories = useReduceCategories(guild, webhooks, channels, isFetchingChannels);

  const webhooksRef = useLatest(webhooks);
  const handleRadioGroup = useCallback((id: string) => {
    const webhook = webhooksRef.current.find((wh) => wh.id === id);
    setSelectedWebhook(webhook ?? null);
  }, []);

  const webhookGuild = session?.user.guilds?.find(({ id }) => id === selectedWebhook?.guild_id);

  let destinationComp: ReactNode = null;
  if (isLoadingMessage || isFetchingChannels) {
    destinationComp = (
      <div className={styles.flex({ cx: true })}>
        <LoadingDots className={styles.largeIcon} />
      </div>
    );
  }

  if (selectedWebhook) {
    let subLabel;
    const foundGuild = webhookGuild?.id && session?.user.guilds?.find((g) => g.id === webhookGuild.id);
    if (foundGuild) {
      // subLabel = (
      //   <div className={styles.flex({ cy: true, gap: 1 })}>
      //     <Image
      //       className="rounded-full"
      //       src={constructGuildIcon(foundGuild, 16)}
