      //       width={16}
      //       height={16}
      //       unoptimized
      //     />
      //     <span className={styles.subLabel}>{foundGuild.name}</span>
      //   </div>
      // );
      subLabel = constructGuildLabel(foundGuild, selectedWebhook, threadId);
    } else {
      subLabel = (
        <div className={styles.flex({ cy: true, gap: 1 })}>
          <DiscordIcon className="h-4 w-4" />
          <span className={styles.subLabel}>Unknown Server</span>
        </div>
      );
    }

    destinationComp = (
      <div className={styles.flex({ cy: true, btw: true })}>
        <div>
          <div className={classNames(!selectedWebhook?.name && 'italic text-mute')}>
            {selectedWebhook?.name ?? 'New Webhook'}
          </div>
          <span>{subLabel}</span>
        </div>
        <XMarkIcon className={styles.icon} />
      </div>
    );
  }

  const isLoading = isWebhookLoading;
  const webhookChannel = selectedWebhook?.channel;

  useEffect(() => {
    if (!webhookChannel) showCustomMenu();
  }, [webhookChannel]);

  const items = useMemo(() => categories.map<AccordionSectionProps>(
    ({ options, ...accordionProps }) => ({
      ...accordionProps,
      altHeaderStyle: true,
      children: isFetchingChannels ? (
        <div className={classNames(styles.flex({ cx: true }), 'w-full')}>
          <LoadingDots className={classNames(styles.largeIcon)} />
        </div>
      ) : (
        <RadioButtonGroup
          aria-label={`${accordionProps.title}'s messages`}
          options={options}
          value={selectedWebhook?.id ?? ''}
          onChange={handleRadioGroup}
          gap={0}
          isDisabled={isLoading}
        />
      ),
    }),
  ), [categories, isFetchingChannels, selectedWebhook?.id]);

  const accordionItems = useMemo(() => [
    ...items, {
      id: 'load',
      title: 'Custom Webhook',
      icon: <ArrowDownTrayIcon className="h-6 w-6" />,
      onHeaderClick: resetWebhook,
      altHeaderStyle: true,
      children: (
        <TextField
          inputMode='url'
          label="Webhook URL"
          tooltip='You can find this in the "Integrations" tab of your server settings.'
          TooltipIcon={QuestionMarkCircleIcon}
          value={url}
          onChange={(t) => setUrl(t.trim())}
          outerClassName='m-4 mt-3 space-y-2'
          labelClassName='flex flex-col text-sm'
          inputClassName='bg-input w-full shadow py-1 px-2 rounded'
          placeholder='https://discord.com/api/webhooks/...'
          errorMessage={
            url && !isWebhookLoading && selectedWebhook === null ? INVALID_URL_ERROR : undefined
          }
          isDisabled={isLoading}
        />
      ),
    }], [selectedWebhook, url, isWebhookLoading, isLoading, items]);

  const threadItems = useMemo<DropdownItem[]>(() => (webhookChannel?.threads ?? [])
    .map((thread) => ({
      className: classNames(styles.button.primaryHover, 'rounded px-2 py-1'),
      label: thread.name,
      value: thread.id,
      onPress: () => setThreadId(thread.id),
    })), [webhookChannel]);
  const thread = (webhookChannel?.threads ?? []).find((t) => t.id === threadId);

  const { labelProps, fieldProps } = useLabel({ label: 'Thread' });

  let threadPostLabel;
  let threadPostSubLabel;
  if (!webhookChannel) {
    threadPostLabel = 'Thread or Post';
    threadPostSubLabel = '(required if new Forum Post)';
  } else if (isForumChannel(webhookChannel)) {
    threadPostLabel = 'Post';
    threadPostSubLabel = '(required)';
  } else {
    threadPostLabel = 'Thread';
    threadPostSubLabel = '(optional)';
  }

  let customInputLabel;
  if (!webhookChannel) {
    customInputLabel = 'Thread or Post ID';
  } else if (isForumChannel(webhookChannel)) {
    customInputLabel = 'Post ID';
  } else {
    customInputLabel = 'Thread ID';
  }

  let customNameLabel;
  if (!webhookChannel) {
    customNameLabel = 'New Thread or Post name';
  } else if (isForumChannel(webhookChannel)) {
    customNameLabel = 'New Post name';
  } else {
    customNameLabel = 'New Thread name';
  }

  return (
    <>
      <NullableComponent show={!destinationComp}>
        <StyledAccordion
          onChange={setPickedCategory}
          preExpanded={[selectedCategory]}
          items={accordionItems}
          selected={selectedCategory}
        />
      </NullableComponent>

      <NullableComponent show={!!destinationComp}>
        <TransitionHeightElement>
          <Button className={classNames(styles.button.tertiaryHover, 'w-full rounded-lg bg-secondary-alt p-4')} onPress={resetWebhook}>
            {destinationComp}
          </Button>
        </TransitionHeightElement>
      </NullableComponent>

      <NullableComponent show={isTextChannel(webhookChannel) || selectedWebhook}>
        <NullableComponent show={!webhookChannel || isTextChannel(webhookChannel)}>
          <NullableComponent show={!isCustomMenuOpen}>
            <div>
              <label className="mb-2 block text-sm font-semibold" {...labelProps}>
                {threadPostLabel}
                {' '}
                <span className="italic text-mute">{threadPostSubLabel}</span>
              </label>
              <div className={styles.flex({ gap: 2 })}>
                <Dropdown
                  triggerClassName={classNames('grow p-2', !thread?.name && 'italic text-mute')}
                  dropdownClassName='p-1 space-y-2'
                  label={
                    !webhookChannel?.threads?.length
                      ? 'Channel has no active threads'
                      : (thread?.name ?? 'Select a thread')
                  }
                  items={threadItems}
                  isDisabled={isLoading || !webhookChannel?.threads?.length}
                  {...fieldProps}
                />
                <Button
                  preset='tertiary'
                  onPress={showCustomMenu}
                >
                  <Cog6ToothIcon className={styles.icon} />
                  Custom
                </Button>
                <Button
                  preset='tertiary'
                  onPress={() => setThreadId('')}
                  isDisabled={isLoading || !threadId}
                >
                  <DocumentIcon className={styles.icon} />
                  Clear
                </Button>
              </div>
            </div>
          </NullableComponent>

          <NullableComponent show={isCustomMenuOpen}>
            <div className={styles.flex({ cy: true, gap: 4 })}>
              <TextField
                inputMode='numeric'
                label={customInputLabel}
                outerClassName='flex-1'
                labelClassName='text-sm'
                inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                value={threadId}
                onChange={setThreadId}
                placeholder="01234567890123456789"
                isDisabled={!!threadName}
                isRequired={isForumChannel(webhookChannel)}
              />
              <NullableComponent show={!webhookChannel || isForumChannel(webhookChannel)}>
                OR
                <TextField
                  inputMode='text'
                  label={customNameLabel}
                  outerClassName='flex-1'
                  labelClassName='text-sm'
                  inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                  value={threadName}
                  onChange={setThreadName}
                  placeholder="New Name"
                  isDisabled={!!threadId}
                  isRequired={isForumChannel(webhookChannel)}
                  autoComplete="off"
                />
              </NullableComponent>
              <NullableComponent show={webhookChannel}>
                <Button
                  preset='tertiary'
                  onPress={() => {
                    hideCustomMenu();
                    setThreadId('');
                    setThreadName('');
                  }}
                  className='self-end'
                >
                  <QueueListIcon className={styles.smallIcon} />
                  List
                </Button>
              </NullableComponent>
            </div>
          </NullableComponent>
        </NullableComponent>
      </NullableComponent>
    </>
  );
};

