'use client';

import { QuestionMarkCircleIcon } from '@heroicons/react/20/solid';
import Image from 'next/image';
import { useMemo } from 'react';

import type { RadioOption } from '~/components/RadioButtonGroup';
import type { AccordionSectionProps } from '~/components/StyledAccordion';

import styles from '~/styles';
import { constructGuildIcon, getChannelIcon } from '~/utils';

type Category = Omit<AccordionSectionProps, 'children'> & { options: RadioOption<string>[] };

export default (guild: undefined | null | Guild, webhooks: Webhook[], channels: DiscordChannel[], isLoading: boolean) => useMemo(() => {
  if (isLoading) {
    return [
      {
        id: guild?.id ?? '0',
        title: guild?.name ?? 'Unknown Guild',
        options: [],
        icon: guild ? (
          <Image
            className="h-6 w-6 rounded-full"
            src={constructGuildIcon(guild, 24)}
            alt={guild.name}
            width={24}
            height={24}
            unoptimized
          />
        ) : <QuestionMarkCircleIcon className="h-6 w-6" />,

      },
    ];
  }
  const categoryMap = (webhooks ?? []).reduce((map, webhook) => {
    const channel = channels.find((c) => c.id === webhook.channel_id);
    const Icon = channel && getChannelIcon(channel.type);
    const option: RadioOption<string> = {
      key: webhook.id,
      label: webhook.name,
      subLabel: (
        <div className={styles.flex({ cy: true, gap: 1 })}>
          {Icon && <Icon className="h-4 w-4" />}
          {channel?.name}
        </div>
      ),
      value: webhook.id,
    };

    const category = map.get(guild?.id ?? '0');
    if (category) {
      category.options.push(option);
    } else {
      map.set(guild?.id ?? '0', {
        id: guild?.id ?? '0',
        title: guild?.name ?? 'Unknown Guild',
        options: [option],
        icon: guild ? (
          <Image
            className="h-6 w-6 rounded-full"
            src={constructGuildIcon(guild, 24)}
            alt={guild.name}
            width={24}
            height={24}
            unoptimized
          />
        ) : <QuestionMarkCircleIcon className="h-6 w-6" />,
      });
    }

    return map;
  }, new Map<string, Category>());

  return [...categoryMap.values()].sort((a, b) => a.title.localeCompare(b.title));
}, [guild, webhooks, channels, isLoading]);

