'use client';

import {
  ArrowDownTrayIcon, BarsArrowDownIcon, ListBulletIcon, Squares2X2Icon, UserIcon,
} from '@heroicons/react/20/solid';
import { DocumentIcon, PlusIcon } from '@heroicons/react/24/outline';
import {
  ChevronLeftIcon, ChevronRightIcon, ClockIcon, DocumentPlusIcon,
} from '@heroicons/react/24/solid';
import classNames from 'classnames';
import { useSession } from 'next-auth/react';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import React, {
  useCallback, useEffect, useMemo, useRef,
} from 'react';
import { useScroll } from 'react-use';

import NewMessageModal from './_components/NewMessageModal';
import {
  Container, ContainerSection, HeaderTitle, SectionHeader,
} from './_layout/Container';

import DiscordIcon from '~/assets/svg/DiscordIcon';
import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import NullableComponent from '~/components/NullableComponent';
import StyledLink from '~/components/StyledLink';
import { BLUR_DATA_URL } from '~/constants';
import { useIsMobile } from '~/providers/IsMobileProvider';
import styles from '~/styles';
import { constructGuildIcon, getPreviewImageUrl, pushSorted } from '~/utils';
import { useClientPreferences, useMounted, useToggleState } from '~/utils/hooks';

const Page: FC = () => {
  const { data: session } = useSession();
  const router = useRouter();
  const isMobile = useIsMobile();

  const localStorage = useClientPreferences();
  const {
    message_servers_view: listView,
    message_servers_order: order,
  } = localStorage.current;
  const toggleListView = useCallback(() => localStorage.update({
    message_servers_view: listView === 'list' ? 'grid' : 'list',
  }), [listView, localStorage.update]);
  const toggleOrderNameAsc = useCallback(() => localStorage.update({
    message_servers_order: order === 'asc' ? 'desc' : 'asc',
  }), [order, localStorage.update]);

  const [newMessageModalOpen,
    { setTrue: openNewMessageModal, setFalse: closeNewMessageModal },
  ] = useToggleState();

  useEffect(() => { void router.replace('/message'); }, []);

  const guilds = useMemo(() => {
    const sorted: UserGuild[] = [];
    for (const guild of session?.user.guilds ?? []) {
      pushSorted(
        sorted,
        guild,
        (a, b) => (order === 'asc' ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name)),
      );
    }
    return sorted;
  }, [session, order]);

  const messages = session?.hydration?.messages ?? [];
  const recentMessages = useMemo(() => {
    const tmp: PartialApiMessage[] = [];
    if (session && messages) {
      for (const id of session.user.preferences?.recentMessageIds ?? []) {
        const message = messages.find((m) => m.id === id);
        if (message) tmp.push(message);
      }
    }
    return tmp;
  }, [session?.user, messages]);

  const scrollRef = useRef<HTMLUListElement>(null);
  const { x } = useScroll(scrollRef as React.RefObject<HTMLUListElement>);

  const containerRef = useRef<HTMLDivElement>(null);

  const mounted = useMounted();
  if (!session) return null;

  let showRightScroll = (
    (scrollRef.current?.scrollWidth ?? 0) - (containerRef.current?.clientWidth ?? 0) - x
  ) > 0;
  if (scrollRef.current === null && messages.length > 6) {
    showRightScroll = true;
  }

  const showLeftScroll = x > 0;

  // const continueMessage = session?.user.preferences.message;
  // const noRecentMessages = recentMessages.length === 0 && !continueMessage;
  const noRecentMessages = recentMessages.length === 0;

  return (
    <Container>
      <ContainerSection className="!m-0 bg-primary py-6">
        <SectionHeader>
          <HeaderTitle id="recent-message-title" title="Recent Messages" Icon={ClockIcon} />
          <AnchoredPopover placement='bottom-end'>
            <AnchoredPopover.Trigger
              className={classNames(styles.button.icon, 'rounded-full')}
              tooltip='New Message'
              aria-label='new message'
            >
              <DocumentPlusIcon className={styles.icon} />
            </AnchoredPopover.Trigger>
            <AnchoredPopover.Child
              {...styles.transition({
                transition: 'transition ease-out',
                enter: 'duration-100',
                leave: 'duration-75',
                closed: '-translate-y-2 flipped:translate-y-2 opacity-0',
                opened: 'translate-y-0 opacity-100',
              })}
            >
              {({ close }) => (
                <div className={classNames(styles.flex({ col: true, gap: 1 }), 'w-52 rounded-lg bg-secondary-alt p-1 shadow drop-shadow')}>
                  <StyledLink href="/message/m/new" className={classNames(styles.flex({ cy: true, gap: 4 }), styles.button.primaryHover, 'rounded p-4')}>
                    <DocumentIcon className={styles.icon} />
                    New Message
                  </StyledLink>
                  <Button
                    onPress={() => { openNewMessageModal(); close(); }}
                    className={classNames(styles.flex({ cy: true, gap: 4 }), styles.button.primaryHover, 'rounded p-4')}
                  >
                    <ArrowDownTrayIcon className={styles.icon} />
                    Upload Message
                  </Button>
                </div>
              )}
            </AnchoredPopover.Child>
          </AnchoredPopover>
        </SectionHeader>
        <div ref={containerRef} id='recent-scroll-container' className="relative">
          <ul ref={scrollRef} aria-labelledby='recent-messages-title' id="recent-scroll" className={classNames(styles.flex({ gap: 4 }), 'scrollbar overflow-x-auto rounded')}>
            <NullableComponent show={noRecentMessages}>
              <StyledLink
                href="/message/m/new"
                className={classNames(styles.flex({ col: true, gap: 2 }), 'group m-1')}
              >
                <div className={classNames(
                  styles.flex({ c: true }),
                  'h-40 w-32 rounded-md border-primary bg-white outline-2 outline-fuchsia-500 group-hover:outline group-[.focus-visible]:outline mobile:h-36 mobile:w-28',
                )}
                >
                  <PlusIcon className={classNames('h-12 w-12 stroke-current stroke-2 group-hover:text-fuchsia-500 group-[.focus-visible]:text-fuchsia-500')} />
                </div>
                <span className="text-sm font-semibold group-hover:underline group-hover:brightness-125 group-[.focus-visible]:underline group-[.focus-visible]:brightness-125">
                  New message
                </span>
              </StyledLink>
            </NullableComponent>
            {recentMessages.map((msg) => (
              <li key={msg.id}>
                <StyledLink
                  href={`/message/m/${msg.id}/edit`}
                  className={classNames(styles.flex({ col: true, gap: 2 }), 'group m-1')}
                  onFocus={(e) => { e.currentTarget.scrollIntoView({ behavior: 'auto', block: 'nearest' }); }}
                >
                  <div className={classNames(
                    styles.button.accentGroupHoverOutline,
                    'h-40 w-32 rounded-md border-primary bg-primary outline outline-1 outline-text-mute mobile:h-36 mobile:w-28',
                  )}
                  >
                    <Image
                      aria-hidden
                      unoptimized
                      blurDataURL={BLUR_DATA_URL}
                      priority
                      src={getPreviewImageUrl(msg)}
                      width={224}
                      height={192}
                      alt={msg.name}
                    />
                  </div>
                  <div className={styles.flex({ col: true, gap: 1 })}>
                    <span className="w-32 overflow-hidden text-ellipsis whitespace-pre text-sm font-semibold group-hover:underline group-hover:brightness-125 group-[.focus-visible]:underline group-[.focus-visible]:brightness-125 mobile:w-28">{msg.name}</span>
                    {(msg.guildId && (() => {
                      const guild = guilds.find((g) => g.id === msg.guildId);
                      if (!guild) return null;

                      return (
                        <div className={classNames(styles.flex({ cy: true, gap: 1 }), 'text-mute')}>
                          <Image
                            aria-hidden
                            unoptimized={!!guild.icon}
                            blurDataURL={BLUR_DATA_URL}
                            priority
                            src={constructGuildIcon(guild, 16)}
                            width={16}
                            height={16}
                            alt={guild.name}
                            className={classNames('h-4 w-4 rounded-full')}
                          />
                          <span className="w-[104px] overflow-hidden text-ellipsis whitespace-pre text-sm">{guild.name}</span>
                        </div>
                      );
                    })()) ?? (
                    <div className={classNames(styles.flex({ cy: true, gap: 1 }), 'text-mute')}>
                      <UserIcon className={classNames('h-4 w-4')} />
                      <span className="w-[104px] overflow-hidden text-ellipsis whitespace-pre text-sm">My Account</span>
                    </div>
                    )}
                  </div>
                </StyledLink>
              </li>
            ))}
          </ul>
          <Button
            aria-label="scroll recent messages left"
            className={classNames(
              styles.flex({ cy: true }),
              'absolute top-0 left-0 h-full rounded-l bg-gradient-to-l from-transparent to-black/50 px-4 transition-opacity',
              showLeftScroll ? 'opacity-100' : 'pointer-events-none opacity-0',
            )}
            onPress={() => {
              const el = document.getElementById('recent-scroll');
              const container = document.getElementById('recent-scroll-container');
              if (container && el) el.scrollBy({ left: -container.clientWidth * 0.75, behavior: 'smooth' });
            }}
            excludeFromTabOrder
          >
            <ChevronLeftIcon className={classNames(styles.largeIcon)} />
          </Button>
          <Button
            aria-label='scroll recent messages right'
            className={classNames(
              styles.flex({ cy: true }),
              'absolute top-0 right-0 h-full rounded-r bg-gradient-to-r from-transparent to-black/50 px-4 transition-opacity',
              showRightScroll ? 'opacity-100' : 'pointer-events-none opacity-0',
            )}
            onPress={() => {
              const el = document.getElementById('recent-scroll');
              const container = document.getElementById('recent-scroll-container');
              if (container && el) el.scrollBy({ left: container.clientWidth * 0.75, behavior: 'smooth' });
            }}
            excludeFromTabOrder
          >
            <ChevronRightIcon className={classNames(styles.largeIcon)} />
          </Button>
        </div>
      </ContainerSection>
      <ContainerSection>
        <NullableComponent show={mounted}>
          <SectionHeader>
            <HeaderTitle id="servers-title" title="Servers" Icon={DiscordIcon} />
            <div className='flex'>
              <Button
                onPress={toggleListView}
                className={classNames(styles.button.icon, 'rounded-full')}
                tooltip={listView === 'grid' ? 'List View' : 'Grid View'}
                aria-label="toggle server list view"
              >
                {listView === 'grid' && <ListBulletIcon className={styles.icon} />}
                {listView === 'list' && <Squares2X2Icon className={styles.icon} />}
              </Button>
              <Button
                onPress={toggleOrderNameAsc}
                className={classNames(styles.button.icon, 'rounded-full')}
                tooltip={order === 'asc' ? 'Name Descending' : 'Name Ascending'}
                aria-label={order === 'asc' ? 'toggle server list name descending' : 'toggle server list name ascending'}
              >
                <BarsArrowDownIcon className={styles.icon} />
              </Button>
            </div>
          </SectionHeader>
          <NullableComponent show={listView === 'list'}>
            <ul aria-labelledby='servers-title' className={classNames(styles.flex({ col: true }))}>
              <li>
                <StyledLink
                  href="/message/f/0"
                  className={classNames(styles.flex({ gap: 4, cy: true }), styles.button.primaryHover, 'group w-full rounded-md p-2')}
                >
                  <UserIcon className={classNames('h-8 w-8 rounded-full')} />
                  <span className='text-center text-sm group-hover:brightness-125'>My Account</span>
                </StyledLink>
              </li>
              <div className='h-[2px] w-full bg-primary' />
              {guilds.map((guild) => (
                <li key={guild.id}>
                  <StyledLink
                    href={`/message/f/${guild.id}`}
                    className={classNames(styles.flex({ gap: 4, cy: true }), styles.button.primaryHover, 'group w-full rounded-md p-2')}
                  >
                    <Image
                      aria-hidden
                      unoptimized={!!guild.icon}
                      blurDataURL={BLUR_DATA_URL}
                      priority
                      src={constructGuildIcon(guild, 32)}
                      width={32}
                      height={32}
                      alt={guild.name}
                      className={classNames('h-8 w-8 rounded-full')}
                    />
                    <div className='text-center text-sm group-hover:brightness-125'>{guild.name}</div>
                  </StyledLink>
                </li>
              ))}
            </ul>
          </NullableComponent>
          <NullableComponent show={listView === 'grid'}>
            <div className={classNames(styles.flex({ wrap: true, cx: true }), 'gap-y-2')}>
              <StyledLink
                href="/message/f/0"
                className={classNames(
                  styles.flex({ col: true, cx: true, gap: 2 }),
                  styles.button.primaryHover,
                  'group w-32 overflow-hidden rounded-md border-4 border-solid border-primary py-4 px-2 mobile:w-28',
                )}
              >
                <UserIcon className="h-24 w-24 mobile:h-20 mobile:w-20" />
                <div className='text-center text-sm group-hover:brightness-125'>My Account</div>
              </StyledLink>
              {guilds.map((guild) => (
                <StyledLink
                  key={guild.id}
                  href={`/message/f/${guild.id}`}
                  className={classNames(
                    styles.flex({ col: true, cx: true, gap: 2 }),
                    styles.button.primaryHover,
                    'group w-32 overflow-hidden rounded-md py-4 px-2 mobile:w-28',
                  )}
                >
                  <Image
                    aria-hidden
                    unoptimized={!!guild.icon}
                    blurDataURL={BLUR_DATA_URL}
                    priority
                    src={constructGuildIcon(guild, isMobile ? 96 : 80)}
                    width={isMobile ? 96 : 80}
                    height={isMobile ? 96 : 80}
                    alt={guild.name}
                    className="h-24 w-24 rounded-full mobile:h-20 mobile:w-20"
                  />
                  <div
                    style={{
                      display: '-webkit-box',
                      WebkitLineClamp: 2,
                      lineClamp: 2,
                      WebkitBoxOrient: 'vertical',
                      wordBreak: 'break-word',
                    }}
                    className='overflow-hidden text-ellipsis text-center text-sm group-hover:brightness-125'
                  >
                    {guild.name}
                  </div>
                </StyledLink>
              ))}
            </div>
          </NullableComponent>
        </NullableComponent>
      </ContainerSection>
      <NewMessageModal
        open={newMessageModalOpen}
        onClose={closeNewMessageModal}
      />
    </Container>
  );
};

export default Page;

