import { FloatingPortal } from '@floating-ui/react';
import { Transition } from '@headlessui/react';
import classNames from 'classnames';
import {
  Fragment, isValidElement, memo, useCallback, useMemo,
} from 'react';
import { useId } from 'react-aria';

import Arrow from '../Arrow';

import renderTrap from './renderTrap';
import { usePopoverState } from './utils';

import type { TransitionClasses, TransitionEvents } from '@headlessui/react';
import type {
  ElementType, HTMLProps, ReactElement, ReactNode, Ref,
} from 'react';

import { extractKeys } from '~/utils';
import { useMounted } from '~/utils/hooks';

const SHADOW_STYLE = 'shadow-md drop-shadow';

function renderPortal(
  children: ReactElement,
  isMounted: boolean,
  isPortal: string | boolean | undefined,
) {
  if (isMounted && isPortal) {
    const root = document.querySelector(isPortal === true ? 'body' : isPortal);
    return root ? <FloatingPortal>{children}</FloatingPortal> : children;
  }
  return children;
}

type TransitionProps = TransitionClasses & TransitionEvents & {
  appear?: boolean;
};

interface Props extends Omit<HTMLProps<HTMLDivElement>, 'as' | 'children' | 'className'>, Omit<TransitionProps, 'children' | 'className'> {
  transitionAs?: ElementType;
  as?: ElementType;
  forwardedRef?: Ref<HTMLElement> | ((instance: HTMLElement | null) => void);
  portal?: boolean | string;
  zIndex?: string | number;
  children: ReactNode | ((props: { close: () => void }) => ReactElement);
  className?: string;
  trapFocus?: boolean;
  focusContain?: boolean;
  focusRestore?: boolean;
}

const AnchoredPopoverChild: FC<Props> = (props) => {
  let [transitionProps, {
    transitionAs = 'div', as: childAs, children, zIndex, portal, style,
    trapFocus = false, focusContain = true, focusRestore = false,
    autoFocus = true, className, forwardedRef,
    ...floatProps
  }] = extractKeys(props, [
    'enter',
    'enterFrom',
    'enterTo',
    'entered',
    'leave',
    'leaveFrom',
    'leaveTo',
    'beforeEnter',
    'afterEnter',
    'beforeLeave',
    'afterLeave',
    'appear',
  ]);

  const isMounted = useMounted();
  const state = usePopoverState();

  const {
    x, y, strategy, middlewareData, placement, open, getFloatingProps,
    refs: { setFloating: floating },
    setOpen: stateSetOpen, arrowRef, arrow, dataState, flipped,
  } = state;

  const setOpen = useCallback(() => { stateSetOpen(true); }, [stateSetOpen]);
  const setClose = useCallback(() => { stateSetOpen(false); }, [stateSetOpen]);

  children = useMemo<ReactElement | ReactNode>(() => (typeof children === 'function' ? children({ close: setClose }) : children), [children, setClose]);

  const stateProps: Record<string, string> = {};
  if (dataState && state.open) stateProps[`data-${dataState}-state`] = 'true';
  const floatingProps = {
    ref: floating,
    id: useId(),
    style: {
      position: strategy,
      top: y ?? 0,
      left: x ?? 0,
      width: 'max-content',
      zIndex: zIndex ?? 10,
    },
    ...stateProps,
    suppressHydrationWarning: true,
  };

  const trapProps = trapFocus
    ? { contain: focusContain, restoreFocus: focusRestore, autoFocus }
    : undefined;
  let child;
  if (childAs === Fragment) {
    if (!isValidElement(children)) throw Error('<AnchorPopover.Child as={Fragment} /> must have a single child.');
    child = (
      <Transition
        as={transitionAs}
        show={isMounted ? open : false}
        data-flipped-state={flipped}
        beforeEnter={setOpen}
        beforeLeave={setClose}
        {...transitionProps}
        {...floatingProps}
      >
        {renderTrap(
          <children.type
            {...(children.props as Record<string, unknown>)}
            key={(children.props as Record<string, unknown>).key as string}
            style={style}
            // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
            className={classNames(
              (children.props as Record<string, unknown>).className as string,
              SHADOW_STYLE,
              className,
            )}
            {...getFloatingProps(floatProps)}
            ref={forwardedRef}
          />,
          trapProps,
        )}
      </Transition>
    );
  } else {
    const FloatingWrapper = childAs ?? 'div';
    child = (
      <FloatingWrapper
        {...getFloatingProps(floatProps)}
        {...floatingProps}
      >
        <Transition
          as={transitionAs}
          show={isMounted ? open : false}
          data-flipped-state={flipped}
          beforeEnter={setOpen}
          beforeLeave={setClose}
          {...transitionProps}
          style={style}
          className={classNames(SHADOW_STYLE, className)}
          ref={forwardedRef}
        >
          {!arrow ? null : (
            <Arrow
              arrow={middlewareData.arrow}
              arrowRef={arrowRef}
              placement={placement}
              fill="var(--background-tertiary)"
              size={60}
            />
          )}
          {renderTrap(children, trapProps)}
        </Transition>
      </FloatingWrapper>
    );
  }

  return renderPortal(
    child,
    isMounted,
    portal,
  );
};

export default memo(AnchoredPopoverChild);

/* eslint-disable @typescript-eslint/no-unsafe-argument */
import {
  cloneElement, Fragment, isValidElement, memo, useMemo,
} from 'react';
import { mergeRefs } from 'react-merge-refs';

import { usePopoverState } from './utils';

import type {
  ElementType, FC, HTMLProps, Ref,
} from 'react';

import Button, { type Props as ButtonProps } from '~/components/Button';

interface Props extends Omit<HTMLProps<HTMLElement>, 'as' | 'label' | 'ref'>,
Pick<ButtonProps, 'isDisabled' | 'tooltip'> {
  forwardedRef?: Ref<HTMLElement> | ((instance: HTMLElement | null) => void);
  as?: ElementType;
}

function replaceOnclickWithOnPress(props: Record<string, unknown>, toggleOpen: () => void) {
  if (props.onClick) {
    delete props.onClick;
    delete props.onKeyDown;
    delete props.onKeyUp;
  }
  props.onPress = toggleOpen;
}

const AnchoredPopoverTrigger: FC<Props> = ((allProps) => {
  const {
    children, as: childAs, forwardedRef, isDisabled, tooltip, ...props
  } = allProps;

  const state = usePopoverState();

  // In React 19, ref is a regular prop accessible via props.ref
  const childrenRef = isValidElement(children)
    ? (children.props as Record<string, unknown>).ref as Ref<HTMLElement> | undefined
    : undefined;
  const ref = useMemo(
    () => mergeRefs([state.refs.setReference, forwardedRef, childrenRef]),
    [state.refs.setReference, forwardedRef, childrenRef],
  );

  const stateProps: Record<string, string> = {};
  if (state.dataState && state.open) stateProps[`data-${state.dataState}-state`] = 'true';

  const floatingProps: Record<string, unknown> = {
    ref,
    ...state.getReferenceProps(props),
    ...stateProps,
    'data-headlessui-state': state.open ? 'open' : 'closed',
  };

  if (childAs === Fragment) {
    if (!isValidElement(children)) throw Error('<AnchorPopover.Trigger as={Fragment} /> must have a single child.');

    if (children.type === Button) {
      if (isDisabled !== undefined) floatingProps.isDisabled = isDisabled;
      if (tooltip !== undefined) floatingProps.tooltip = tooltip;
      replaceOnclickWithOnPress(floatingProps, state.toggleOpen);
    } else if ((isDisabled !== undefined || tooltip !== undefined) && children.type !== Button) {
      throw Error('<AnchorPopover.Trigger as={Fragment} /> can only have isDisabled or tooltip prop if child is a <Button />.');
    }
    return cloneElement(children, { ...(children.props as Record<string, unknown>), ...floatingProps });
  }

  const TriggerWrapper = childAs ?? Button;
  if (TriggerWrapper === Button) {
    if (isDisabled !== undefined) floatingProps.isDisabled = isDisabled;
    if (tooltip !== undefined) floatingProps.tooltip = tooltip;
    replaceOnclickWithOnPress(floatingProps, state.toggleOpen);
  } else if ((isDisabled !== undefined || tooltip !== undefined) && TriggerWrapper !== Button) {
    throw Error('<AnchorPopover.Trigger /> can only have isDisabled or tooltip prop if as={undefined || Button}.');
  }

  return (
    <TriggerWrapper {...floatingProps}>{children}</TriggerWrapper>
  );
});
AnchoredPopoverTrigger.displayName = 'AnchoredPopoverTrigger';

export default memo(AnchoredPopoverTrigger);

import {
  autoUpdate,
  flip, shift,
  arrow as useArrow,
  useClick, useDismiss,
  useFloating, useInteractions, useRole,
} from '@floating-ui/react';
import {
  createContext, use, useCallback, useEffect, useMemo, useRef,
} from 'react';

import type { Placement } from '@floating-ui/react';
import type { RefObject } from 'react';

import { useToggleState } from '~/utils/hooks';

export interface AnchoredPopoverOptions {
  initialOpen?: boolean;
  placement?: Placement;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  arrow?: boolean;
  dataState?: string;
  anchorElementId?: string;
  // position?: { x: number, y: number }; // Will need to be fixed.
}

export type AnchoredPopoverContextType = ReturnType<typeof usePopover & {
  arrowRef: RefObject<HTMLDivElement | null>;
  arrow?: boolean;
  flipped: boolean;
}>;

export const AnchoredPopoverContext = createContext<AnchoredPopoverContextType | null>(null);
export const usePopoverState = () => {
  const context = use(AnchoredPopoverContext);

  if (context == null) {
    throw new Error('AnchoredPopover components must be wrapped in <AnchoredPopover />');
  }

  return context;
};

export function usePopover({
  initialOpen = false,
  placement = 'top',
  open: controlledOpen,
  onOpenChange: setControlledOpen,
  arrow = false,
  dataState,
  anchorElementId,
  // position,
}: AnchoredPopoverOptions = {}) {
  const arrowRef = useRef<HTMLDivElement>(null);
  const [uncontrolledOpen, { set: setUncontrolledOpen, toggle }] = useToggleState(initialOpen);

  const open = controlledOpen ?? uncontrolledOpen;
  const setOpen = setControlledOpen ?? setUncontrolledOpen;
  const uncontrolledToggle = useCallback(() => setOpen(!open), [open]);
  const toggleOpen = setControlledOpen ? uncontrolledToggle : toggle;

  const _arrow = useArrow({ element: arrowRef });

  const data = useFloating(useMemo(() => ({
    placement,
    open,
    onOpenChange: setOpen,
    whileElementsMounted: autoUpdate,
    middleware: [flip(), shift(), arrow && _arrow],
  }), [open, placement, setOpen, arrow, _arrow]));

  // if (data.refs.reference.current && data.refs.floating.current && open) {
  //   computePosition(
  //     data.refs.reference.current,
  //     data.refs.floating.current,
  //     { placement },
  //   ).then((d) => {
  //     if (open && (d.x !== data.x || d.y !== data.y)) {
  //       console.log('update');
  //       data.update();
  //     }
  //   }).catch(console.error);
  // }

  useEffect(() => {
    if (anchorElementId) {
      const element = document.getElementById(anchorElementId);
      if (element) data.refs.setPositionReference(element);
    }
  }, [anchorElementId]);

  const { context } = data;

  const click = useClick(context, { enabled: !controlledOpen });
  const dismiss = useDismiss(context);
  const role = useRole(context);

  const interactions = useInteractions([click, dismiss, role]);

  // flipped currently only works on leave seemingly due to placement not changing until after
  // the transition has already started
  const flipped = placement !== data.placement;

  return useMemo(
    () => ({
      open,
      setOpen,
      toggleOpen,
      ...interactions,
      ...data,
      flipped,
      arrowRef,
      arrow,
      dataState,
      // x: position?.x ?? data.x,
      // y: position?.y ?? data.y,
    }),
    open
      ? [open, setOpen, toggleOpen, interactions, open && data, arrow && arrowRef.current, flipped]
      : [null, null, null, null, null, null, null],
  );
}

