import { XMarkIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import {
  createContext, memo, use, useEffect, useMemo, useRef, useState,
} from 'react';
import { FocusScope, useId } from 'react-aria';
import { createPortal } from 'react-dom';

import Button from './Button';

import type {
  ComponentClass, Dispatch, FC, PropsWithChildren, RefObject, SetStateAction,
} from 'react';

import styles from '~/styles';
import { useWindowEventListener } from '~/utils/hooks';

function tryHideSidebar() {
  const menuBar = document.getElementById('menu-bar');
  if (!menuBar) return setTimeout(() => { tryHideSidebar(); }, 50);
  menuBar.style.display = 'none';
  return undefined;
}

interface BottomPortalContext {
  childrenProps: PropsWithChildren<Props>[] | undefined;
  portalRef: RefObject<HTMLDivElement | null>;
  setChildrenProps: Dispatch<SetStateAction<PropsWithChildren<Props>[]>>;
}

const BottomPortalContext = createContext<BottomPortalContext | null>(null);
const useBottomPortalState = () => {
  const context = use(BottomPortalContext);
  if (!context) throw new Error('useBottomPortalState must be used within a BottomPortal');
  return context;
};
const useBottomPortalContext = () => {
  const [childrenProps, setChildrenProps] = useState<PropsWithChildren<Props>[]>([]);
  const portalRef = useRef<HTMLDivElement>(null);

  const currentChild = childrenProps.at(-1);
  useWindowEventListener('mouseup', (e) => {
    if (currentChild && !portalRef.current?.contains(e.target as Node)) {
      currentChild.setOpen(false);
    }
  }, [portalRef.current, currentChild], { capture: true });
  useWindowEventListener('pointerup', (e) => {
    if (currentChild && !portalRef.current?.contains(e.target as Node)) {
      currentChild.setOpen(false);
    }
  }, [portalRef.current, currentChild], { capture: true });

  useEffect(() => {
    if (childrenProps.length) {
      const timeout = tryHideSidebar();

      return () => {
        clearTimeout(timeout);
        const menuBar = document.getElementById('menu-bar');
        if (menuBar) menuBar.style.display = '';
      };
    }

    return undefined;
  }, [!!childrenProps.length]);

  return useMemo(() => ({
    childrenProps,
    portalRef,
    setChildrenProps,
  }), [childrenProps, portalRef]);
};

export const BottomPortalProvider: FC<PropsWithChildren> = ({ children }) => {
  const value = useBottomPortalContext();

  return (
    <BottomPortalContext.Provider value={value}>
      {children}
    </BottomPortalContext.Provider>
  );
};

const Inner: FC<PropsWithChildren<Props> & {
  show: boolean;
  portalRef: undefined | RefObject<HTMLDivElement | null>;
}> = (props) => {
  const {
    title, TitleIcon, description, children, show, portalRef, overlay, setOpen,
  } = props;

  return !children ? null : createPortal(
    <div className={classNames('bg-primary', !show && 'hidden')}>
      <FocusScope contain>
        <div ref={portalRef} className='relative z-10 border-t border-solid border-tertiary bg-primary'>
          <div className='m-2'>
            <div className={styles.flex({ c: true, btw: true })}>
              <h2 className={classNames(styles.flex({ cy: true, gap: 2 }), 'font-semibold leading-none text-mute')}>
                {TitleIcon && <TitleIcon className='h-5 w-5' />}
                {title}
              </h2>
              <Button aria-label="close" onPress={() => setOpen(false)}>
                <XMarkIcon className={styles.icon} />
              </Button>
            </div>
            <div>
              {description && <div className="text-xs leading-tight text-mute">{description}</div>}
            </div>
          </div>
          {children}
        </div>
      </FocusScope>
      {overlay && <div className="pointer-events-auto absolute inset-0 bg-black/80" />}
    </div>,
    document.getElementById('app-container') as HTMLElement,
  );
};

export const BottomPortalContainer: FC = () => {
  const { childrenProps, portalRef } = useBottomPortalState();

  return childrenProps?.map((props, i) => (!props.open ? null : (
    <Inner
      {...props}
      portalRef={i === childrenProps.length - 1 ? portalRef : undefined}
      key={props.id}
      show={i === childrenProps.length - 1}
    />
  ))) ?? null;
};

interface Props {
  id?: string;
  open: boolean;
  title: string;
  TitleIcon?:
  | FC<{ className?: undefined | string }>
  | ComponentClass<{ className?: undefined | string }>;
  description?: string;
  setOpen: (open: boolean) => void;
  level: number;
  overlay?: boolean;
}

const BottomPortal: FC<PropsWithChildren<Props>> = (props) => {
  const { open, id: propsId, level } = props;
  const { setChildrenProps } = useBottomPortalState();

  const id = useId(propsId);

  useEffect(() => {
    if (open) {
      setChildrenProps((prev) => {
        const newChildrenProps = [...prev];
        // eslint-disable-next-line react/destructuring-assignment
        const updateIdx = newChildrenProps.findIndex((p) => p.id === id);
        if (updateIdx !== -1) {
          newChildrenProps.splice(updateIdx, 1, { ...props, id });
          return newChildrenProps;
        }

        const replaceIdx = newChildrenProps.findIndex((p) => p.level === level);
        if (replaceIdx !== -1) {
          const oldChild = newChildrenProps.splice(replaceIdx, 1, { ...props, id })[0];
          setTimeout(() => oldChild.setOpen(false));
          return newChildrenProps.filter((p) => p.level <= level);
        }

        newChildrenProps.push({ ...props, id });
        return newChildrenProps;
      });
    } else {
      setChildrenProps((prev) => (
        prev.some((p) => p.id === id) ? prev.filter((p) => p.id !== id) : prev
      ));
    }
  }, [...Object.values(props)]);

  useEffect(() => () => {
    setChildrenProps((prev) => (
      prev.some((p) => p.id === id) ? prev.filter((p) => p.id !== id) : prev
    ));
  }, []);

  return null;
};

export default memo(BottomPortal);

import { endOfMonth, getWeeksInMonth } from '@internationalized/date';
import { useCalendarGrid, useLocale } from 'react-aria';

import CalendarCell from './CalendarCell';

import type { CalendarState } from 'react-stately';

interface Props {
  state: CalendarState;
  offset?: { months?: number, weeks?: number, days?: number };
}

const CalendarGrid: FC<Props> = ({ state, offset = {} }) => {
  const { locale } = useLocale();
  const startDate = state.visibleRange.start.add(offset);
  const endDate = endOfMonth(startDate);
  const { gridProps, headerProps, weekDays } = useCalendarGrid({ startDate, endDate }, state);

  // Get the number of weeks in the month so we can render the proper number of rows.
  const weeksInMonth = getWeeksInMonth(startDate, locale);

  return (
    <table {...gridProps} cellPadding="0" className="flex-1">
      <thead {...headerProps} className="text-mute">
        <tr>
          {weekDays.map((day, index) => (
            <th key={index}><div className='flex justify-center'>{day}</div></th>
          ))}
        </tr>
      </thead>
      <tbody>
        {[...new Array(weeksInMonth).keys()].map((weekIndex) => (
          <tr key={weekIndex}>
            {state
              .getDatesInWeek(weekIndex, startDate)
              .map((date, i) => (date ? (
                <CalendarCell
                  key={i}
                  state={state}
                  date={date}
                  currentMonth={startDate}
                />
              ) : (
                <td key={i} />
              )))}
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default CalendarGrid;

