import classNames from 'classnames';
import {
  memo, useEffect, useRef,
} from 'react';
import { useId, useTextField } from 'react-aria';

import type { AriaTextFieldProps } from 'react-aria';
import type { Ref } from 'react';

type Props = AriaTextFieldProps & {
  inputMode: Required<AriaTextFieldProps>['inputMode'];
  value: string;
  fragment?: boolean;
  outerClassName?: string;
  labelClassName?: string;
  inputClassName?: string;
  descriptionClassName?: string;
  errorClassName?: string;
};

function ContentEditable({ ref: propRef, ...props }: Props & { ref?: Ref<HTMLDivElement> }) {
  const {
    label, fragment, description, errorMessage, outerClassName, labelClassName,
    inputClassName, descriptionClassName, errorClassName,
  } = props;

  if (fragment && outerClassName) throw new Error('Cannot use outerClassName with fragment');

  const localRef = useRef<HTMLDivElement>(propRef && typeof propRef !== 'function' ? propRef.current : null);

  const {
    labelProps, inputProps, descriptionProps, errorMessageProps,
    // @ts-expect-error brute-force ref
  } = useTextField({ ...props, id: useId(props.id) }, localRef);

  useEffect(() => {
    if (localRef.current && localRef.current.innerText !== inputProps.value) {
      localRef.current.innerText = inputProps.value as string;
    }
  }, [inputProps.value]);

  const body = (
    <>
      {label && <label className={labelClassName} {...labelProps}>{label}</label>}
      <div
        className={classNames(inputClassName, 'no-drag cursor-text text-inherit focus:rounded focus:ring')}
        {...inputProps}
        onInput={() => props.onChange?.(localRef.current?.textContent ?? '')}
        ref={localRef}
        contentEditable
      />
      {description && <div className={classNames('text-xs', descriptionClassName)} {...descriptionProps}>{description}</div>}
      {errorMessage && typeof errorMessage !== 'function' && <div className={classNames('px-2 text-xs font-semibold text-error', errorClassName)} {...errorMessageProps}>{errorMessage as React.ReactNode}</div>}
    </>
  );

  if (fragment) return body;

  return <div className={outerClassName}>{body}</div>;
}

export default memo(ContentEditable);

