import { act, useState } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import DiscordMessageEditor from '..';

import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';
import styles from '~/styles';
import {
  makeContainer, makeSection, makeTextDisplay,
} from '~/utils/__tests__/helpers/components';

interface ComponentStub {
  component: { _key: string };
  canDuplicate: boolean;
  canAddChild: boolean;
  actions: { duplicate: VoidFunction };
}

const stubs = vi.hoisted(() => ({
  components: new Map<string, unknown>(),
  author: [] as Array<{ hideValidation?: boolean }>,
  body: [] as Array<{ hideValidation?: boolean }>,
}));
const handle = { setCount: (_count: number) => {} };

vi.mock('../components/EmbedEditor', () => ({ default: () => null }));
vi.mock('../components/ComponentEditors/ComponentEditor', () => ({
  default: (props: ComponentStub) => {
    stubs.components.set(props.component._key, props);
    return null;
  },
}));
vi.mock('../components/ContentBody', () => ({
  default: (props: { hideValidation?: boolean }) => {
    stubs.body.push(props);
    return null;
  },
}));
vi.mock('../components/Author', () => ({
  default: (props: { hideValidation?: boolean }) => {
    stubs.author.push(props);
    return null;
  },
}));
vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));
vi.mock('~/providers/MarkdownProvider', () => ({
  useMarkdown: () => ({}),
}));

const ResizeObserverStub = function ResizeObserverStub() {
  return { observe() {}, unobserve() {}, disconnect() {} };
};

beforeEach(() => { vi.stubGlobal('ResizeObserver', ResizeObserverStub); });

afterEach(() => {
  vi.unstubAllGlobals();
  unmountDom();
  stubs.components.clear();
  stubs.author.length = 0;
  stubs.body.length = 0;
});

const keyed = (components: Array<Record<string, unknown>>) => components.map((c, i) => ({ ...c, _key: `c${i}` }));
const texts = (n: number) => Array.from({ length: n }, () => makeTextDisplay());

async function mountV2(
  components: Array<Record<string, unknown>>,
  setMessage: (message: EditableMessageData) => void = () => {},
) {
  const host = mountDom(
    <DiscordMessageEditor
      message={{ components: keyed(components) } as unknown as EditableMessageData}
      locale="en"
      editableState={{
        showEdit: true, messageMode: 'v2', showComponentsEditable: true,
      } as unknown as EditableState}
      setMessage={setMessage}
    />,
  );
  await act(async () => {});
  return host;
}

const hasAddButton = (host: HTMLElement) => host.textContent?.includes('Add Component') ?? false;
const errorLine = (host: HTMLElement) => Array.from(host.querySelectorAll('.text-error'))
  .map((el) => el.textContent)
  .find((text) => text?.startsWith('Message has '));

describe('DiscordMessageEditor component limit', () => {
  it.each([
    ['38 flat components', texts(38), true],
    ['39 flat components', texts(39), true],
    ['40 flat components', texts(40), false],
    ['41 flat components', texts(41), false],
    ['42 flat components', texts(42), false],
    ['a container holding 38 text displays (39 in all)', [makeContainer(texts(38))], true],
    ['a container holding 39 text displays (40 in all)', [makeContainer(texts(39))], false],
    ['a container holding 40 text displays (41 in all)', [makeContainer(texts(40))], false],
    ['9 containers of one section each (36 in all)', Array.from({ length: 9 }, () => makeContainer([makeSection(1)])), true],
    ['10 containers of one section each (40 in all)', Array.from({ length: 10 }, () => makeContainer([makeSection(1)])), false],
  ])('offers adds only below the limit: %s', async (_title, components, offered) => {
    const host = await mountV2(components);

    expect(hasAddButton(host)).toBe(offered);
    expect((stubs.components.get('c0') as ComponentStub).canDuplicate).toBe(offered);
    expect((stubs.components.get('c0') as ComponentStub).canAddChild).toBe(offered);
  });

  it.each([
    ['40 flat components', texts(40)],
    ['a container holding 39 text displays', [makeContainer(texts(39))]],
  ])('shows no error at the limit: %s', async (_title, components) => {
    const host = await mountV2(components);

    expect(errorLine(host)).toBeUndefined();
    expect(host.querySelector('.discord-visualizer__accessories')?.className).not.toContain(styles.errorBorder);
  });

  it.each([
    ['41 flat components', texts(41), 41],
    ['a container holding 40 text displays', [makeContainer(texts(40))], 41],
    ['11 containers of one section each', Array.from({ length: 11 }, () => makeContainer([makeSection(1)])), 44],
  ])('shows the total and the limit with a red border above the limit: %s', async (_title, components, total) => {
    const host = await mountV2(components);

    expect(errorLine(host)).toBe(`Message has ${total} components; the limit is 40.`);
    expect(host.querySelector('.discord-visualizer__accessories')?.className).toContain(styles.errorBorder);
  });
});

describe('DiscordMessageEditor component limit, the error line', () => {
  it('shows the components line after the text-length line', async () => {
    const host = await mountV2(Array.from({ length: 41 }, () => makeTextDisplay('x'.repeat(100))));

    expect(Array.from(host.querySelectorAll('.text-error')).map((el) => el.textContent)).toEqual([
      'Components text exceeds 4000 characters.',
      'Message has 41 components; the limit is 40.',
    ]);
  });

  it('drops the line and the border once the total is back to 40', async () => {
    const Host = () => {
      const [count, setCount] = useState(41);
      handle.setCount = setCount;
      return (
        <DiscordMessageEditor
          message={{ components: keyed(texts(count)) } as unknown as EditableMessageData}
          locale="en"
          editableState={{
            showEdit: true, messageMode: 'v2', showComponentsEditable: true,
          } as unknown as EditableState}
          setMessage={() => {}}
        />
      );
    };
    const host = mountDom(<Host />);
    await act(async () => {});
    expect(errorLine(host)).toBe('Message has 41 components; the limit is 40.');
    expect(host.querySelector('.discord-visualizer__accessories')?.className).toContain(styles.errorBorder);

    await act(async () => { handle.setCount(40); });

    expect(errorLine(host)).toBeUndefined();
    expect(host.querySelector('.discord-visualizer__accessories')?.className).not.toContain(styles.errorBorder);
  });
});

describe('DiscordMessageEditor component validity, the error line', () => {
  const errorLines = (host: HTMLElement) => Array.from(host.querySelectorAll('.text-error')).map((el) => el.textContent);
  const border = (host: HTMLElement) => host.querySelector('.discord-visualizer__accessories')?.className;

  async function mountWith(components: Array<Record<string, unknown>>, flags?: number) {
    const host = mountDom(
      <DiscordMessageEditor
        message={{ components: keyed(components), flags } as unknown as EditableMessageData}
        locale="en"
        editableState={{
          showEdit: true, messageMode: 'v2', showComponentsEditable: true,
        } as unknown as EditableState}
        setMessage={() => {}}
      />,
    );
    await act(async () => {});
    return host;
  }

  it('shows one line naming the Text Display, with a red border, for an empty Text Display', async () => {
    const host = await mountWith([makeTextDisplay('')]);

    expect(errorLines(host)).toHaveLength(1);
    expect(errorLines(host)[0]).toContain('Text Display');
    expect(border(host)).toContain(styles.errorBorder);
  });

  it('shows the line for an empty Action Row when only the V2 flag makes the message V2', async () => {
    const host = await mountWith([{ type: 1, components: [] }], 32768);

    expect(errorLines(host)).toHaveLength(1);
    expect(errorLines(host)[0]).toContain('Action Row');
  });

  it('shows no line for an empty Action Row in a classic message', async () => {
    const host = mountDom(
      <DiscordMessageEditor
        message={{ content: 'Hi', components: keyed([{ type: 1, components: [] }]) } as unknown as EditableMessageData}
        locale="en"
        setMessage={() => {}}
      />,
    );
    await act(async () => {});

    expect(errorLines(host)).toEqual([]);
  });

  it('shows the line after the components-total line', async () => {
    const host = await mountWith(Array.from({ length: 41 }, () => makeTextDisplay('')));

    const lines = errorLines(host);
    expect(lines).toHaveLength(2);
    expect(lines[0]).toBe('Message has 41 components; the limit is 40.');
    expect(lines[1]).toContain('Text Display');
  });

  it('drops the line once the Text Display is filled', async () => {
    const Host = () => {
      const [content, setContent] = useState('');
      handle.setCount = (n: number) => setContent('x'.repeat(n));
      return (
        <DiscordMessageEditor
          message={{
            components: keyed([makeTextDisplay(content)]),
          } as unknown as EditableMessageData}
          locale="en"
          editableState={{
            showEdit: true, messageMode: 'v2', showComponentsEditable: true,
          } as unknown as EditableState}
          setMessage={() => {}}
        />
      );
    };
    const host = mountDom(<Host />);
    await act(async () => {});
    expect(errorLines(host)).toHaveLength(1);

    await act(async () => { handle.setCount(3); });

    expect(errorLines(host)).toEqual([]);
    expect(border(host)).not.toContain(styles.errorBorder);
  });

  it('shows the line when the message is not being edited, as the send page preview does', async () => {
    const host = mountDom(
      <DiscordMessageEditor
        message={{ components: keyed([makeTextDisplay('')]) } as unknown as EditableMessageData}
        locale="en"
        setMessage={() => {}}
      />,
    );
    await act(async () => {});

    expect(errorLines(host)).toHaveLength(1);
    expect(border(host)).toContain(styles.errorBorder);
  });
});

describe('DiscordMessageEditor validation lines that precede the component lines', () => {
  it('shows the text-length line with a red border for Text Displays over 4000 characters', async () => {
    const host = await mountV2([makeTextDisplay('x'.repeat(4001))]);

    const lines = Array.from(host.querySelectorAll('.text-error')).map((el) => el.textContent);
    expect(lines).toEqual(['Components text exceeds 4000 characters.']);
    expect(host.querySelector('.discord-visualizer__accessories')?.className).toContain(styles.errorBorder);
  });
});

describe('DiscordMessageEditor error-line text', () => {
  const renderedText = async (message: Record<string, unknown>, hideValidation = false) => {
    const host = mountDom(
      <DiscordMessageEditor
        message={message as unknown as EditableMessageData}
        locale="en"
        hideValidation={hideValidation}
        setMessage={() => {}}
      />,
    );
    await act(async () => {});
    return host.querySelector('.discord-visualizer__message')?.textContent;
  };

  const cases: Array<[string, Record<string, unknown>, string]> = [
    ['no content', {}, 'Message must have content, embeds, or components.'],
    ['embed characters', { embeds: [{ _key: 'e0', description: 'x'.repeat(6001) }] }, 'Embeds exceed 6000 characters.'],
    ['displayable text', { components: keyed([makeTextDisplay('x'.repeat(4001))]) }, 'Components text exceeds 4000 characters.'],
    ['component count', { components: keyed(texts(41)) }, 'Message has 41 components; the limit is 40.'],
    ['V2 component reason', { components: keyed([makeTextDisplay('')]) }, 'A Text Display is empty.'],
  ];

  it.each(cases)('renders only the reason text for %s', async (_title, message, reason) => {
    expect(await renderedText(message)).toBe(reason);
  });

  it('renders no text when the message has no error', async () => {
    expect(await renderedText({ content: 'Hello' })).toBe('');
  });

  it.each(cases)('renders no text for %s when validation is hidden', async (_title, message) => {
    expect(await renderedText(message, true)).toBe('');
  });
});

describe('DiscordMessageEditor hideValidation', () => {
  const editable = { showEdit: true, messageMode: 'v2', showComponentsEditable: true } as unknown as EditableState;
  const mountWith = async (hideValidation: boolean | undefined, editableState?: EditableState) => {
    mountDom(
      <DiscordMessageEditor
        message={{ components: [] } as unknown as EditableMessageData}
        locale="en"
        editableState={editableState}
        hideValidation={hideValidation}
        setMessage={() => {}}
      />,
    );
    await act(async () => {});
  };

  it.each([true, false])('gives the V2 editing Author hideValidation %s', async (hide) => {
    await mountWith(hide, editable);

    expect(stubs.author.at(-1)?.hideValidation).toBe(hide);
  });

  it.each([false])('gives the message body hideValidation %s', async (hide) => {
    await mountWith(hide);

    expect(stubs.body.at(-1)?.hideValidation).toBe(hide);
  });
});

describe('DiscordMessageEditor adds from 39 components', () => {
  it.each([
    ['Section', 9, 'accessory'],
    ['Container', 17, 'components'],
    ['Action Row', 1, 'components'],
  ])('completes an Add Component %s in full', async (label, type, part) => {
    const setMessage = vi.fn();
    const host = await mountV2(texts(39), setMessage);

    const open = Array.from(host.querySelectorAll('button'))
      .find((b) => b.textContent?.includes('Add Component')) as HTMLElement;
    act(() => { open.click(); });
    const item = Array.from(document.body.querySelectorAll('button'))
      .find((b) => b.textContent === label) as HTMLElement;
    act(() => { item.click(); });

    expect(setMessage).toHaveBeenCalledOnce();
    const sent = setMessage.mock.calls[0][0] as EditableMessageData;
    const next = sent.components as Array<Record<string, unknown>>;
    expect(next).toHaveLength(40);
    expect(next[39].type).toBe(type);
    expect(next[39][part]).toBeTruthy();
  });

  it('duplicates a container with all of its children', async () => {
    const setMessage = vi.fn();
    await mountV2([makeContainer(texts(3)), ...texts(34)], setMessage);

    (stubs.components.get('c0') as ComponentStub).actions.duplicate();

    const sent = setMessage.mock.calls[0][0] as EditableMessageData;
    const next = sent.components as Array<Record<string, unknown>>;
    expect(next).toHaveLength(36);
    expect((next[1].components as unknown[])).toHaveLength(3);
  });
});

describe('DiscordMessageEditor component limit when not editing', () => {
  it('shows the total and the limit with a red border when validation is not hidden', async () => {
    const host = mountDom(
      <DiscordMessageEditor
        message={{ components: keyed(texts(41)) } as unknown as EditableMessageData}
        locale="en"
        setMessage={() => {}}
      />,
    );
    await act(async () => {});

    expect(errorLine(host)).toBe('Message has 41 components; the limit is 40.');
    expect(host.querySelector('.discord-visualizer__accessories')?.className).toContain(styles.errorBorder);
  });
});

describe('DiscordMessageEditor mount callback', () => {
  it('calls onMount once after mounting and not again when it re-renders', async () => {
    const onMount = vi.fn();
    const Host = () => {
      const [count, setCount] = useState(1);
      handle.setCount = setCount;
      return (
        <DiscordMessageEditor
          message={{ components: keyed(texts(count)) } as unknown as EditableMessageData}
          locale="en"
          setMessage={() => {}}
          onMount={onMount}
        />
      );
    };
    mountDom(<Host />);
    await act(async () => {});

    expect(onMount).toHaveBeenCalledTimes(1);

    await act(async () => { handle.setCount(2); });

    expect(onMount).toHaveBeenCalledTimes(1);
  });
});

'use client';

import {
  FloatingFocusManager, FloatingList, FloatingPortal,
  flip, shift,
  useClick, useDismiss, useFloating, useInteractions,
  useListItem, useListNavigation, useRole,
} from '@floating-ui/react';
import { Cog6ToothIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import {
  createContext, memo, use, useRef, useState,
} from 'react';

import type { FC as IconFC, PropsWithChildren } from 'react';

import styles from '~/styles';

interface MenuContext {
  getItemProps: ReturnType<typeof useInteractions>['getItemProps'];
  activeIndex: number | null;
}

const ActionsMenuContext = createContext<MenuContext | null>(null);

interface ItemProps {
  label: string;
  Icon?: IconFC<{ className?: string }>;
  onPress: VoidFunction;
  disabled?: boolean;
  danger?: boolean;
  active?: boolean;
}

const ActionsMenuItem: FC<ItemProps> = ({
  label, Icon, onPress, disabled, danger, active,
}) => {
  const ctx = use(ActionsMenuContext);
  if (!ctx) throw new Error('ActionsMenu.Item must be used inside ActionsMenu');
  const { ref, index } = useListItem();
  const isActive = ctx.activeIndex === index;

  return (
    <button
      ref={ref}
      type="button"
      role="menuitem"
      tabIndex={isActive ? 0 : -1}
      disabled={disabled}
      className={classNames(
        'flex w-full items-center gap-2 px-3 py-1.5 text-left text-sm',
        danger
          ? 'text-red-400 hover:bg-red-500/10'
          : 'text-header-primary hover:bg-modifier-hover',
        (active || isActive) && 'bg-modifier-hover',
        disabled && 'cursor-not-allowed opacity-50',
      )}
      {...ctx.getItemProps({
        onClick: disabled ? undefined : onPress,
      })}
    >
      {Icon && <Icon className={styles.smallIcon} />}
      {label}
    </button>
  );
};

const ActionsMenuDivider = () => (
  <div role="separator" className="my-1 border-t border-tertiary" />
);

interface Props {
  label: string;
}

const ActionsMenu: FC<PropsWithChildren<Props>> = ({ children, label }) => {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const listRef = useRef<(HTMLElement | null)[]>([]);

  const { refs, floatingStyles, context } = useFloating({
    open,
    onOpenChange: setOpen,
    placement: 'left-start',
    middleware: [flip(), shift()],
  });

  const click = useClick(context);
  const dismiss = useDismiss(context, {
    outsidePress: (event) => {
      const target = event.target as HTMLElement;
      return !target.closest('[data-floating-ui-portal]');
    },
  });
  const role = useRole(context, { role: 'menu' });
  const listNav = useListNavigation(context, {
    listRef,
    activeIndex,
    onNavigate: setActiveIndex,
    loop: true,
  });

  const { getReferenceProps, getFloatingProps, getItemProps } = useInteractions([
    click, dismiss, role, listNav,
  ]);

  return (
    <div className="relative">
      <button
        ref={refs.setReference}
        type="button"
        aria-label={`${label} actions`}
        className='block rounded p-0.5'
        {...getReferenceProps()}
      >
        <Cog6ToothIcon className={styles.icon} />
      </button>
      {open && (
        <FloatingPortal>
          <FloatingFocusManager context={context} modal={false}>
            <div
              ref={refs.setFloating}
              style={floatingStyles}
              className={classNames(
                'z-10',
                'min-w-[11rem] rounded-md border border-tertiary',
                'bg-secondary py-1 shadow-lg',
              )}
              {...getFloatingProps()}
            >
              <ActionsMenuContext value={{ getItemProps, activeIndex }}>
                <FloatingList elementsRef={listRef}>
                  {children}
                </FloatingList>
              </ActionsMenuContext>
            </div>
          </FloatingFocusManager>
        </FloatingPortal>
      )}
    </div>
  );
};

ActionsMenu.displayName = 'ActionsMenu';

export default Object.assign(memo(ActionsMenu), {
  Item: ActionsMenuItem,
  Divider: ActionsMenuDivider,
});

