'use client';

import classNames from 'classnames';
import dayjs from 'dayjs';
import Image from 'next/image';
import {
  memo, useCallback, useEffect, useState,
} from 'react';

import Button from '~/components/Button';
import ContentEditable from '~/components/ContentEditable';
import ImageUploader from '~/components/dynamics/ImageUploader';
import { BLUR_DATA_URL, DEFAULT_IMAGE_URL, MINUTE_IN_MILLISECONDS } from '~/constants';
import styles from '~/styles';
import { validateUsername } from '~/utils';
import { useToggleState } from '~/utils/hooks';
import timestampToString from '~/utils/timestampToString';

const DEFAULT_USERNAME = 'Captain Hook';

export interface Props {
  visualStyle: DiscordMessageStyle;
  username: string;
  avatarUrl: string;
  showEdit: boolean;
  hideValidation?: boolean;
  setUsername: (str: string) => void;
  setAvatarUrl: (str: string) => void;
}

const Author: FC<Props> = ({
  visualStyle, username, avatarUrl, showEdit, hideValidation = false, setUsername, setAvatarUrl,
}) => {
  const [showImageUpload, {
    setTrue: setShowImageUpload,
    setFalse: unsetShowImageUpload,
  }] = useToggleState();
  const [ts, setTs] = useState<Date>(() => {
    const tmp = new Date();
    tmp.setHours(0, 0, 0, 0);
    return tmp;
  });

  useEffect(() => {
    setTs(new Date());
    let interval: undefined | ReturnType<typeof setInterval>;
    const timeout = setTimeout(() => {
      interval = setInterval(() => { setTs(new Date()); }, MINUTE_IN_MILLISECONDS);
    }, MINUTE_IN_MILLISECONDS - (new Date().getSeconds() * 1000) - new Date().getMilliseconds());
    return () => {
      clearTimeout(timeout);
      clearInterval(interval);
    };
  }, []);

  const error = hideValidation ? '' : validateUsername(username);
  const wrappedSetUsername = useCallback<(s: string) => void>((value) => setUsername(value.replace(/\s+/g, ' ').trimStart()), [setUsername]);

  const usernameComponent = showEdit ? (
    <ContentEditable
      inputMode='text'
      aria-label="message username"
      inputClassName={classNames('discord-visualizer__username', styles.clickable, styles.errorStateBorder)}
      value={username}
      placeholder={DEFAULT_USERNAME}
      onChange={wrappedSetUsername}
      data-erroring-state={error ? true : undefined}
      fragment
    />
  ) : (
    <span className="discord-visualizer__username">
      {username}
    </span>
  );

  const botTagComponent = (
    <span className="discord-visualizer__username-bot-tag">
      <span className="discord-visualizer__username-bot-tag-inner">
        BOT
      </span>
    </span>
  );

  const timeComponent = (
    <span className="discord-visualizer__timestamp">
      <time dateTime={ts.toISOString()}>{visualStyle === 'cozy' ? timestampToString(ts) : dayjs(ts).format('LT')}</time>
    </span>
  );

  const setImage = useCallback<(url: string) => void>((dataURL) => { setAvatarUrl(dataURL); }, [setAvatarUrl]);

  const avatar = showEdit ? (
    <Button
      className={classNames('discord-visualizer__avatar-outer', showEdit && styles.dimHover)}
      onPress={showEdit ? setShowImageUpload : undefined}
      aria-label="edit avatar icon"
    >
      <Image
        alt="user avatar"
        src={avatarUrl || DEFAULT_IMAGE_URL}
        className="discord-visualizer__avatar"
        height="40"
        width="40"
        unoptimized
        placeholder='blur'
        blurDataURL={BLUR_DATA_URL}
      />
    </Button>
  ) : (
    <div className={classNames('discord-visualizer__avatar-outer', showEdit && styles.dimHover)}>
      <Image
        alt="user avatar"
        src={avatarUrl || DEFAULT_IMAGE_URL}
        className="discord-visualizer__avatar"
        height="40"
        width="40"
        unoptimized
        placeholder='blur'
        blurDataURL={BLUR_DATA_URL}
      />
    </div>
  );

  let comp;
  if (visualStyle === 'cozy') {
    comp = (
      <>
        {avatar}
        <span className={classNames('strip discord-visualizer__header', styles.errorStateBorder)}>
          <span className="discord-visualizer__user">
            {usernameComponent}
            {botTagComponent}
          </span>
          {timeComponent}
        </span>
        {error && <div className='mt-1 text-xs font-bold text-error'>{error}</div>}
      </>
    );
  } else {
    comp = (
      <>
        <span className="strip discord-visualizer__header">
          {timeComponent}
          <span className="discord-visualizer__user">
            {botTagComponent}
            {usernameComponent}
            <i className='discord-visualizer__separator'>:</i>
          </span>
        </span>
        {error && <div className='mt-1 text-xs font-bold text-error'>{error}</div>}
      </>
    );
  }

  return (
    <>
      {comp}
      <ImageUploader
        isOpen={showImageUpload}
        onClose={unsetShowImageUpload}
        image={avatarUrl}
        ringMask
        setImage={setImage}
        aspectRatio={1}
      />
    </>
  );
};

export default memo(Author);

'use client';

import { PlusIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import { memo, useCallback, useState } from 'react';
import { useFocusWithin } from 'react-aria';
import { useLatest } from 'react-use';

import { createLinkButton } from '../../types';

import ExternalLinkIcon from './ExternalLinkIcon';
import LinkButtonEditor from './LinkButtonEditor';

import NullableComponent from '~/components/NullableComponent';
import { MAX_ACTION_ROW_BUTTONS } from '~/constants';
import { genUuid } from '~/utils';

interface ButtonVisualProps {
  button: EditableLinkButton;
  showEdit: boolean;
  setButton: (btn: EditableLinkButton) => void;
  onDelete: VoidFunction;
  onDuplicate: VoidFunction | undefined;
}

const ButtonVisual: FC<ButtonVisualProps> = ({
  button, showEdit, setButton, onDelete, onDuplicate,
}) => {
  const [focused, setFocused] = useState(false);
  const { focusWithinProps } = useFocusWithin({ onFocusWithinChange: setFocused });

  return (
    <div {...(showEdit ? focusWithinProps : {})} className="relative">
      <div
        className={classNames(
          'discord-visualizer__button discord-visualizer__button--link',
          button.disabled && 'discord-visualizer__button--disabled',
        )}
        tabIndex={showEdit ? 0 : undefined}
        role={showEdit ? 'button' : undefined}
      >
        {button.emoji?.name ? (
          <span className="discord-visualizer__button__emoji">
            {button.emoji.name}
          </span>
        ) : null}
        <span>{button.label || 'Button'}</span>
        <ExternalLinkIcon className="discord-visualizer__button__launch-icon" />
      </div>

      <NullableComponent show={showEdit && focused}>
        <div className="absolute left-0 z-10 mt-1 rounded-md border border-tertiary bg-secondary shadow-lg">
          <LinkButtonEditor button={button} setButton={setButton} />
          <div className="border-t border-tertiary px-3 py-2">
            <div className="flex items-center justify-between">
              <NullableComponent show={onDuplicate}>
                <button
                  type="button"
                  className="text-xs font-medium text-header-secondary hover:text-header-primary"
                  onClick={onDuplicate}
                >
                  Duplicate Button
                </button>
              </NullableComponent>
              <button
                type="button"
                className="text-xs font-medium text-red-400 hover:text-red-300"
                onClick={onDelete}
              >
                Delete Button
              </button>
            </div>
          </div>
        </div>
      </NullableComponent>
    </div>
  );
};

interface Props {
  row: EditableActionRow;
  showEdit: boolean;
  setRow: (row: EditableActionRow) => void;
}

const ActionRowEditor: FC<Props> = ({ row, showEdit, setRow }) => {
  const latestRow = useLatest(row);

  const addButton = useCallback(() => {
    if (latestRow.current.components.length >= MAX_ACTION_ROW_BUTTONS) return;
    setRow({
      ...latestRow.current,
      components: [...latestRow.current.components, createLinkButton()],
    });
  }, [setRow]);

  const setButton = useCallback((idx: number) => (btn: EditableLinkButton) => setRow({
    ...latestRow.current,
    components: latestRow.current.components.map((b, i) => (i === idx ? btn : b)),
  }), [setRow]);

  const deleteButton = useCallback((idx: number) => () => setRow({
    ...latestRow.current,
    components: latestRow.current.components.filter((_, i) => i !== idx),
  }), [setRow]);

  const duplicateButton = useCallback((idx: number) => () => {
    if (latestRow.current.components.length >= MAX_ACTION_ROW_BUTTONS) return;
    const original = latestRow.current.components[idx];
    const clone: EditableLinkButton = { ...original, _key: genUuid() };
    const next = [...latestRow.current.components];
    next.splice(idx + 1, 0, clone);
    setRow({ ...latestRow.current, components: next });
  }, [setRow]);

  return (
    <div className="discord-visualizer__action-row">
      {row.components.map((btn, idx) => (
        <ButtonVisual
          key={btn._key}
          button={btn}
          showEdit={showEdit}
          setButton={setButton(idx)}
          onDelete={deleteButton(idx)}
          onDuplicate={row.components.length < MAX_ACTION_ROW_BUTTONS
            ? duplicateButton(idx) : undefined}
        />
      ))}
      <NullableComponent show={showEdit && row.components.length < MAX_ACTION_ROW_BUTTONS}>
        <button
          type="button"
          className="discord-visualizer__button-add"
          onClick={addButton}
        >
          <PlusIcon className="h-4 w-4" />
        </button>
      </NullableComponent>
      <NullableComponent show={showEdit}>
        <span className="self-center text-[10px] text-text-mute">
          {row.components.length}
          /
          {MAX_ACTION_ROW_BUTTONS}
        </span>
      </NullableComponent>
    </div>
  );
};

export default memo(ActionRowEditor);

'use client';

import {
  Menu, MenuButton, MenuItem, MenuItems,
} from '@headlessui/react';
import { DocumentDuplicateIcon, PlusIcon, TrashIcon } from '@heroicons/react/20/solid';
import { ChevronDownIcon, ChevronUpIcon } from '@heroicons/react/24/outline';
import classNames from 'classnames';
import { ComponentType } from 'discord-api-types/v10';
import {
  memo, useCallback, useRef, useState,
} from 'react';
import { useLatest } from 'react-use';

import {
  createActionRow,
  createFile,
  createMediaGallery,
  createSection,
  createSeparator,
  createTextDisplay,
} from '../../types';

import ActionRowEditor from './ActionRowEditor';
import FileEditor from './FileEditor';
import MediaGalleryEditor from './MediaGalleryEditor';
import SectionEditor from './SectionEditor';
import SeparatorEditor from './SeparatorEditor';
import TextDisplayEditor from './TextDisplayEditor';

import Button from '~/components/Button';
import NullableComponent from '~/components/NullableComponent';
import Tooltip from '~/components/dynamics/Tooltip';
import styles from '~/styles';
import { intToHex, rekeyComponent } from '~/utils';

interface ChildBodyProps {
  child: EditableContainerChild;
  showEdit: boolean;
  set: (c: EditableContainerChild) => void;
  onAutoRemove: VoidFunction;
}

const ContainerChildBody: FC<ChildBodyProps> = ({ child, showEdit, set, onAutoRemove }) => {
  switch (child.type) {
    case ComponentType.ActionRow:
      return (
        <ActionRowEditor
          row={child}
          showEdit={showEdit}
          setRow={set as (row: EditableActionRow) => void}
        />
      );
    case ComponentType.TextDisplay:
      return (
        <TextDisplayEditor
          component={child}
          showEdit={showEdit}
          set={set as (c: EditableTextDisplay) => void}
        />
      );
    case ComponentType.Section:
      return (
        <SectionEditor
          section={child}
          showEdit={showEdit}
          setSection={set as (c: EditableSection) => void}
          onAutoRemove={onAutoRemove}
        />
      );
    case ComponentType.MediaGallery:
      return (
        <MediaGalleryEditor
          gallery={child}
          showEdit={showEdit}
          setGallery={set as (c: EditableMediaGallery) => void}
        />
      );
    case ComponentType.File:
      return (
        <FileEditor
          file={child}
          showEdit={showEdit}
          setFile={set as (c: EditableFile) => void}
        />
      );
    case ComponentType.Separator:
      return (
        <SeparatorEditor
          separator={child}
          showEdit={showEdit}
          setSeparator={set as (c: EditableSeparator) => void}
        />
      );
    default:
      return null;
  }
};

const CHILD_LABELS: Record<number, string> = {
  [ComponentType.ActionRow]: 'Action Row',
  [ComponentType.TextDisplay]: 'Text Display',
  [ComponentType.Section]: 'Section',
  [ComponentType.MediaGallery]: 'Media Gallery',
  [ComponentType.File]: 'File',
  [ComponentType.Separator]: 'Separator',
};

interface ChildWrapperProps {
  child: EditableContainerChild;
  showEdit: boolean;
  set: (c: EditableContainerChild) => void;
  onDelete: VoidFunction;
  onMoveUp: VoidFunction | undefined;
  onMoveDown: VoidFunction | undefined;
  onDuplicate: VoidFunction | undefined;
}

const ContainerChildWrapper: FC<ChildWrapperProps> = ({
  child, showEdit, set, onDelete, onMoveUp, onMoveDown, onDuplicate,
}) => {
  const label = CHILD_LABELS[child.type] ?? 'Component';
  const [focusedWithin, setFocusedWithin] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  return (
    <div className="group/child relative">
      <div
        ref={contentRef}
        onFocus={() => setFocusedWithin(true)}
        onBlur={(e) => {
          if (!contentRef.current?.contains(e.relatedTarget as Node)) {
            setFocusedWithin(false);
          }
        }}
      >
        <ContainerChildBody child={child} showEdit={showEdit} set={set} onAutoRemove={onDelete} />
      </div>
      {showEdit && !focusedWithin && (
        <div
          className={classNames(
            'absolute top-0 right-0 z-[1] flex overflow-hidden rounded',
            'bg-tertiary leading-[0] opacity-0',
            'group-hover/child:opacity-100',
          )}
        >
          <NullableComponent show={onMoveUp}>
            <Tooltip label="Move Up" placement="top">
              <Button
                aria-label={`move ${label} up`}
                className={classNames(styles.button.icon, '!p-1 first:rounded-l last:rounded-r')}
                onPress={onMoveUp}
                altFocus
              >
                <ChevronUpIcon className={classNames(styles.smallIcon, '!stroke-2')} />
              </Button>
            </Tooltip>
          </NullableComponent>
          <NullableComponent show={onMoveDown}>
            <Tooltip label="Move Down" placement="top">
              <Button
                aria-label={`move ${label} down`}
                className={classNames(styles.button.icon, '!p-1 first:rounded-l last:rounded-r')}
                onPress={onMoveDown}
                altFocus
              >
                <ChevronDownIcon className={classNames(styles.smallIcon, '!stroke-2')} />
              </Button>
            </Tooltip>
          </NullableComponent>
          <NullableComponent show={onDuplicate}>
            <Tooltip label="Duplicate" placement="top">
              <Button
                aria-label={`duplicate ${label}`}
                className={classNames(styles.button.icon, '!p-1 first:rounded-l last:rounded-r')}
                onPress={onDuplicate}
                altFocus
              >
                <DocumentDuplicateIcon className={styles.smallIcon} />
              </Button>
            </Tooltip>
          </NullableComponent>
          <Tooltip label="Delete" placement="top">
            <Button
              aria-label={`delete ${label}`}
              className={classNames(styles.button.icon, '!p-1 first:rounded-l last:rounded-r')}
              onPress={onDelete}
              altFocus
            >
              <TrashIcon className={styles.smallIcon} />
            </Button>
          </Tooltip>
        </div>
      )}
    </div>
  );
};

const CONTAINER_CHILD_ITEMS = [
  { label: 'Action Row', factory: createActionRow },
  { label: 'Text Display', factory: createTextDisplay },
  { label: 'Section', factory: createSection },
  { label: 'Media Gallery', factory: createMediaGallery },
  { label: 'File', factory: createFile },
  { label: 'Separator', factory: createSeparator },
] as const;

interface Props {
  container: EditableContainer;
  showEdit: boolean;
  setContainer: (c: EditableContainer) => void;
  canAddChild: boolean;
}

const ContainerEditor: FC<Props> = ({
  container, showEdit, setContainer, canAddChild,
}) => {
  const latest = useLatest(container);

  const setChild = useCallback(
    (idx: number) => (child: EditableContainerChild) => setContainer({
      ...latest.current,
      components: latest.current.components.map((c, i) => (i === idx ? child : c)),
    }),
    [setContainer],
  );

  const deleteChild = useCallback(
    (idx: number) => () => setContainer({
      ...latest.current,
      components: latest.current.components.filter((_, i) => i !== idx),
    }),
    [setContainer],
  );

  const moveChildUp = useCallback(
    (idx: number) => () => {
      if (idx === 0) return;
      const next = [...latest.current.components];
      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
      setContainer({ ...latest.current, components: next });
    },
    [setContainer],
  );

  const moveChildDown = useCallback(
    (idx: number) => () => {
      if (idx === latest.current.components.length - 1) return;
      const next = [...latest.current.components];
      [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
      setContainer({ ...latest.current, components: next });
    },
    [setContainer],
  );

  const duplicateChild = useCallback(
    (idx: number) => () => {
      const child = latest.current.components[idx];
      const clone = rekeyComponent(
        child as EditableTopLevelComponent,
      ) as EditableContainerChild;
      const next = [...latest.current.components];
      next.splice(idx + 1, 0, clone);
      setContainer({ ...latest.current, components: next });
    },
    [setContainer],
  );

  const borderColor = container.accent_color != null
    ? intToHex(container.accent_color) : undefined;

  return (
    <div
      className="discord-visualizer__container"
      style={{ borderLeftColor: borderColor }}
    >
      {container.spoiler && (
        <div className="discord-visualizer__container__spoiler-overlay">
          SPOILER
        </div>
      )}

      <div className={classNames(
        'discord-visualizer__container__children',
        showEdit && 'gap-2',
      )}
      >
        {container.components.map((child, idx) => (
          <ContainerChildWrapper
            key={child._key}
            child={child}
            showEdit={showEdit}
            set={setChild(idx)}
            onDelete={deleteChild(idx)}
            onMoveUp={idx === 0 ? undefined : moveChildUp(idx)}
            onMoveDown={idx === container.components.length - 1
              ? undefined : moveChildDown(idx)}
            onDuplicate={canAddChild ? duplicateChild(idx) : undefined}
          />
        ))}

        <NullableComponent
          show={showEdit && canAddChild}
        >
          <Menu as="div" className="relative">
            <MenuButton className="discord-visualizer__button-add w-full">
              <PlusIcon className="h-4 w-4" />
            </MenuButton>
            <MenuItems
              className="absolute left-0 z-10 mt-1 w-40 rounded-md border border-tertiary bg-secondary py-1 shadow-lg"
            >
              {CONTAINER_CHILD_ITEMS.map(({ label, factory }) => (
                <MenuItem key={label}>
                  <button
                    type="button"
                    className="block w-full px-3 py-1.5 text-left text-sm text-header-primary hover:bg-modifier-hover"
                    onClick={() => setContainer({
                      ...latest.current,
                      components: [
                        ...latest.current.components,
                        factory() as EditableContainerChild,
                      ],
                    })}
                  >
                    {label}
                  </button>
                </MenuItem>
              ))}
            </MenuItems>
          </Menu>
        </NullableComponent>
      </div>
    </div>
  );
};

export default memo(ContainerEditor);

'use client';

import { DocumentIcon } from '@heroicons/react/24/outline';
import classNames from 'classnames';
import {
  memo, useCallback, useMemo, useState,
} from 'react';
import { useFocusWithin } from 'react-aria';
import { useLatest } from 'react-use';

import NullableComponent from '~/components/NullableComponent';

interface Props {
  file: EditableFile;
  showEdit: boolean;
  setFile: (f: EditableFile) => void;
}

const FileEditor: FC<Props> = ({ file, showEdit, setFile }) => {
  const latest = useLatest(file);
  const [focused, setFocused] = useState(false);
  const { focusWithinProps } = useFocusWithin({ onFocusWithinChange: setFocused });

  const setUrl = useCallback(
    (val: string) => setFile({ ...latest.current, file: { url: val } }),
    [setFile],
  );

  const setSpoiler = useCallback(
    (val: boolean) => setFile({ ...latest.current, spoiler: val || undefined }),
    [setFile],
  );

  const fileName = useMemo(() => {
    try {
      const { url } = file.file;
      if (!url) return '';
      const segments = new URL(url).pathname.split('/');
      return segments[segments.length - 1] || url;
    } catch {
      return file.file.url || '';
    }
  }, [file.file.url]);

  return (
    <div
      {...(showEdit ? focusWithinProps : {})}
      className={classNames(
        'discord-visualizer__file',
        file.spoiler && 'discord-visualizer__file--spoiler',
