import { memo, useCallback } from 'react';
import { useLatest } from 'react-use';

import type { MutableRefObject } from 'react';

import { MAX_BUTTON_LABEL_LENGTH } from '~/constants';
import isValidUrl from '~/utils/isValidUrl';

function useButtonSetter<K extends keyof EditableLinkButton>(
  button: EditableLinkButton,
  latest: MutableRefObject<EditableLinkButton>,
  key: K,
  set: (btn: EditableLinkButton) => void,
) {
  return useCallback(
    (val: EditableLinkButton[K]) => set({ ...latest.current, [key]: val }),
    [button[key], set],
  ) as (val: EditableLinkButton[K]) => void;
}

interface Props {
  button: EditableLinkButton;
  setButton: (btn: EditableLinkButton) => void;
}

/** Popover form content for editing a single link button. */
const LinkButtonEditor: FC<Props> = ({ button, setButton }) => {
  const latest = useLatest(button);

  const setLabel = useButtonSetter(button, latest, 'label', setButton);
  const setUrl = useButtonSetter(button, latest, 'url', setButton);
  const setDisabled = useButtonSetter(button, latest, 'disabled', setButton);

  const urlEmpty = !button.url;
  const urlInvalid = !!button.url && !isValidUrl(button.url);

  return (
    <div className="w-56 space-y-1.5 p-3">
      <label className="text-xs font-medium text-header-secondary">
        Label
        <input
          type="text"
          value={button.label ?? ''}
          maxLength={MAX_BUTTON_LABEL_LENGTH}
          placeholder="Button label"
          className="mt-0.5 block w-full rounded-md border border-tertiary bg-primary px-2 py-1 text-sm text-header-primary placeholder:text-text-mute"
          onChange={(e) => setLabel(e.target.value || undefined)}
        />
      </label>
      <label className="text-xs font-medium text-header-secondary">
        URL
        <input
          type="url"
          value={button.url}
          placeholder="https://example.com"
          className={`mt-0.5 block w-full rounded-md border px-2 py-1 text-sm text-header-primary placeholder:text-text-mute ${urlEmpty || urlInvalid ? 'border-error bg-primary' : 'border-tertiary bg-primary'}`}
          onChange={(e) => setUrl(e.target.value)}
        />
        {urlEmpty && (
          <span className="mt-0.5 text-xs text-error">URL is required.</span>
        )}
        {urlInvalid && (
          <span className="mt-0.5 text-xs text-error">Invalid URL.</span>
        )}
      </label>
      <label className="flex items-center gap-1.5 text-xs font-medium text-header-secondary">
        <input
          type="checkbox"
          checked={!!button.disabled}
          onChange={(e) => setDisabled(e.target.checked || undefined)}
