interface Props {
  gallery: EditableMediaGallery;
  showEdit: boolean;
  setGallery: (g: EditableMediaGallery) => void;
}

const MediaGalleryEditor: FC<Props> = ({ gallery, showEdit, setGallery }) => {
  const latest = useLatest(gallery);

  const setItem = useCallback(
    (idx: number) => (item: EditableMediaGalleryItem) => setGallery({
      ...latest.current,
      items: latest.current.items.map((it, i) => (i === idx ? item : it)),
    }),
    [setGallery],
  );

  const deleteItem = useCallback(
    (idx: number) => () => setGallery({
      ...latest.current,
      items: latest.current.items.filter((_, i) => i !== idx),
    }),
    [setGallery],
  );

  const addItem = useCallback(() => {
    if (latest.current.items.length >= MAX_MEDIA_GALLERY_ITEMS) return;
    setGallery({
      ...latest.current,
      items: [...latest.current.items, createMediaGalleryItem()],
    });
  }, [setGallery]);

  const duplicateItem = useCallback(
    (idx: number) => () => {
      if (latest.current.items.length >= MAX_MEDIA_GALLERY_ITEMS) return;
      const original = latest.current.items[idx];
      const clone: EditableMediaGalleryItem = { ...original, _key: genUuid() };
      const next = [...latest.current.items];
      next.splice(idx + 1, 0, clone);
      setGallery({ ...latest.current, items: next });
    },
    [setGallery],
  );

  const count = gallery.items.length;
  let gridModifier;
  if (count === 1) {
    gridModifier = '--1';
  } else if (count === 2) {
    gridModifier = '--2';
  } else {
    gridModifier = '--mosaic';
  }

  return (
    <>
      <div
        className={classNames(
          'discord-visualizer__media-gallery',
          `discord-visualizer__media-gallery${gridModifier}`,
        )}
      >
        {gallery.items.map((item, idx) => (
          <GalleryItemVisual
            key={item._key}
            item={item}
            showEdit={showEdit}
            canDelete={count > 1}
            setItem={setItem(idx)}
            onDelete={deleteItem(idx)}
            onDuplicate={count < MAX_MEDIA_GALLERY_ITEMS
              ? duplicateItem(idx) : undefined}
          />
        ))}
        <NullableComponent show={showEdit && count < MAX_MEDIA_GALLERY_ITEMS}>
          <button
            type="button"
            className="discord-visualizer__media-gallery__item-add"
            onClick={addItem}
          >
            <PlusIcon className="h-5 w-5" />
          </button>
        </NullableComponent>
      </div>
      <NullableComponent show={showEdit}>
        <div className="mt-1 text-right text-[10px] text-text-mute">
          {count}
          /
          {MAX_MEDIA_GALLERY_ITEMS}
        </div>
      </NullableComponent>
    </>
  );
};

export default memo(MediaGalleryEditor);

