const SectionEditor: FC<Props> = ({ section, showEdit, setSection, onAutoRemove }) => {
  const latest = useLatest(section);

  const setTextComponent = useCallback(
    (idx: number) => (td: EditableTextDisplay) => setSection({
      ...latest.current,
      components: latest.current.components.map((c, i) => (i === idx ? td : c)),
    }),
    [setSection],
  );

  const addTextComponent = useCallback(() => {
    if (latest.current.components.length >= MAX_SECTION_TEXT_COMPONENTS) return;
    setSection({
      ...latest.current,
      components: [...latest.current.components, createTextDisplay()],
    });
  }, [setSection]);

  const deleteTextComponent = useCallback(
    (idx: number) => () => {
      const next = latest.current.components.filter((_, i) => i !== idx);
      if (next.length === 0) {
        onAutoRemove();
      } else {
        setSection({ ...latest.current, components: next });
      }
    },
    [setSection, onAutoRemove],
  );

  const duplicateTextComponent = useCallback(
    (idx: number) => () => {
      if (latest.current.components.length >= MAX_SECTION_TEXT_COMPONENTS) return;
      const original = latest.current.components[idx];
      const clone: EditableTextDisplay = { ...original, _key: genUuid() };
      const next = [...latest.current.components];
      next.splice(idx + 1, 0, clone);
      setSection({ ...latest.current, components: next });
    },
    [setSection],
  );

  const moveTextComponentUp = useCallback(
    (idx: number) => () => {
      if (idx === 0) return;
      const next = [...latest.current.components];
      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
      setSection({ ...latest.current, components: next });
    },
    [setSection],
  );

  const moveTextComponentDown = useCallback(
    (idx: number) => () => {
      if (idx === latest.current.components.length - 1) return;
      const next = [...latest.current.components];
      [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
      setSection({ ...latest.current, components: next });
    },
    [setSection],
  );

  const setAccessory = useCallback(
    (acc: EditableThumbnail | EditableLinkButton) => setSection({
      ...latest.current, accessory: acc,
    }),
    [setSection],
  );

  return (
    <div className="discord-visualizer__section">
      <div className="discord-visualizer__section__text">
        {section.components.map((td, idx) => (
          <TextDisplayWrapper
            key={td._key}
            td={td}
            showEdit={showEdit}
            set={setTextComponent(idx)}
            onDelete={deleteTextComponent(idx)}
            onDuplicate={section.components.length < MAX_SECTION_TEXT_COMPONENTS
              ? duplicateTextComponent(idx) : undefined}
            onMoveUp={idx > 0 ? moveTextComponentUp(idx) : undefined}
            onMoveDown={idx < section.components.length - 1
              ? moveTextComponentDown(idx) : undefined}
          />
        ))}
        <NullableComponent
          show={showEdit && section.components.length < MAX_SECTION_TEXT_COMPONENTS}
        >
          <button
            type="button"
            className="discord-visualizer__button-add"
            style={{ height: 24 }}
            onClick={addTextComponent}
          >
            <PlusIcon className="h-3.5 w-3.5" />
          </button>
        </NullableComponent>
        <NullableComponent show={showEdit}>
          <span className="text-[10px] text-text-mute">
            {section.components.length}
            /
            {MAX_SECTION_TEXT_COMPONENTS}
          </span>
        </NullableComponent>
      </div>

      <div className="discord-visualizer__section__accessory">
        {section.accessory.type === ComponentType.Thumbnail ? (
          <ThumbnailEditor
            thumbnail={section.accessory}
            showEdit={showEdit}
            setThumbnail={setAccessory as (t: EditableThumbnail) => void}
          />
        ) : (
          <AccessoryButton
            button={section.accessory}
            showEdit={showEdit}
            setButton={setAccessory as (b: EditableLinkButton) => void}
          />
        )}
      </div>
    </div>
  );
};

