import { act, useState } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import ColorPickerWrapper from '../index';

import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';
import press from '~/components/__tests__/helpers/press';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('next/image', () => ({ default: () => null }));
vi.mock('../Picker', () => ({ default: () => null }));

const handle = vi.hoisted(() => ({ hide: () => {} }));

const Host = () => {
  const [shown, setShown] = useState(true);
  handle.hide = () => setShown(false);
  return shown ? <ColorPickerWrapper initColor={0} setColor={() => {}} /> : null;
};

const ResizeObserverStub = function ResizeObserverStub() {
  return { observe() {}, unobserve() {}, disconnect() {} };
};

const scrollLocked = () => document.documentElement.classList.contains('overflow-hidden');

beforeEach(() => {
  vi.stubGlobal('ResizeObserver', ResizeObserverStub);
});
afterEach(() => {
  unmountDom();
  document.documentElement.classList.remove('overflow-hidden');
  vi.unstubAllGlobals();
});

describe('colour picker, page scrolling while it is open', () => {
  it('locks page scrolling while the picker is open', () => {
    const el = mountDom(<Host />);

    press(el.querySelector('button') as HTMLElement);

    expect(scrollLocked()).toBe(true);
  });

  it('releases the lock when the picker is removed while open', () => {
    const el = mountDom(<Host />);
    press(el.querySelector('button') as HTMLElement);
    expect(scrollLocked()).toBe(true);

    act(() => { handle.hide(); });

    expect(scrollLocked()).toBe(false);
  });
});

'use client';

import { LinkIcon, XMarkIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import Image from 'next/image';
import { Fragment, useCallback, useRef } from 'react';
import { useFocusWithin } from 'react-aria';

import type { EmbedAuthor as EmbedAuthorType } from '../../types';

import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import ContentEditable from '~/components/ContentEditable';
import ImageUploader from '~/components/dynamics/ImageUploader';
import NullableComponent from '~/components/NullableComponent';
import TextField from '~/components/TextField';
import { BLUR_DATA_URL, DEFAULT_IMAGE_URL } from '~/constants';
import styles from '~/styles';
import { validateEmbedAuthor } from '~/utils';
import {
  usePassedProp, useStandardBlurKeys, useStateSetter, useToggleState,
} from '~/utils/hooks';

interface Props {
  showEdit: boolean;
  author: undefined | EmbedAuthorType;
  setAuthor: (cb: (author: EmbedAuthorType) => EmbedAuthorType) => void;
}

const EmbedAuthor: FC<Props> = ({ author, showEdit, setAuthor }) => {
  const urlRef = useRef<HTMLInputElement>(null);

  const [showImageUpload, {
    setTrue: setShowImageUpload,
    setFalse: setHideImageUpload,
  }] = useToggleState();
  const [urlInputOpen, {
    set: setShowUrlInput, setTrue: showUrlInput,
    setFalse: hideUrlInput,
  }] = useToggleState();

  const setName = (value: string) => setAuthor((prevAuthor) => ({ ...prevAuthor, name: value }));
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
  const [localUsername, setLocalUsername] = usePassedProp(author?.name ?? '');

  const [url, _setUrl] = useStateSetter<EmbedAuthorType>(author ?? { name: localUsername }, 'url', setAuthor);
  const [iconUrl, _setIconUrl] = useStateSetter<EmbedAuthorType>(author ?? { name: localUsername }, 'icon_url', setAuthor);
  const setUrl = useCallback((val: EmbedAuthorType['url']) => _setUrl(val || undefined), [_setUrl]);
  const setIconUrl = useCallback((val: EmbedAuthorType['icon_url']) => _setIconUrl(val || undefined), [_setIconUrl]);
  const setImageCallback = useCallback<(url: string) => void>((dataURL) => { setIconUrl(dataURL); }, [setIconUrl]);

  const onBlurKey = useStandardBlurKeys();
  const { focusWithinProps } = useFocusWithin({
    onFocusWithin: () => {
      if (author?.name !== localUsername) setLocalUsername(author?.name ?? '');
      showUrlInput();
    },
    onBlurWithin: () => {
      const newName = localUsername.trim();
      if (newName !== author?.name) setName(newName);
      hideUrlInput();
    },
  });

  if (!showEdit) {
    if (!author) return null;

    return (
      <div className='discord-visualizer__embed-author'>
        {!author.icon_url ? null : (
          <Image
            alt="embed author icon"
            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
            src={author.icon_url ?? DEFAULT_IMAGE_URL}
            role='presentation'
            className='discord-visualizer__embed-author-icon'
            height="24"
            width="24"
            unoptimized
            placeholder='blur'
            blurDataURL={BLUR_DATA_URL}
          />
        )}
        {!url ? (
          <div className='discord-visualizer__embed-author-name'>
            {author.name}
          </div>
        ) : (
          <a
            target='_blank'
            rel='noreferrer'
            href={url}
            className='discord-visualizer__embed-author-name'
          >
            {author.name}
          </a>
        )}
      </div>
    );
  }

  const { error, urlErroring } = validateEmbedAuthor({ name: localUsername, url });

  return (
    <div className='discord-visualizer__embed-author' {...focusWithinProps}>
      <Button
        aria-label='edit embed author icon'
        className={classNames('flex min-w-fit', styles.dimHover)}
        onPress={setShowImageUpload}
      >
        <Image
          alt="embed author icon"
          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
          src={iconUrl || DEFAULT_IMAGE_URL}
          role='presentation'
          className='discord-visualizer__embed-author-icon'
          height="24"
          width="24"
          unoptimized
        />
      </Button>
      <AnchoredPopover
        placement='bottom-start'
        open={urlInputOpen}
        onOpenChange={setShowUrlInput}
      >
        <AnchoredPopover.Trigger as={Fragment}>
          <div data-erroring-state={error ? true : undefined}>
            <div className={classNames(styles.flex({ gap: 1 }), styles.errorStateBorder)}>
              <ContentEditable
                inputMode="text"
                aria-label='author name'
                inputClassName={classNames('discord-visualizer__embed-author-name', styles.clickable)}
                value={localUsername}
                placeholder='Author Name'
                onChange={setLocalUsername}
                onKeyDown={onBlurKey}
                fragment
              />
              <NullableComponent show={!urlInputOpen}>
                <Button aria-label='show embed author link' data-erroring-state={urlErroring ? true : undefined}>
                  <LinkIcon className={classNames('h-4 w-4', !url ? 'text-mute' : 'erroring:text-error')} />
                </Button>
              </NullableComponent>
            </div>
            <NullableComponent show={error}>
              <div className="mt-1 text-xs font-semibold text-error">{error}</div>
            </NullableComponent>
          </div>
        </AnchoredPopover.Trigger>
        <AnchoredPopover.Child
          {...styles.transition({
            transition: 'transition ease-out',
            enter: 'duration-100',
            leave: 'duration-75',
            closed: 'translate-x-2 opacity-0',
            opened: 'translate-x-0 opacity-100',
          })}
        >
          <div className='relative'>
            <TextField
              ref={urlRef}
              inputMode="url"
              aria-label="author url"
              outerClassName={classNames(styles.flex({ cy: true }), 'rounded bg-tertiary')}
              inputClassName="py-1 px-2"
              errorMessage={urlErroring ? 'Invalid URL' : undefined}
              errorClassName="text-error pr-6"
              placeholder="Enter a link (optional)"
              onChange={setUrl}
              value={url ?? ''}
            />
            <NullableComponent show={url}>
              <Button aria-label="remove author link" className="absolute right-0 top-0 h-full px-2 align-middle" onPress={() => setUrl('')}>
                <XMarkIcon className="h-4 w-4" />
              </Button>
            </NullableComponent>
          </div>
        </AnchoredPopover.Child>
      </AnchoredPopover>
      <ImageUploader
        isOpen={showImageUpload}
        image={iconUrl}
        ringMask
        onClose={setHideImageUpload}
        setImage={setImageCallback}
        aspectRatio={1}
      />
    </div>
  );
};

export default EmbedAuthor;

'use client';

import classNames from 'classnames';
import Image from 'next/image';
import { useCallback } from 'react';

import type { FC, ReactNode } from 'react';
import type { EmbedFooter as EmbedFooterType } from '../../types';

import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import ContentEditable from '~/components/ContentEditable';
import Calendar from '~/components/dynamics/Calendar';
import ImageUploader from '~/components/dynamics/ImageUploader';
import { DEFAULT_IMAGE_URL, MAX_EMBED_FOOTER_TEXT_LENGTH } from '~/constants';
import styles from '~/styles';
import {
  usePassedProp, useStandardBlurKeys, useStateSetter, useToggleState,
} from '~/utils/hooks';
import timestampToString from '~/utils/timestampToString';

type ISO8601timestamp = string;

const PLACEHOLDER_FOOTER_TEXT = 'Click or tap to edit footer text.';
const DEFAULT_TIMESTAMP = new Date();
DEFAULT_TIMESTAMP.setHours(0, 0, 0, 0);

interface Props {
  showEdit: boolean;
  footer?: EmbedFooterType;
  timestamp?: undefined | ISO8601timestamp;
  setTimestamp: (timestamp: ISO8601timestamp) => void;
  setFooter: (cb: (author: EmbedFooterType) => EmbedFooterType) => void;
}

const EmbedFooter: FC<Props> = ({
  showEdit, setFooter, setTimestamp, footer, timestamp,
}) => {
  const setText = (value: string) => setFooter((prev) => ({ ...prev, text: value }));
  const [showImageUpload, {
    setTrue: setShowImageUpload,
    setFalse: setHideImageUpload,
  }] = useToggleState();
  const [_localText, setLocalText] = usePassedProp(footer?.text ?? '');
  const displayText = (footer?.text?.trim() ?? '');
  const localText = _localText;

  const [iconUrl, _setIconUrl] = useStateSetter<EmbedFooterType>(footer ?? { text: localText }, 'icon_url', setFooter);
  const setIconUrl = useCallback((val: EmbedFooterType['icon_url']) => _setIconUrl(val === '' ? undefined : val), [_setIconUrl]);

  const setImageCallback = useCallback<(url: string) => void>((dataURL) => { setIconUrl(dataURL); }, [setIconUrl]);

  const onBlurKey = useStandardBlurKeys();

  let footerComp: undefined | ReactNode;
  if (!showEdit) {
    const footerText = displayText;
    const timestampText = timestamp && timestampToString(timestamp);

    if (footerText && timestampText) {
      footerComp = (
        <>
          {footerText}
          <span className="discord-visualizer__embed-footer-separator">•</span>
          {timestampText}
        </>
      );
    } else if (footer?.text) {
      footerComp = footerText;
    } else if (timestampText) {
      footerComp = timestampText;
    }

    return (
      <div className="discord-visualizer__embed-footer">
        {!footer?.icon_url || !displayText ? null : (
          <Image
            alt='embed footer icon'
            src={footer.icon_url ?? DEFAULT_IMAGE_URL}
            className='discord-visualizer__embed-footer-icon'
            height="20"
            width="20"
            unoptimized
          />
        )}
        {!footerComp ? null : <span className="discord-visualizer__embed-footer-text">{footerComp}</span>}
      </div>
    );
  }

  const error = localText.length > MAX_EMBED_FOOTER_TEXT_LENGTH ? `Footer text must be less than ${MAX_EMBED_FOOTER_TEXT_LENGTH} characters.` : undefined;

  return (
    <>
      <div className="discord-visualizer__embed-footer" data-erroring-state={error ? true : undefined}>
        <Button
          aria-label="edit embed footer icon"
          className={classNames('flex min-w-fit', showEdit && styles.dimHover)}
          onPress={showEdit ? setShowImageUpload : undefined}
        >
          <Image
            alt="embed footer icon"
            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
            src={iconUrl || DEFAULT_IMAGE_URL}
            className='discord-visualizer__embed-footer-icon'
            height="20"
            width="20"
            unoptimized
          />
        </Button>
        <span className="discord-visualizer__embed-footer-text flex">
          <ContentEditable
            inputMode='text'
            aria-label='footer text'
            inputClassName={classNames(styles.errorStateBorder, !localText && 'italic !text-mute')}
            value={localText}
            placeholder={PLACEHOLDER_FOOTER_TEXT}
            onChange={setLocalText}
            onKeyDown={onBlurKey}
            onFocus={() => {
              if (displayText !== localText) setLocalText(displayText ?? '');
            }}
            onBlur={() => setText(localText?.trim())}
            fragment
          />
          <span className={classNames('discord-visualizer__embed-footer-separator', (!timestamp || !displayText) && '!text-mute')}>•</span>
          <AnchoredPopover placement='top' arrow>
            <AnchoredPopover.Trigger className={classNames(!timestamp && 'text-mute')}>
              {/* eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing */}
              {timestampToString(timestamp || DEFAULT_TIMESTAMP)}
            </AnchoredPopover.Trigger>
            <AnchoredPopover.Child
              {...styles.transition({
                transition: 'transition ease-out min-w-fit',
                enter: 'duration-100',
                leave: 'duration-75',
                closed: '-translate-y-4 flipped:translate-y-4 opacity-0',
                opened: '-translate-y-2 flipped:translate-y-2 opacity-100',
              })}
            >
              <Calendar
                value={timestamp ? new Date(timestamp) : new Date()}
                onChange={(date) => setTimestamp(date ? date.toISOString() : '')}
              />
            </AnchoredPopover.Child>
          </AnchoredPopover>
        </span>
        <ImageUploader
          isOpen={showImageUpload}
          image={iconUrl}
          ringMask
          onClose={setHideImageUpload}
          setImage={setImageCallback}
          aspectRatio={1}
        />
      </div>
      {/* <NullableComponent show={error}>
        <div className="text-error text-xs font-semibold mt-1">{error}</div>
      </NullableComponent> */}
    </>
  );
};

export default EmbedFooter;

import classNames from 'classnames';
import NextImage from 'next/image';
import { useCallback, useEffect, useState } from 'react';

import Button from '~/components/Button';
import ImageUploader from '~/components/dynamics/ImageUploader';
import { BLUR_DATA_URL, DEFAULT_IMAGE_URL } from '~/constants';
import styles from '~/styles';
import { useToggleState } from '~/utils/hooks';

const MAX_IMAGE_WIDTH = 400;
const MAX_IMAGE_HEIGHT = 256;

const getImageDimensions = (url: string, setDimensions: (d: null | Dimensions) => void) => {
  const image = new Image();
  image.onload = () => {
    if (image.width > 0) {
      setDimensions({ width: image.width, height: image.height });
    } else {
      setDimensions(null);
    }
  };
  image.onerror = () => {
    setDimensions(null);
  };
  image.src = url;
};

function constrainAspectRatio(width: number, height: number, maxWidth: number, maxHeight: number) {
  if (width > maxWidth || height > maxHeight) {
    const xConstraint = width / maxWidth;
    const yConstraint = height / maxHeight;
    if (xConstraint > yConstraint) {
      height /= xConstraint;
      width /= xConstraint;
    } else {
      height /= yConstraint;
      width /= yConstraint;
    }
  }

  return {
    width: Math.floor(width),
    height: Math.floor(height),
  };
}

interface Props {
  showEdit: boolean;
  url: undefined | string;
  hasThumbnail: boolean;
  set: (url: string) => void;
}

const EmbedImage: FC<Props> = ({
  showEdit, hasThumbnail, url, set,
}) => {
  const [showImageUpload, {
    setTrue: setShowImageUpload,
    setFalse: setHideImageUpload,
  }] = useToggleState();
  let [dimensions, setDimensions] = useState<null | Dimensions>(null);

  const setImage = useCallback<(image: string) => void>((image) => { set(image); }, [set]);

  useEffect(() => {
    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
    getImageDimensions(url || DEFAULT_IMAGE_URL, setDimensions);
  }, [url]);

  if (!dimensions) dimensions = { width: MAX_IMAGE_WIDTH, height: MAX_IMAGE_HEIGHT };

  const { width, height } = constrainAspectRatio(
    dimensions.width,
    dimensions.height,
    MAX_IMAGE_WIDTH,
    MAX_IMAGE_HEIGHT,
  );

  let image = (
    <NextImage
      style={{
        maxWidth: `${width}px`,
        maxHeight: `${height}px`,
        width: '100%',
        aspectRatio: `${width} / ${height}`,
      }}
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
      src={url || DEFAULT_IMAGE_URL}
      alt='embed main'
      width={width}
      height={height}
      priority
      placeholder='blur'
      blurDataURL={BLUR_DATA_URL}
      unoptimized
    />
  );

  if (showEdit) {
    image = (
      <Button
        aria-label="edit embed image"
        className={classNames(showEdit && styles.dimHover, 'h-full w-full')}
        onPress={showEdit ? setShowImageUpload : undefined}
      >
        {image}
      </Button>
    );
  }

  return (
    <div className={classNames('discord-visualizer__embed-media discord-visualizer__embed-image discord-visualizer__image-content', hasThumbnail && 'hasThumbnail')}>
      <div className="discord-visualizer__image-container">
        <div
          style={{
            maxWidth: `${width}px`,
            width: '100%',
            aspectRatio: `${width} / ${height}`,
          }}
          className='discord-visualizer__image-wrapper'
        >
          {image}
        </div>
      </div>
      <ImageUploader
        isOpen={showImageUpload}
        image={url}
        onClose={setHideImageUpload}
        setImage={setImage}
        // cropBoxResizable
        // cropBoxMovable
      />
    </div>
  );
};

export default EmbedImage;

