'use client';

import { DocumentDuplicateIcon, TrashIcon } from '@heroicons/react/20/solid';
import { ChevronDownIcon, ChevronUpIcon } from '@heroicons/react/24/outline';
import classNames from 'classnames';
import { useCallback } from 'react';
import { useLatest } from 'react-use';

import ActionsMenu from '../ActionsMenu';

import ColorPicker from './ColorPicker';
import Embed from './Embed';

import type { MutableRefObject } from 'react';
import type { EmbedAuthor as EmbedAuthorType, EmbedFooter as EmbedFooterType } from '../../types';

import NullableComponent from '~/components/NullableComponent';
import WarningDialog from '~/components/WarningDialog';
import { intToHex } from '~/utils';
import { useToggleState } from '~/utils/hooks';

// function omit<T extends Record<string, unknown>, K extends keyof T>(obj: T, key: K): Omit<T, K> {
//   const { [key]: _, ...o } = obj;
//   return o;
// }

function useEmbedSetter<K extends keyof EditableEmbed>(
  embed: EditableEmbed,
  latestEmbed: MutableRefObject<EditableEmbed>,
  key: K,
  set: (embed: EditableEmbed) => void,
) {
  return useCallback(((val: EditableEmbed[K]) => set({ ...latestEmbed.current, [key]: val })), [embed[key], set]) as (val: EditableEmbed[K]) => void;
}

interface Props {
  showEdit: boolean;
  embed: EditableEmbed;
  editableState?: EditableState;
  setEmbed: (embed: EditableEmbed) => void;
  onDuplicate: undefined | (() => void);
  onDelete: () => void;
  onMoveUp: undefined | (() => void);
  onMoveDown: undefined | (() => void);
}

const EmbedEditor: FC<Props> = ({
  showEdit, embed, editableState,
  setEmbed, onDelete, onDuplicate, onMoveUp, onMoveDown,
}) => {
  const {
    author, image, color, thumbnail, footer,
  } = embed;

  const [showDeleteConfirmation, {
    setTrue: setShowDeleteConfirmation,
    setFalse: hideDeleteConfirmation,
  }] = useToggleState();

  const latestEmbed = useLatest(embed);

  const setColor = useEmbedSetter(embed, latestEmbed, 'color', setEmbed);
  const setTitle = useEmbedSetter(embed, latestEmbed, 'title', setEmbed);
  const setUrl = useEmbedSetter(embed, latestEmbed, 'url', setEmbed);
  const setDescription = useEmbedSetter(embed, latestEmbed, 'description', setEmbed);
  const setFields = useEmbedSetter(embed, latestEmbed, 'fields', setEmbed);
  const setAuthor = useCallback((cb: (a: EmbedAuthorType) => EmbedAuthorType) => setEmbed({
    ...latestEmbed.current, author: cb(author ?? { name: '' }),
  }), [setEmbed, author]);
  const setThumbnail = useCallback(((val: string) => setEmbed({
    ...latestEmbed.current, thumbnail: val ? { url: val } : undefined,
  })), [setEmbed]);
  const setImage = useCallback(((val: string) => setEmbed({
    ...latestEmbed.current, image: val ? { url: val } : undefined,
  })), [setEmbed]);
  const setFooter = useCallback((cb: (a: EmbedFooterType) => EmbedFooterType) => setEmbed({
    ...latestEmbed.current, footer: cb(footer ?? { text: '' }),
  }), [setEmbed, footer]);
  const setTimestamp = useCallback((val: string) => {
    const _embed = { ...latestEmbed.current };
    if (val) {
      _embed.timestamp = val;
    } else {
      delete _embed.timestamp;
    }

    setEmbed(_embed);
  }, [setEmbed]);

  const borderColor = color != null ? intToHex(color) : undefined;

  return (
    <article
      style={{ borderColor, maxWidth: image ? '432px' : undefined }}
      className={classNames('markup discord-visualizer__embed-wrapper discord-visualizer__embed--full', !!thumbnail?.url && 'discord-visualizer__embed--thumbnail')}
    >
      <NullableComponent show={showEdit && editableState?.showEmbedTools}>
        <div className="absolute left-0 flex translate-x-[calc(-100%-4px)] flex-col items-center gap-2 px-2">
          <ActionsMenu label="Embed">
            <NullableComponent show={onMoveUp}>
              <ActionsMenu.Item
                label="Move Up"
                Icon={ChevronUpIcon}
                onPress={() => onMoveUp?.()}
              />
            </NullableComponent>
            <NullableComponent show={onMoveDown}>
              <ActionsMenu.Item
                label="Move Down"
                Icon={ChevronDownIcon}
                onPress={() => onMoveDown?.()}
              />
            </NullableComponent>
            {(onMoveUp || onMoveDown) && <ActionsMenu.Divider />}
            <NullableComponent show={onDuplicate}>
              <ActionsMenu.Item
                label="Duplicate"
                Icon={DocumentDuplicateIcon}
                onPress={() => onDuplicate?.()}
              />
            </NullableComponent>
            <ActionsMenu.Item
              label="Delete"
              Icon={TrashIcon}
              onPress={setShowDeleteConfirmation}
              danger
            />
          </ActionsMenu>
          <ColorPicker initColor={color} setColor={setColor} />
        </div>
      </NullableComponent>
      <Embed
        embed={embed}
        showEdit={showEdit}
        editableState={editableState}
        setAuthor={setAuthor}
        setDescription={setDescription}
        setThumbnail={setThumbnail}
        setTitle={setTitle}
        setUrl={setUrl}
        setImage={setImage}
        setFields={setFields}
        setFooter={setFooter}
        setTimestamp={setTimestamp}
      />
      <WarningDialog
        title="Delete Embed?"
        message='Are you sure you want to delete this embed?'
        confirmText='Delete'
        open={showDeleteConfirmation}
        onConfirm={onDelete}
        onClose={hideDeleteConfirmation}
      />
    </article>
  );
};

export default EmbedEditor;

