'use client';

import {
  Menu, MenuButton, MenuItem, MenuItems, Transition,
} from '@headlessui/react';
import { PlusIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import {
  memo, use, useCallback, useEffect, useMemo, useRef,
} from 'react';

import Button from '../Button';

import Author from './components/Author';
import ComponentEditor from './components/ComponentEditors/ComponentEditor';
import ContentBody from './components/ContentBody';
import EmbedEditor from './components/EmbedEditor';
import {
  createActionRow,
  createContainer,
  createFile,
  createMediaGallery,
  createSection,
  createSeparator,
  createTextDisplay,
} from './types';

import type { StateCallback } from '~/utils/hooks';
import type { ComponentActions } from './types';

import NullableComponent from '~/components/NullableComponent';
import {
  MAX_EMBEDS, MAX_MESSAGE_CONTENT_LENGTH, MAX_TOTAL_COMPONENTS,
} from '~/constants';
import { Context as ConfirmationContext } from '~/providers/ConfirmationProvider';
import { useMarkdown } from '~/providers/MarkdownProvider';
import styles from '~/styles';
import { applyModeSwitch } from '~/utils/messageMode';
import {
  countTotalComponents, genUuid,
  hasClassicContent, hasV2Content,
  rekeyComponent, validateComponentCount, validateContentRequirements,
  validateDisplayableTextCount,
  validateEmbedCharacterCount,
  validateV2Components,
} from '~/utils';
import { useMounted, useStateSetter } from '~/utils/hooks';

export * from './types';

const COMPONENT_MENU_ITEMS = [
  { label: 'Action Row', factory: createActionRow },
  { label: 'Text Display', factory: createTextDisplay },
  { label: 'Section', factory: createSection },
  { label: 'Media Gallery', factory: createMediaGallery },
  { label: 'File', factory: createFile },
  { label: 'Separator', factory: createSeparator },
  { label: 'Container', factory: createContainer },
] as const;

interface EmbedActions {
  set: (embed: EditableEmbed) => void;
  duplicate: VoidFunction;
  delete: VoidFunction;
  moveUp: VoidFunction;
  moveDown: VoidFunction;
}

export interface VisualizerProps {
  message: EditableMessageData;
  visualStyle?: DiscordMessageStyle;
  locale: string;
  editableState?: EditableState;
  hideValidation?: boolean;
  setMessage: (message: EditableMessageData) => void;
  onMount?: VoidFunction;
}

const DiscordMessageEditor: FC<VisualizerProps> = ({
  message, visualStyle = 'cozy', locale, editableState, hideValidation = false, onMount, setMessage,
}) => {
  const mounted = useMounted();
  const markdown = useMarkdown();
  const confirmation = use(ConfirmationContext);

  useEffect(() => { onMount?.(); }, []);

  const messageRef = useRef(message);
  messageRef.current = message;
  const _setMessage = useCallback<StateCallback<EditableMessageData>>((cb) => setMessage(cb(messageRef.current)), [setMessage]);
  const [avatarUrl = '', setAvatarUrl] = useStateSetter<EditableMessageData, 'avatar_url'>(message, 'avatar_url', _setMessage);
  const [username = '', setUsername] = useStateSetter(message, 'username', _setMessage);
  const [content = '', setMessageContent] = useStateSetter(message, 'content', _setMessage);
  const [embeds = [], setEmbeds] = useStateSetter(message, 'embeds', _setMessage);
  const [components = [], setComponents] = useStateSetter(message, 'components', _setMessage);

  const embedActions = useMemo<EmbedActions[]>(() => {
    const duplicateEmbed = (idx: number) => () => {
      const newEmbeds = [...embeds];
      const newEmbed = JSON.parse(JSON.stringify(newEmbeds[idx])) as EditableEmbed;
      newEmbed._key = genUuid();
      if (newEmbed.fields) {
        for (const field of newEmbed.fields) {
          field._key = genUuid();
        }
      }
      newEmbeds.splice(idx + 1, 0, newEmbed);
      setEmbeds(newEmbeds);
    };
    const deleteEmbed = (idx: number) => () => setEmbeds(embeds.filter((_, i) => i !== idx));
    const setEmbed = (idx: number) => (embed: EditableEmbed) => setEmbeds(embeds.map((e, i) => (i === idx ? embed : e)));
    const moveEmbedUp = (idx: number) => () => {
      if (idx === 0) return;
      const newEmbeds = [...embeds];
      const temp = newEmbeds[idx];
      newEmbeds[idx] = newEmbeds[idx - 1];
      newEmbeds[idx - 1] = temp;
      setEmbeds(newEmbeds);
    };
    const moveEmbedDown = (idx: number) => () => {
      if (idx === embeds.length - 1) return;
      const newEmbeds = [...embeds];
      const temp = newEmbeds[idx];
      newEmbeds[idx] = newEmbeds[idx + 1];
      newEmbeds[idx + 1] = temp;
      setEmbeds(newEmbeds);
    };

    return new Array(MAX_EMBEDS).fill('', 0).map<EmbedActions>((_, idx) => ({
      set: setEmbed(idx),
      duplicate: duplicateEmbed(idx),
      delete: deleteEmbed(idx),
      moveUp: moveEmbedUp(idx),
      moveDown: moveEmbedDown(idx),
    }));
  }, [embeds, setEmbeds]);

  const componentActions = useMemo<ComponentActions[]>(() => {
    const setComponent = (idx: number) => (comp: EditableTopLevelComponent) => setComponents(components.map((c, i) => (i === idx ? comp : c)));

    const deleteComponent = (idx: number) => () => setComponents(components.filter((_, i) => i !== idx));

    const duplicateComponent = (idx: number) => () => {
      const clone = rekeyComponent(components[idx]);
      const next = [...components];
      next.splice(idx + 1, 0, clone);
      setComponents(next);
    };

    const moveUp = (idx: number) => () => {
      if (idx === 0) return;
      const next = [...components];
      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
      setComponents(next);
    };

    const moveDown = (idx: number) => () => {
      if (idx === components.length - 1) return;
      const next = [...components];
      [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
      setComponents(next);
    };

    return components.map<ComponentActions>((_, idx) => ({
      set: setComponent(idx),
      delete: deleteComponent(idx),
      duplicate: duplicateComponent(idx),
      moveUp: moveUp(idx),
      moveDown: moveDown(idx),
    }));
  }, [components, setComponents]);

  const totalComponentCount = countTotalComponents(components);
  const canAddComponent = totalComponentCount < MAX_TOTAL_COMPONENTS;

  const isEditing = !!editableState?.showEdit;
  const isClassicMode = !editableState || editableState.messageMode === 'classic';
  const isV2Mode = editableState?.messageMode === 'v2';

  const noContentError = hideValidation ? '' : validateContentRequirements(message);
  const embedCharacterError = hideValidation ? '' : validateEmbedCharacterCount(embeds);
  const v2TextError = hideValidation ? '' : validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
  const componentCountError = hideValidation ? '' : validateComponentCount(components);
  const v2ComponentError = hideValidation ? '' : validateV2Components(components, message.flags);
  const showEmbedButton = isEditing && isClassicMode
    && embeds.length < MAX_EMBEDS;
  const showComponentButton = isEditing && isV2Mode
    && !!editableState?.showComponentsEditable
    && canAddComponent;

  // In classic mode editing, only show ActionRow (type 1) components.
  // In v2 mode or preview, show all components.
  const visibleComponents = isEditing && isClassicMode
    ? components.filter((c) => (c as { type: number }).type === 1)
    : components;

  const handleModeSwitch = useCallback(() => {
    if (!editableState || !confirmation) return;
    const targetMode: MessageMode = isClassicMode ? 'v2' : 'classic';

    const currentMessage = messageRef.current;
    const currentComponents = currentMessage.components ?? [];
    const hasDepartingData = isClassicMode
      ? hasClassicContent(currentMessage)
      : hasV2Content(currentComponents as { type: number }[]);

    const switchMode = () => {
      _setMessage((prev) => applyModeSwitch(targetMode, prev));
      editableState.setMessageMode(targetMode);
    };

    confirmation.showConfirmation({
      enabled: hasDepartingData,
      title: 'Switch message mode?',
      message: targetMode === 'v2'
        ? 'Your embeds and content will be removed. This cannot be undone.'
        : 'Your Components V2 data will be removed. This cannot be undone.',
      confirmText: 'Continue',
      onConfirm: switchMode,
    });
  }, [editableState, isClassicMode, confirmation, _setMessage]);

  return (
    <Transition
      as="div"
      show={!!(markdown && (onMount || mounted))}
      appear
      className={classNames(
        `discord-visualizer discord-visualizer__${locale} w-full`,
        onMount && 'pointer-events-none select-none',
      )}
      {...styles.fadeInTransition}
    >
      <div className={classNames(
        'discord-visualizer__outer rounded-r-lg rounded-b-lg bg-primary',
        `discord-visualizer__${visualStyle}`,
        onMount && 'rounded-lg py-4 pr-4',
      )}
      >
        <div className="discord-visualizer__message">
          <NullableComponent show={isEditing}>
            <div className="mb-2 flex">
              <button
                type="button"
                className="flex rounded bg-tertiary p-1 text-sm text-header-primary"
                onClick={handleModeSwitch}
              >
                <span
                  className={classNames(
                    'rounded px-2 py-1 transition-colors',
                    isClassicMode && 'bg-modifier-hover',
                  )}
                >
                  Classic
                </span>
                <span
                  className={classNames(
                    'rounded px-2 py-1 transition-colors',
                    isV2Mode && 'bg-modifier-hover',
                  )}
                >
                  Components V2
                </span>
              </button>
            </div>
          </NullableComponent>
          <NullableComponent show={isClassicMode || !isEditing}>
            <ContentBody
              visualStyle={visualStyle}
              value={content}
              username={username}
              avatarUrl={avatarUrl}
              showEdit={isEditing && isClassicMode
                && !!editableState?.showContentEditable}
              hideValidation={hideValidation}
              onChange={setMessageContent}
              setUsername={setUsername}
              setAvatarUrl={setAvatarUrl}
              limit={MAX_MESSAGE_CONTENT_LENGTH}
            />
          </NullableComponent>
          <NullableComponent show={isV2Mode && isEditing}>
            <div className='discord-visualizer__contents'>
              <Author
                visualStyle={visualStyle}
                username={username}
                avatarUrl={avatarUrl}
                showEdit={!!editableState?.showContentEditable}
                hideValidation={hideValidation}
                setUsername={setUsername}
                setAvatarUrl={setAvatarUrl}
              />
            </div>
          </NullableComponent>
          <NullableComponent show={noContentError}>
            <div className="mt-1 text-xs font-semibold text-error">{noContentError}</div>
          </NullableComponent>
          <div className={classNames('discord-visualizer__accessories', (embedCharacterError || v2TextError || componentCountError || v2ComponentError) && styles.errorBorder)}>
            <NullableComponent show={(isClassicMode || !isEditing) && embeds.length}>
              {embeds.map((embed, idx) => (
                <EmbedEditor
                  key={embed._key}
                  embed={embed}
                  showEdit={!!editableState?.showEdit}
                  setEmbed={embedActions[idx].set}
                  onDelete={embedActions[idx].delete}
                  onDuplicate={embeds.length < MAX_EMBEDS ? embedActions[idx].duplicate : undefined}
                  onMoveUp={idx > 0 ? embedActions[idx].moveUp : undefined}
                  onMoveDown={idx < embeds.length - 1 ? embedActions[idx].moveDown : undefined}
                  editableState={editableState}
                />
              ))}
            </NullableComponent>
            <NullableComponent show={visibleComponents.length}>
              <div className={classNames(
                'discord-visualizer__components mt-1',
                isEditing && 'space-y-2',
              )}
              >
                {visibleComponents.map((comp, idx) => {
                  const realIdx = components.indexOf(comp);
                  return (
                    <ComponentEditor
                      key={comp._key}
                      component={comp}
                      showEdit={isEditing}
                      actions={componentActions[realIdx]}
                      isFirst={idx === 0}
                      isLast={idx === visibleComponents.length - 1}
                      canDuplicate={canAddComponent}
                      canAddChild={canAddComponent}
                    />
                  );
                })}
              </div>
            </NullableComponent>
          </div>
          <NullableComponent show={embedCharacterError}>
            <div className="mt-1 text-xs font-semibold text-error">{embedCharacterError}</div>
          </NullableComponent>
          <NullableComponent show={v2TextError}>
            <div className="mt-1 text-xs font-semibold text-error">{v2TextError}</div>
          </NullableComponent>
          <NullableComponent show={componentCountError}>
            <div className="mt-1 text-xs font-semibold text-error">{componentCountError}</div>
          </NullableComponent>
          <NullableComponent show={v2ComponentError}>
            <div className="mt-1 text-xs font-semibold text-error">{v2ComponentError}</div>
          </NullableComponent>
          <NullableComponent show={showEmbedButton && editableState?.showEmbedTools}>
            <Button
              className={classNames(styles.button.iconSizing, styles.button.tertiary, 'mt-2')}
              onPress={() => setEmbeds([...embeds, {} as EditableEmbed])}
            >
              <PlusIcon className={styles.icon} />
              Add Embed
            </Button>
          </NullableComponent>
          <NullableComponent show={showComponentButton}>
            <Menu as="div" className="relative mt-2 inline-block">
              <MenuButton
                as={Button}
                className={classNames(styles.button.iconSizing, styles.button.tertiary)}
              >
                <PlusIcon className={styles.icon} />
                Add Component
              </MenuButton>
              <MenuItems className="absolute left-0 z-10 mt-1 w-44 rounded-md border border-tertiary bg-secondary py-1 shadow-lg">
                {COMPONENT_MENU_ITEMS.map(({ label, factory }) => (
                  <MenuItem key={label}>
                    <button
                      type="button"
                      className="block w-full px-3 py-1.5 text-left text-sm text-header-primary hover:bg-modifier-hover"
                      onClick={() => setComponents(
                        [...components, factory() as EditableTopLevelComponent],
                      )}
                    >
                      {label}
                    </button>
                  </MenuItem>
                ))}
              </MenuItems>
            </Menu>
            <span className="ml-2 text-xs text-text-mute">
              {totalComponentCount}
              /
              {MAX_TOTAL_COMPONENTS}
            </span>
          </NullableComponent>
        </div>
      </div>
    </Transition>
  );
};

export default memo(DiscordMessageEditor);

