'use client';

import { Dialog } from '@headlessui/react';
import { clamp } from '@react-aria/utils';
import { animated, config, useSpring } from '@react-spring/web';
import { useDrag } from '@use-gesture/react';
import classNames from 'classnames';
import {
  memo, useCallback, useEffect, useMemo, useRef, useState,
} from 'react';
import { useIsSSR } from 'react-aria';
import { useLatest, useLockBodyScroll } from 'react-use';

import type { SpringValue } from '@react-spring/web';
import type {
  ComponentClass, FC, PropsWithChildren, ReactNode,
} from 'react';

import NullableComponent from '~/components/NullableComponent';
import styles from '~/styles';
import { useMounted } from '~/utils/hooks';

export type TransitionStatus = 'opening' | 'open' | 'resizing' | 'closing' | 'closed';

type Orientation = 'horizontal' | 'vertical';

function useStatus(open: boolean): [TransitionStatus, (status: TransitionStatus) => void] {
  const [status, setStatus] = useState<TransitionStatus>(open ? 'opening' : 'closed');

  useEffect(() => {
    if (open && status === 'closed') setStatus('opening');
    else if (!open && status !== 'closed') setStatus('closing');
  }, [open, status]);

  return [status, setStatus];
}

function useThresholds(
  orientation: Orientation,
  openThreshold: number,
  initSize: number,
  closeThreshold: number,
) {
  const { current: fullSize } = useRef<number>((orientation === 'vertical' ? window?.innerHeight : window?.innerWidth) ?? 0);
  return useMemo(() => {
    if (orientation === 'vertical') {
      const initPosition = clamp(Math.floor(fullSize * (1 - initSize)), 0);
      const openPosition = clamp(Math.floor(fullSize * (1 - openThreshold)), 0);
      const closePosition = clamp(Math.floor(fullSize * (1 - closeThreshold)), 0);
      return {
        fullSize, initPosition, openPosition, closePosition,
      };
    }

    const initPosition = clamp(Math.floor(-fullSize + (fullSize * initSize)), -fullSize);
    const openPosition = clamp(Math.floor(-fullSize + (fullSize * openThreshold)), -fullSize);
    const closePosition = clamp(Math.floor(-fullSize + (fullSize * closeThreshold)), -fullSize);

    return {
      fullSize: -fullSize, initPosition, openPosition, closePosition,
    };
  }, []);
}

function useDragSpring({
  open, setOpen, status, setStatus, isPartialOpen, setIsPartialOpen,
  initPosition, openPosition, closePosition, pos, setPos, fullSize, orientation,
}: {
  open: boolean;
  setOpen: (open: boolean) => void;
  status: TransitionStatus;
  setStatus: (status: TransitionStatus) => void;
  isPartialOpen: boolean;
  setIsPartialOpen: (isPartialOpen: boolean) => void;
  initPosition: number;
  openPosition: number;
  closePosition: number;
  pos: number;
  setPos: (pos: number) => void;
  fullSize: number;
  orientation: Orientation;
}) {
  const latestPosition = useLatest(pos);

  const onStop = useCallback<(newPos?: number) => void>((newPos = latestPosition.current) => {
    if (
      (isPartialOpen && newPos > initPosition)
      || (!isPartialOpen && newPos > closePosition)
    ) {
      setOpen(false);
    } else {
      setPos(openPosition);
      setIsPartialOpen(false);
    }
  }, [isPartialOpen, initPosition, openPosition, closePosition]);

  const dragInfoRef = useRef<null | number>(null);
  const isVerticalRef = useRef(orientation === 'vertical');
  const [springStyle, api] = useSpring(() => ({
    [isVerticalRef.current ? 'y' : 'x']: pos,
    config: status === 'open' || status === 'resizing'
      ? {
        ...config.default,
        clamp: isVerticalRef.current ? (pos <= 0) : (pos >= openPosition),
      } : { tension: 250, friction: 25 },
    immediate: dragInfoRef.current !== null,
    onRest: () => {
      if (dragInfoRef.current !== null) return;
      if (open) setStatus('open');
      else if (pos === fullSize) setStatus('closed');
    },
  }), [status, open, pos, fullSize]);

  const bind = useDrag(({ event, pressed, movement: [dX, dY] }) => {
    if (event.target instanceof HTMLElement && event.target.closest('.no-drag, input, textarea, select, button, [contenteditable="true"]')) {
      return;
    }

    if (dragInfoRef.current === null) {
      api.stop();
      dragInfoRef.current = (
        isVerticalRef.current
          // @ts-expect-error dynamically set above
          // eslint-disable-next-line @typescript-eslint/no-unsafe-call
          ? springStyle.y.get()
          // @ts-expect-error dynamically set above
          // eslint-disable-next-line @typescript-eslint/no-unsafe-call
          : springStyle.x.get()
        ) as number;
    }

    const newPos = (isVerticalRef.current ? dY : dX) + dragInfoRef.current;
    // const overAmount = isVerticalRef.current ? (openPosition - newPos) : (openPosition + newPos);
    // if (overAmount > 0) {
    //   newPos = openPosition * (openPosition / (openPosition + overAmount));
    // }

    setPos(newPos);
    if (!pressed) {
      onStop(newPos);
      dragInfoRef.current = null;
    }
  });

  return {
    springStyle: springStyle as {
      tension: SpringValue<number>;
      friction: SpringValue<number>;
      clamp: SpringValue<boolean>;
      x: SpringValue<number>;
      y: SpringValue<number>;
  },
    bind,
  };
}

export interface Props {
  // children: ReactNode | ((props: { isTransitioning: boolean }) => ReactElement);
  title?: string;
  TitleIcon?: FC<ClassNameProps> | ComponentClass<ClassNameProps>;
  initialFocus?: boolean;
  description?: string;
  children: ReactNode;
  open: boolean;
  setOpen: (open: boolean) => void;
  openThreshold: number;
  initSize?: number;
  closeThreshold?: number;
  status: TransitionStatus;
  setStatus: (status: TransitionStatus) => void;
  orientation: Orientation;
}

const Drawer: FC<PropsWithChildren<Props>> = (props) => {
  const {
    children, title, description, TitleIcon,
    open, setOpen, status, setStatus,
    openThreshold = 1, initSize = openThreshold,
    closeThreshold = openThreshold * 0.8, orientation,
  } = props;

  const mounted = useMounted();
  useEffect(() => {
    if (mounted) throw Error('Changing orientation, penThreshold, initSize, or closeThreshold not supported.');
  }, [openThreshold, initSize, closeThreshold, orientation]);
  useLockBodyScroll(open);
  // useEffect(() => {
  //   if (open) document.body.style.overflow = 'hidden';
  //   return () => { if (!open) document.body.style.overflow = ''; };
  // }, [open]);

  const [isPartialOpen, setIsPartialOpen] = useState(initSize !== openThreshold);

  const {
    fullSize, initPosition, openPosition, closePosition,
  } = useThresholds(orientation, openThreshold, initSize, closeThreshold);

  const [pos, setPos] = useState<number>(fullSize);

  useEffect(() => {
    if (!isPartialOpen) {
      setStatus('resizing');
      setPos(openPosition);
    }
  }, [openPosition]);
  useEffect(() => { if (status === 'opening') setPos(initPosition); }, [status, initPosition]);
  useEffect(() => { if (status === 'closing') setPos(fullSize); }, [status]);

  const { springStyle, bind } = useDragSpring({
    open,
    setOpen,
    status,
    setStatus,
    isPartialOpen,
    setIsPartialOpen,
    initPosition,
    openPosition,
    closePosition,
    pos,
    setPos,
    fullSize,
    orientation,
  });

  const opacity = Math.floor((1 - (pos / fullSize)) * 100) / 100;

  return (
    <Dialog
      className="fixed inset-0 z-20 h-screen w-screen"
      onClose={useCallback(() => { setOpen(false); }, [])}
      open
    >
      <div // overlay
        style={{ opacity }}
        className={classNames('pointer-events-auto absolute inset-0 h-[200%] bg-black/80', pos === initPosition && 'transition-opacity', isPartialOpen && 'will-change-[opacity]')}
        aria-hidden="true"
      />
      <Dialog.Panel className="pointer-events-none relative h-full w-full max-w-full">
        <animated.div
          style={springStyle}
          className={classNames('pointer-events-auto flex touch-none flex-col', orientation === 'vertical' ? 'h-screen' : 'w-screen')}
          {...bind()}
        >
          <div className={classNames(styles.flex({ c: true }), 'h-8 w-full')}>
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2} className="w-12">
              <path strokeLinecap="round" strokeLinejoin="round" d="M 3.75 12 L 20.25 12" />
            </svg>
          </div>
          <div className={classNames(styles.flex({ col: true, gap: 4 }), 'flex-auto bg-secondary p-4')}>
            <NullableComponent show={title}>
              <Dialog.Title as="h2" className={classNames(styles.flex({ cy: true, gap: 2 }), 'font-semibold leading-none text-mute')}>
                {TitleIcon && <TitleIcon className='h-5 w-5' />}
                {title}
              </Dialog.Title>
            </NullableComponent>
            <NullableComponent show={description}>
              <Dialog.Description className="text-xs leading-tight text-mute">{description}</Dialog.Description>
            </NullableComponent>
            {/* {typeof children === 'function' ? children({ isTransitioning: status !== 'open' }) : children} */}
            {children}
          </div>
        </animated.div>
      </Dialog.Panel>
    </Dialog>
  );
};

type WrapperProps = Omit<Props, 'status' | 'setStatus'>;
const Wrapper: FC<WrapperProps> = (props) => {
  const { open, setOpen } = props;

  const [status, setStatus] = useStatus(open);

  const isSSR = useIsSSR();
  return (
    <NullableComponent show={!isSSR && status !== 'closed'}>
      <Drawer
        {...props}
        open={open}
        setOpen={setOpen}
        status={status}
        setStatus={setStatus}
      />
    </NullableComponent>
  );
};

export default memo(Wrapper);

