import { ChevronDownIcon } from '@heroicons/react/20/solid';
import classNames from 'classnames';
import { memo, useCallback, useState } from 'react';
import { useFocusWithin } from 'react-aria';

import type { Placement } from '@floating-ui/react';
import type {
  ElementType, FC, HTMLProps, MutableRefObject, ReactElement, ReactNode,
} from 'react';
import type { Props as ButtonProps } from '~/components/Button';

import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import NullableComponent from '~/components/NullableComponent';
import StyledLink from '~/components/StyledLink';
import styles from '~/styles';
import { useToggleState } from '~/utils/hooks';

type NodeLabelItem = {
  label: Exclude<ReactNode, 'string'>;
  key: string;
};
type StringLabelItem = {
  label: string;
  key?: never;
};
export type DropdownItem = (NodeLabelItem | StringLabelItem) & {
  onPress?: string | ButtonProps['onPress']| null;
  outerClassName?: string;
  className?: string;
  isDisabled?: boolean;
  isSpacer?: false;
  keepOpen?: boolean;
  newTab?: boolean;
  prefetch?: boolean;
  altFocus?: boolean;
};
type DropdownSpacer = {
  isSpacer: true;
};
type Droppable = undefined | null | DropdownItem | DropdownSpacer;

interface PanelRenderPropArg {
  close: (focusableElement?: HTMLElement | MutableRefObject<HTMLElement | null>) => void;
}

// eslint-disable-next-line react/display-name
const renderItems = (items: Droppable[]) => ({ close }: PanelRenderPropArg): ReactElement => (
  <ul className={classNames(styles.flex({ col: true }), 'w-full rounded')}>
    {items.map((props, idx) => {
      if (!props) return null;

      if (props.isSpacer) {
        return (
          <div key={`spacer-${idx}`} className="my-1 h-[1px] w-11/12 self-center bg-primary" />
        );
      }

      const {
        label: btnLabel, onPress, className, keepOpen = false,
        isSpacer: _, key, newTab, prefetch, altFocus, outerClassName, ...btnProps
      } = props;

      const labelClassName = classNames('group block w-full rounded', className);

      let label;
      if (onPress === null) {
        label = (
          <div className={labelClassName}>
            {btnLabel}
          </div>
        );
      } else if (typeof onPress === 'string') {
        label = (
          <StyledLink
            href={onPress}
            className={labelClassName}
            // className={classNames('group block w-full rounded', className)}
            onClick={() => { if (!keepOpen) close(); }}
            target={newTab ? '_blank' : undefined}
            rel={newTab ? 'external nofollow noopener noreferrer' : undefined}
            prefetch={prefetch}
            altFocus={altFocus}
          >
            {btnLabel}
          </StyledLink>
        );
      } else {
        label = (
          <Button
            key={key}
            className={labelClassName}
            onPress={(evt) => { if (!keepOpen) close(); onPress?.(evt); }}
            altFocus={altFocus}
            {...btnProps}
          >
            {btnLabel}
          </Button>
        );
      }

      return (
        <li key={typeof props.label === 'string' ? props.label : key} className={outerClassName}>
          {label}
        </li>
      );
    })}
  </ul>
);

interface Props extends Omit<HTMLProps<HTMLButtonElement>, 'as' | 'label'> {
  label: ReactNode;
  items: Droppable[];
  triggerClassName?: string;
  dropdownClassName?: string;
  labelOnly?: boolean;
  placement?: Placement;
  gap?: boolean;
  noPad?: boolean;
  noBackground?: boolean;
  portal?: boolean;
  maxItems?: number;
  as?: ElementType;
  isDisabled?: boolean;
}
const Dropdown: FC<Props> = (props) => {
  const {
    label, items, triggerClassName, dropdownClassName, labelOnly,
    placement = 'bottom-start', gap, noBackground, noPad, portal,
    maxItems, ...attributes
  } = props;

  const [isOpen, { set: setOpen, setFalse: close }] = useToggleState();

  const [triggerRef, setTriggerRef] = useState<HTMLElement | null>(null);

  const { focusWithinProps } = useFocusWithin({ onBlurWithin: close });

  return (
    <AnchoredPopover
      open={isOpen}
      onOpenChange={setOpen}
      placement={placement}
      dataState="opened"
    >
      <AnchoredPopover.Trigger
        {...attributes}
        forwardedRef={setTriggerRef}
        className={classNames(
          styles.flex({ c: true }),
          !labelOnly && 'gap-1 rounded',
          !noPad && 'pr-2 pl-3',
          !noBackground && 'rounded bg-secondary shadow drop-shadow dark:bg-tertiary',
