        </NullableComponent>
      </AnchoredPopover.Trigger>
      <AnchoredPopover.Child
        portal={portal}
        style={{ minWidth: `${triggerRef?.offsetWidth ?? 0}px`, maxHeight: maxItems ? `${maxItems * 2.5}rem` : undefined }}
        className={classNames('overflow-auto rounded border border-solid border-secondary bg-secondary p-1 shadow dark:border-primary dark:bg-tertiary', dropdownClassName)}
        {...styles.transition({
          transition: 'transition ease-out',
