  const {
    scale,
    onEmojiClick,
    search,
    selectedSkinTone,
    setActiveEmoji,
    customCategories,
    categoryScrollTops,
    scrollSidebar,
    setSearch,
    setSelectedSkinTone,
    showMobileSearch = false,
    setShowMobileSearch,
  } = props;
  const isMobile = useIsMobile();

  const [collapsedCategories, setCollapseCategories] = useState<Set<string>>(new Set());

  const {
    heightStyle, rowCount, categoryComponents, currentPositions, setPositions,
  } = useCategoryPositions(customCategories, collapsedCategories, search, scale, showMobileSearch && isMobile);
  const onScroll = useScrollCalculator(categoryComponents, setPositions, scale);

  categoryScrollTops.current = categoryComponents.reduce<Record<string, number>>((acc, { category, topOffset }) => {
    acc[getCategoryIdentifier(category)] = topOffset;
    return acc;
  }, {});

  const topOffset = useMemo(() => {
    let offset = 0;
    if (currentPositions[0]?.emojiRows[0]?.topOffset) {
      offset += currentPositions[0].emojiRows[0].topOffset - EMOJI_HEADER_HEIGHT;
    } else if (currentPositions[0]?.position.bottomOffset) {
      offset += currentPositions[0].position.bottomOffset - EMOJI_HEADER_HEIGHT;
    }
    if (offset === MOBILE_SEARCH_HEADER_HEIGHT && isMobile && showMobileSearch) {
      offset -= MOBILE_SEARCH_HEADER_HEIGHT;
    }
    return offset;
  }, [categoryComponents, currentPositions, isMobile, showMobileSearch]);

  const localRef = useRef<HTMLDivElement>(null);
  const scrollRef = mergeRefs([localRef, propRef]);
  useEffect(() => {
    if (localRef.current) onScroll({ currentTarget: localRef.current });
  }, [localRef.current, categoryComponents]);

  useEffect(() => {
    scrollSidebar(
      getCategoryIdentifier(currentPositions[0].position.category),
      currentPositions[1]?.position.category.name === defaultEmojiCategories[0].name,
    );
  }, [currentPositions[0]]);

  return (
    <div className='relative grid grid-rows-[auto_1fr] grid-row-[2/3] grid-col-[2/3]'>
      <div className='relative overflow-hidden grid-row-[2/2]'>
        <div className='absolute inset-0'>
          <div
            ref={scrollRef}
            className='scrollbar relative h-full min-h-0 overflow-x-hidden overflow-y-scroll mobile:mb-8'
            onScroll={onScroll}
          >
            <div
              role="treegrid"
              style={{ inset: `${topOffset}px 0 0.5rem ${isMobile ? 0 : 0.5}rem` }}
              aria-rowcount={rowCount}
              aria-colcount={EMOJI_ROW_LENGTH}
              className='absolute contain-layout'
            >
              <NullableComponent show={showMobileSearch && isMobile && topOffset < MOBILE_SEARCH_HEADER_HEIGHT}>
                <Header
                  search={search ?? ''}
                  setSearch={setSearch}
                  selectedSkinTone={selectedSkinTone}
                  setSelectedSkinTone={setSelectedSkinTone}
                  setShowMobileSearch={setShowMobileSearch}
                />
              </NullableComponent>
              {currentPositions.map((visibleCategory) => (
                <Section
                  scale={scale}
                  key={getCategoryIdentifier(visibleCategory.position.category)}
                  visibleCategory={visibleCategory}
                  onEmojiClick={onEmojiClick}
                  selectedSkinTone={selectedSkinTone}
                  setActiveEmoji={setActiveEmoji}
                  collapsed={collapsedCategories.has(getCategoryIdentifier(visibleCategory.position.category))}
                  setCollapsed={setCollapseCategories}
                />
              ))}
            </div>
            <div style={heightStyle} className='invisible' />
          </div>
        </div>
      </div>
    </div>
  );
}

