import { useMemo, useState } from 'react';

import { defaultEmojiCategories, getCategoryIdentifier } from '../../utils';
import isCustom from '../../utils/isCustom';

import {
  EMOJI_DIMENSIONS, EMOJI_HEADER_HEIGHT, EMOJI_LIST_LENGTH, EMOJI_ROW_LENGTH, MOBILE_SEARCH_HEADER_HEIGHT,
} from './constants';

import type {
  CustomCategory, DefaultEmojiCategory, EmojiCategory, EmojiType, SearchCategory,
} from '../EmojiPicker.types';
import type { EmojiRowType, PositionedCategory, VisibleCategory } from './EmojiList.types';

import { useFrequentEmojis } from '~/utils/hooks';

const MARGIN_BOTTOM = 12;
const SEARCH_PIXEL_OFFSET = 8;

const isSearchResult = (name: string, search: string): boolean => (search.startsWith(':') || search.endsWith(':') ? `:${name.toLocaleLowerCase()}:` : name.toLocaleLowerCase()).includes(search.toLocaleLowerCase());
const filterEmojis = (emoji: EmojiType, search: string): boolean => (isCustom(emoji)
  ? isSearchResult(emoji.name, search)
  : emoji.names.some((n) => isSearchResult(n, search)));

export default (customCategories: CustomCategory[], collapsedCategories: Set<string>, search: string | null, scale: number, showMobileSearch: boolean) => {
  const { current: frequentEmojis } = useFrequentEmojis();

  const allEmojis = useMemo<EmojiType[]>(() => [
    ...customCategories, ...defaultEmojiCategories,
  ].reduce<EmojiType[]>((acc, { emojis }) => acc.concat(emojis), []), [customCategories]);

  const categoryComponents = useMemo<PositionedCategory[]>(() => positionCategories(
    frequentEmojis,
    allEmojis,
    customCategories,
    search,
    collapsedCategories,
    scale,
    showMobileSearch,
  ), [frequentEmojis, customCategories, search, collapsedCategories]);

  const { heightStyle, rowCount } = useMemo(() => {
    let totalHeight = 0;
    let count = 0;
    for (const { emojiRows, height } of categoryComponents) {
      count += emojiRows.length;
      totalHeight += height;
    }
    return { rowCount: count, heightStyle: { height: `${totalHeight}px` } };
  }, [categoryComponents]);

  const [currentPositions, setPositions] = useState<VisibleCategory[]>([{
    position: categoryComponents[0],
    emojiRows: categoryComponents[0].emojiRows.slice(0, EMOJI_LIST_LENGTH),
  }]);
  return {
    heightStyle, categoryComponents, currentPositions, setPositions, rowCount,
  };
};

function positionCategories(
  frequentEmojis: EmojiType[],
  allEmojis: EmojiType[],
  customCategories: CustomCategory[],
  search: string | null,
  collapsedCategories: Set<string>,
  scale: number,
  showMobileSearch: boolean,
) {
  if (search !== null) {
    return insertCategory(
      {
        name: 'search',
        emojis: allEmojis.filter((e) => search && filterEmojis(e, search)),
      } as SearchCategory,
      collapsedCategories,
      [],
      scale,
      showMobileSearch,
    );
  }

  const tmp: PositionedCategory[] = [];
  if (frequentEmojis.length) {
    insertCategory(
      { name: 'frequentlyUsed', emojis: frequentEmojis } as DefaultEmojiCategory,
      collapsedCategories,
      tmp,
      scale,
      showMobileSearch,
    );
  }
  for (const category of customCategories) insertCategory(category, collapsedCategories, tmp, scale, showMobileSearch);
  for (const category of defaultEmojiCategories) insertCategory(category, collapsedCategories, tmp, scale, showMobileSearch);
  return tmp;
}

function insertCategory(
  category: EmojiCategory,
  collapsedCategories: Set<string>,
  categoryComponents: PositionedCategory[],
  scale: number,
  showMobileSearch: boolean,
) {
  const emojis = collapsedCategories.has(getCategoryIdentifier(category)) ? [] : category.emojis;

  const prev = categoryComponents.at(-1);
  let topOffset = showMobileSearch ? MOBILE_SEARCH_HEADER_HEIGHT : 0;
  if (!isCustom(category) && category.name === 'search') topOffset += SEARCH_PIXEL_OFFSET;
  if (prev) topOffset = prev.bottomOffset;

  const scaledEmojiDimensions = EMOJI_DIMENSIONS * scale;

  const expandedHeight = emojis.length ? Math.ceil(emojis.length / EMOJI_ROW_LENGTH) * scaledEmojiDimensions + MARGIN_BOTTOM : 0;
  const height = EMOJI_HEADER_HEIGHT + expandedHeight;
  const bottomOffset = topOffset + height;

  const startRowIndex = categoryComponents.reduce((acc, { emojiRows }) => acc + emojiRows.length, 1);
  const preEmojiRows = (emojis as EmojiType[]).reduce<EmojiType[][]>((acc, emoji, i) => {
    if (i % EMOJI_ROW_LENGTH === 0) acc.push([]);
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    acc.at(-1)!.push(emoji);
    return acc;
  }, []);
  const emojiRows = preEmojiRows.map<EmojiRowType>((e, i) => {
    const rowTopOffset = topOffset + EMOJI_HEADER_HEIGHT + (i * scaledEmojiDimensions);
    const rowBottomOffset = rowTopOffset + scaledEmojiDimensions;
    return {
      topOffset: rowTopOffset,
      bottomOffset: rowBottomOffset,
      emojis: e,
      ariaIndex: startRowIndex + i,
    };
  });

  categoryComponents.push({
    topOffset, bottomOffset, height, category, emojiRows,
  });

  return categoryComponents;
}

import { useCallback } from 'react';

import { getCategoryIdentifier, isSameEmoji } from '../../utils';

import { EMOJI_DIMENSIONS, EMOJI_LIST_LENGTH } from './constants';

import type { Dispatch, SetStateAction } from 'react';
import type { PositionedCategory, VisibleCategory } from './EmojiList.types';

export default (
  categoryComponents: PositionedCategory[],
  setPositions: Dispatch<SetStateAction<VisibleCategory[]>>,
  scale: number,
) => useCallback<(e: { currentTarget: { scrollTop: number }}) => void>((e) => {
  const { scrollTop } = e.currentTarget;

  const scaledEmojiDimensions = EMOJI_DIMENSIONS * scale;
  const { newPositions } = categoryComponents.reduce<{ newPositions: VisibleCategory[], rowCount: number }>((acc, category) => {
    if (acc.rowCount >= EMOJI_LIST_LENGTH) return acc;

    const minScroll = category.topOffset - EMOJI_LIST_LENGTH * scaledEmojiDimensions;
    const maxScroll = category.bottomOffset;
    const isVisible = scrollTop > minScroll && scrollTop < maxScroll;
    if (isVisible) {
      const start = Math.max(0, Math.floor((scrollTop - category.topOffset) / scaledEmojiDimensions));
      const end = Math.min(category.emojiRows.length, start + EMOJI_LIST_LENGTH - (acc.newPositions[0]?.emojiRows.length ?? 0));
      const emojiRows = category.emojiRows.slice(start, end);
      acc.newPositions.push({ position: category, emojiRows });
    }
    return acc;
  }, { newPositions: [], rowCount: 0 });

  setPositions((old) => {
    const oldFirst = old.at(0);
    const newFirst = newPositions.at(0);
    const oldLast = old.at(-1);
    const newLast = newPositions.at(-1);

    const oldFirstId = oldFirst && getCategoryIdentifier(oldFirst.position.category);
    const newFirstId = newFirst && getCategoryIdentifier(newFirst.position.category);
    const oldLastId = oldLast && getCategoryIdentifier(oldLast.position.category);
    const newLastId = newLast && getCategoryIdentifier(newLast.position.category);

    if (
      old.length !== newPositions.length
        || oldFirstId !== newFirstId
        || oldLastId !== newLastId
        || oldFirst?.emojiRows.at(0)?.ariaIndex !== newFirst?.emojiRows.at(0)?.ariaIndex
        || oldLast?.emojiRows.at(-1)?.ariaIndex !== newLast?.emojiRows.at(-1)?.ariaIndex
        || oldFirst?.position.category.emojis?.length !== newFirst?.position.category.emojis?.length
        || !isSameEmoji(oldFirst?.position.category.emojis.at(0), newFirst?.position.category.emojis.at(0))
    ) {
      return newPositions;
    }
    return old;
  });
}, [categoryComponents, scale]);

