const mainEmojiUrl = 'url("/assets/emoji_sheet_1.png")';
const diversityUrls: string[] = [
  'url("/assets/emoji_sheet_2.png")', 'url("/assets/emoji_sheet_3.png")',
  'url("/assets/emoji_sheet_4.png")', 'url("/assets/emoji_sheet_5.png")',
  'url("/assets/emoji_sheet_6.png")', 'url("/assets/emoji_sheet_7.png")',
];

function emojiIsDiverse(emoji: EmojiSurrogate): emoji is DiverseEmojiSurrogate {
  return 'hasDiversity' in emoji && !!emoji.hasDiversity;
}

const separatedEmojis = defaultEmojiCategories.reduce<{ diverse: DiverseEmojiSurrogate[], nonDiverse: EmojiSurrogate [] }>(
  (acc, category) => {
    const diverse = category.emojis.filter(emojiIsDiverse);
    const nonDiverse = category.emojis.filter((emoji) => !emojiIsDiverse(emoji));

    return {
      diverse: [...acc.diverse, ...diverse],
      nonDiverse: [...acc.nonDiverse, ...nonDiverse],
    };
  },
  { diverse: [], nonDiverse: [] },
);

export const emojiNameWithColons = (emoji: EmojiType): string => (isCustom(emoji) ? `:${emoji.name}:` : emoji.names.map((name) => `:${name}:`).join(' '));

export const getEmojiCharacter = (emoji: EmojiSurrogate, selectedTone: number): string => {
  // subtract 1 because selectedTone includes the default tone as 0
  if (selectedTone) return emoji.diversityChildren?.[selectedTone - 1]?.surrogates ?? emoji.surrogates;

  return emoji.surrogates;
};

export const getCustomEmojiUrl = ({ id, animated }: CustomEmoji, size: number): string => `${DISCORD_CDN_BASE}/emojis/${id}.${animated ? 'gif' : 'png'}?size=${getValidCdnSize(size)}&quality=lossless`;
export const charToSvgUrl = (emojiChar: string) => `${TWEMOJI_EMOJI_BASE}/${Twemoji.convert.toCodePoint(emojiChar)}.svg`;

const BACKGROUND_EMOJI_DIMENSIONS = 40;
const DIVERSE_BACKGROUND_EMOJI_ROW_LENGTH = 10;
const NONDIVERSE_BACKGROUND_EMOJI_ROW_LENGTH = 42;

const DIVERSITY_BACKGROUND_IMAGE_WIDTH = 400;
const DIVERSITY_BACKGROUND_IMAGE_HEIGHT = 1160;
const NONDIVERSITY_BACKGROUND_IMAGE_WIDTH = 1680;
const NONDIVERSITY_BACKGROUND_IMAGE_HEIGHT = 1520;

const rowPosition = (rowIdx: number, isDiverse: boolean, scale: number) => {
  const rowLength = isDiverse ? DIVERSE_BACKGROUND_EMOJI_ROW_LENGTH : NONDIVERSE_BACKGROUND_EMOJI_ROW_LENGTH;
  const position = (rowIdx % rowLength) * BACKGROUND_EMOJI_DIMENSIONS * scale;
  return Math.ceil(position * 100) / 100;
};

const colPosition = (colIdx: number, scale: number) => {
  const position = colIdx * BACKGROUND_EMOJI_DIMENSIONS * scale;
  return Math.ceil(position * 100) / 100;
};

export function defaultEmojiToBackgroundStyle(emoji: EmojiSurrogate | DiverseEmojiSurrogate, selectedTone: number, style: CSSProperties = {}, svg = false, scale = 1) {
  if (svg) {
    return {
      ...style,
      backgroundImage: `url("${charToSvgUrl(getEmojiCharacter(emoji, selectedTone))}")`,
    };
  }

  if (emojiIsDiverse(emoji)) {
    const url = diversityUrls[selectedTone];
    const rowIdx = separatedEmojis.diverse.findIndex((e) => e.names[0] === emoji.names[0]);
    const colIdx = Math.floor(rowIdx / DIVERSE_BACKGROUND_EMOJI_ROW_LENGTH);

    const scaledWidth = DIVERSITY_BACKGROUND_IMAGE_WIDTH * scale;
    const scaledHeight = DIVERSITY_BACKGROUND_IMAGE_HEIGHT * scale;

    return {
      ...style,
      backgroundImage: url,
      backgroundSize: `${scaledWidth}px ${scaledHeight}px`,
      backgroundPosition: `-${rowPosition(rowIdx, true, scale)}px -${colPosition(colIdx, scale)}px`,
    };
  }

  const rowIdx = separatedEmojis.nonDiverse.findIndex((e) => e.names[0] === emoji.names[0]);
  const colIdx = Math.floor(rowIdx / NONDIVERSE_BACKGROUND_EMOJI_ROW_LENGTH);

  const scaledWidth = NONDIVERSITY_BACKGROUND_IMAGE_WIDTH * scale;
  const scaledHeight = NONDIVERSITY_BACKGROUND_IMAGE_HEIGHT * scale;

  return {
    ...style,
    backgroundImage: mainEmojiUrl,
    backgroundSize: `${scaledWidth}px ${scaledHeight}px`,
    backgroundPosition: `-${rowPosition(rowIdx, false, scale)}px -${colPosition(colIdx, scale)}px`,
  };
}

export function isSameEmoji(a: undefined | EmojiType, b: undefined | EmojiType): boolean {
  if (a === undefined || b === undefined) return false;
  if (isCustom(a) && isCustom(b)) return a.id === b.id;
  if (!isCustom(a) && !isCustom(b)) return a.surrogates === b.surrogates;
  return false;
}

export const getCategoryIdentifier = (category: EmojiCategory): string => (isCustom(category) ? category.id : category.name);

