import classNames from 'classnames';
import {
  createContext, memo, use, useRef,
} from 'react';
import {
  mergeProps, useFocusRing, useRadio, useRadioGroup,
} from 'react-aria';
import { useRadioGroupState } from 'react-stately';

import NullableComponent from './NullableComponent';

import type { FC, ReactNode } from 'react';
import type { AriaRadioProps } from 'react-aria';
import type { RadioGroupProps, RadioGroupState } from 'react-stately';
import type { FlexOptions } from '~/styles';

import RadioButtonChecked from '~/assets/svg/RadioButtonChecked';
import RadioButtonUnchecked from '~/assets/svg/RadioButtonUnchecked';
import styles from '~/styles';

export interface RadioOption<T extends string> extends AriaRadioProps {
  key?: string;
  label: string;
  value: T;
  subLabel?: ReactNode;
}

const RadioContext = createContext<RadioGroupState | null>(null);
const useRadioContext = () => {
  const context = use(RadioContext);

  if (context == null) {
    throw new Error('RadioContext components must be wrapped in <RadioContext />');
  }

  return context;
};

const RadioButton: FC<AriaRadioProps & { altBackground?: boolean }> = (props) => {
  const { altBackground, children } = props;
  const state = useRadioContext();
  const ref = useRef(null);
  const { inputProps, isSelected, isDisabled } = useRadio(props, state, ref);
  const { isFocusVisible, focusProps } = useFocusRing();

  let radio;
  if (isSelected) radio = <RadioButtonChecked className='h-5 w-5 shrink-0' />;
  else radio = <RadioButtonUnchecked className='h-5 w-5 shrink-0' />;

  return (
    <label
      style={{ opacity: isDisabled ? 0.85 : 1 }}
      className={classNames(
        styles.flex({ cy: true }),
        'group/radio-item block rounded px-4 py-2 pr-8',
        altBackground
          ? 'bg-secondary-alt ui-checked:bg-tertiary dark:bg-tertiary dark:ui-checked:bg-secondary-alt '
          : 'bg-tertiary ui-checked:bg-secondary',
        !isDisabled && 'ui-not-checked:cursor-pointer',
        !isDisabled && isFocusVisible && 'enabled:focus-visible-alt',
        !isDisabled && (altBackground
          ? 'enabled:ui-not-checked:focus-within:brightness-95 enabled:ui-not-checked:hover:brightness-95 enabled:dark:ui-not-checked:focus-within:brightness-110 enabled:dark:ui-not-checked:hover:brightness-110'
          : 'enabled:focus-within:bg-secondary-alt enabled:hover:bg-secondary-alt'),
      )}
      data-headlessui-state={isSelected ? 'checked' : 'unchecked'}
    >
      <input {...mergeProps(inputProps, focusProps)} ref={ref} />
      <span className={classNames(styles.flex({ cy: true, gap: 2 }), 'w-full')}>
        {radio}
        {children}
      </span>
    </label>
  );
};

interface Props<T extends string> extends Omit<RadioGroupProps, 'onChange'> {
  value: T;
  onChange: ((val: T) => void);
  label?: string;
  options: RadioOption<T>[];
  altBackground?: boolean;
  gap?: FlexOptions['gap'];
}
const RadioButtonGroup = <T extends string>(props: Props<T>) => {
  const {
    label, description, options, altBackground, gap = 2,
    // errorMessage, validationState,
  } = props;
  const state = useRadioGroupState(props as unknown as RadioGroupProps);
  const { radioGroupProps, labelProps, descriptionProps } = useRadioGroup(props as unknown as RadioGroupProps, state);

  return (
    <div {...radioGroupProps} className={styles.flex({ col: true, gap })}>
      <NullableComponent show={label}>
        <span {...labelProps}>{label}</span>
      </NullableComponent>
      <RadioContext.Provider value={state}>
        {options.map(({
          key, label: radioLabel, subLabel, value, isDisabled, ...rest
        }) => (
          <RadioButton
            key={key ?? radioLabel.toLowerCase().replace(/ /g, '-')}
            altBackground={altBackground}
            value={value}
            isDisabled={isDisabled}
            {...rest}
          >
            {/* react-aria wants radiobutton to have children */}
            <div className={classNames(
              styles.flex({ col: true }),
              'w-full justify-between brightness-75 ui-checked:brightness-100',
              !isDisabled && 'group-focus-within/radio-item:brightness-100 group-hover/radio-item:brightness-100',
            )}
            >
              <div className="overflow-hidden text-ellipsis whitespace-nowrap">{radioLabel}</div>
              <NullableComponent show={subLabel}>
                <div className={styles.subLabel}>{subLabel}</div>
              </NullableComponent>
            </div>
          </RadioButton>
        ))}
      </RadioContext.Provider>
      {description && <div {...descriptionProps} style={{ fontSize: 12 }}>{description}</div>}
      {/* {errorMessage && validationState === 'invalid'
      && (
        <div {...errorMessageProps} style={{ color: 'red', fontSize: 12 }}>
          {errorMessage}
        </div>
      )} */}
    </div>
  );
};

export default memo(RadioButtonGroup) as typeof RadioButtonGroup;

