import type { StrictSingleASTNode } from 'simple-markdown';
import type { Element, Path, Range } from 'slate';

interface Cursor {
  position: number;
  moveBy: (val: number) => number;
}

function createCursor(): Cursor {
  let current = 0;
  return {
    get position() { return current; },
    moveBy(val) {
      current += val;
      return current;
    },
  };
}

interface Branch {
  final: () => void;
}
function createBranch(cursor: Cursor, range: Range): Branch {
  return {
    final() {
      range.focus.offset = cursor.moveBy(0);
    },
  };
}

export interface DecoratedLeaf {
  ranges: Range[];
  lang: string;
  jump: Cursor['moveBy'];
  branch: (ast: string | StrictSingleASTNode) => undefined | Branch;
  grow: (length: number, ast?: string | StrictSingleASTNode) => undefined | Range;
}
export default function createLeaf(path: Path, lang: Element['lang']): DecoratedLeaf {
  const cursor = createCursor();
  const ranges: Range[] = [];

  return {
    get ranges() { return [...ranges]; },
    get lang() { return lang; },
    branch(ast) {
      const range = this.grow(0, ast);
      if (!range) {
        cursor.moveBy(0);
        return undefined;
      }
      return createBranch(cursor, range);
    },
    jump: cursor.moveBy,
    grow(length, ast) {
      const start = cursor.position;
      const end = cursor.moveBy(length);

      const classNames: string[] = [];
      let syntax = false;
      if (ast === 'syntax') {
        syntax = true;
      } else if (typeof ast === 'string') {
        classNames.push(ast);
      } else if (ast) {
        const className = astToClassName(ast);
        if (className) classNames.push(className);
      }

      if (!syntax && !classNames.length) return undefined;

      const range: Range = {
        anchor: { path, offset: start },
        focus: { path, offset: end },
        classNames,
        syntax,
      };
      ranges.push(range);
      return range;
    },
  };
}

function astToClassName(ast: StrictSingleASTNode): undefined | string {
  if (ast.partialCodeBlock) return 'codeBlockText';
  switch (ast.type) {
    case 'autolink':
    case 'link':
    case 'url':
      return 'linkText';
    case 'inlineCode': return 'inlineCodeText';
    case 'em': return 'emText';
    case 's': return 'sText';
    case 'spoiler': return 'spoilerText';
    case 'strong': return 'strongText';
    case 'u': return 'uText';
    default: return undefined;
  }
}

import hljs from 'highlight.js';
import { Editor, Text } from 'slate';

import createLeaf from './createLeaf';

import type { Emitter, Node } from 'highlight.js';
import type { InteractiveParser, MarkdownTypes, StrictSingleASTNode } from 'simple-markdown';
import type { Element, NodeEntry, Range } from 'slate';
import type { DecoratedLeaf } from './createLeaf';

const OFFSETS = new Map<undefined | MarkdownTypes, number>([
  ['em', 1],
  ['strong', 2],
  ['u', 2],
  ['s', 2],
  ['spoiler', 2],
  ['link', 1],
]);

function reduceAdjacentSyntax(acc: number, ast: StrictSingleASTNode, reverse?: boolean): number {
  const { content } = ast;
  if (!content || !Array.isArray(content)) return acc;

  const child = reverse ? content.at(-1) : content[0];
  if (!child) return acc;

  const offset = OFFSETS.get(child?.type) ?? 0;
  acc += offset;
  if (!offset) return acc;

  return reduceAdjacentSyntax(acc, child, reverse);
}

function walkAst(leaf: DecoratedLeaf, ast: StrictSingleASTNode, edgeChild: { first?: boolean, last?: boolean } = {}) {
  if ('content' in ast) {
    if (leaf.lang !== '' && typeof ast.content === 'string') {
      handleCodeBlockRange(leaf, leaf.lang, ast.content);
      return;
    }

    const offset = OFFSETS.get(ast.type);
    if (offset && !edgeChild.first) leaf.grow(offset + reduceAdjacentSyntax(0, ast), 'syntax');

    const branch = leaf.branch(ast);

    const astContent = ast.content;
    if (Array.isArray(astContent)) astContent.forEach((a) => walkAst(leaf, a, { first: a === astContent.at(-1) }));
    else if (typeof astContent === 'string') leaf.jump(astContent.length);
    branch?.final();

    if (offset && !edgeChild.last) leaf.grow(offset + reduceAdjacentSyntax(0, ast, true), 'syntax');
    if (ast.type === 'link' && ast.target) {
      leaf.grow(1, 'syntax');
      leaf.grow(ast.target.length, 'linkText');
      leaf.grow(1, 'syntax');
    }

    if (ast.type === 'text') return;

    return;
  }

  if (ast.type === 'codeBlock') {
    leaf.grow(3, 'syntax');
    leaf.grow(ast.lang.length, hljs.getLanguage(ast.lang) ? 'lang' : undefined);
  }
}

function handleCodeBlockRange(leaf: DecoratedLeaf, lang: string, content: string) {
  if (hljs.getLanguage(lang) !== undefined) {
    const highlightedBlock = hljs.highlight(content, { language: lang, ignoreIllegals: true });
    (highlightedBlock._emitter as unknown as Emitter).rootNode.children.forEach((block) => { walkCodeBlock(leaf, lang, block); });
  }
}

function constructClassName(scope: string) {
  const names = scope.split('.');
  let pad = 0;
  return names.map((n) => n + '_'.repeat(pad++)).join(' ');
}

function walkCodeBlock(leaf: DecoratedLeaf, lang: string, block: Node) {
  if (typeof block === 'string') {
    leaf.jump(block.length);
  } else {
    const branch = leaf.branch(`hljs-${block.scope ? constructClassName(block.scope) : ''}`);
    block.children.forEach((child) => { walkCodeBlock(leaf, lang, child); });
    branch?.final();
  }
}

const MERGE_NODES = new Set(['paragraph', 'text']);

function normalizeAst(ast: StrictSingleASTNode[]): StrictSingleASTNode[] {
  const normalized: StrictSingleASTNode[] = [];
  for (const a of ast) {
    const prevNode = normalized.at(-1);
    if (prevNode && 'content' in a && 'content' in prevNode) {
      if (MERGE_NODES.has(a.type) && MERGE_NODES.has(prevNode?.type) && typeof prevNode.content === 'string' && typeof a.content === 'string') {
        prevNode.content += a.content;
      } else if (Array.isArray(a.content)) {
        normalized.push({ ...a, content: normalizeAst(a.content) } as StrictSingleASTNode);
      } else {
        normalized.push(a);
      }
    } else {
      normalized.push(a);
    }
  }
  return normalized;
}

function adjacentSyntax(a: Range, b: Range) {
  return a.syntax && b.syntax && a.focus.offset === b.anchor.offset;
}

function isSamePoint(a: Range, b: Range) {
  return a.anchor.offset === b.anchor.offset && a.focus.offset === b.focus.offset;
}

function isChild(parent: Range, child: Range) {
  return parent.anchor.offset <= child.anchor.offset && child.focus.offset <= parent.focus.offset;
}

function normalizeRanges(ranges: Range[]): Range[] {
  if (!ranges.length) return [];
  const normalized: Range[] = [ranges.shift() as Range];

  let prevMarkup: Range | null = normalized[0].syntax ? normalized[0] : null;
  for (const range of ranges) {
    const prev = normalized.at(-1) as Range;
    if (adjacentSyntax(prev, range)) {
      prev.focus.offset = range.focus.offset;
    } else if (isSamePoint(prev, range)) {
      prev.classNames.push(...range.classNames);
    } else if (prevMarkup && isChild(prevMarkup, range)) {
      range.classNames.push(...prev.classNames);
      normalized.push(range);
    } else {
      normalized.push(range);
    }
    if (!range.syntax) prevMarkup = range;
  }

  return normalized;
}

export default (editor: Editor, mounted: boolean, isEmbed: boolean, parserContent: InteractiveParser) => ([node, path]: NodeEntry): Range[] => {
  if (!Text.isText(node)) return [];
  const [ancestor] = Editor.above(editor, { at: path }) as NodeEntry<Element>;

  const ast = parserContent(node.text, { inCodeBlock: ancestor.startCodeBlock, mounted, isEmbed });
  const rootNode = ast[0];
  const normalized = Array.isArray(rootNode.content) ? normalizeAst(rootNode.content) : [rootNode];
  const leaf = createLeaf(path, ancestor.lang);
  for (const a of normalized) walkAst(leaf, a);

  return normalizeRanges(leaf.ranges);
};

import { isEmojiElement, isEmojiNode } from './common';

import type { InteractiveParser } from 'simple-markdown';
import type { Descendant, Element, Text } from 'slate';

export default (input: string, parseEmoji: InteractiveParser, partialMarkdown: boolean): Descendant[] => {
  if (input.length === 0) {
    return [{
      type: 'div',
      lang: '',
      startCodeBlock: false,
      empty: true,
      children: [{ type: 'span', text: '' }],
    }];
  }

  const descendants: Descendant[] = [];
  let inCodeBlock = false;
  let inMultilineBlockQuote = false;
  let currentLang: null | string = null;
  for (let text of input.split('\n')) {
    const blocks = text.split('```');
    const containsBlockEnd = blocks.length > 1;
    const isCodeBlock = !partialMarkdown && inCodeBlock && !containsBlockEnd;

    const multilineStart: boolean = !inMultilineBlockQuote && /^ *>>> /.test(text);
    if (multilineStart) text = text.replace(/^ *>>> /, '');
    inMultilineBlockQuote = inMultilineBlockQuote || multilineStart;
    const isBlockQuote = !partialMarkdown && !isCodeBlock && (inMultilineBlockQuote || /^ *> /.test(text));

    let children: Array<Element | Text>;
    let type: Element['type'];
    if (isCodeBlock) {
      children = [{ type: 'span', text }];
      type = 'codeBlock';
    } else {
      if (isBlockQuote) {
        // if (inMultilineBlockQuote && !text.startsWith('> ')) {
        //   text = multilineStart ? `> ${text.replace(/^ *>>> /, '')}` : `> ${text}`;
        // }
        text = text.replace(/^ *> /, '');
        type = 'blockQuote';
      } else {
        type = 'div';
      }

      children = [];
      if (text.length) {
        const ast = parseEmoji(text);
        let curText = '';
        for (const node of ast) {
          if (isEmojiNode(node)) {
            children.push({ type: 'span', text: curText });
            curText = '';
            children.push({
              type: 'emoji',
              lang: '',
              startCodeBlock: false,
              ast: node,
              children: [{ type: 'span', text: '' }],
              empty: false,
            });
          } else {
            const nodeText = node.content as string;
            curText += ast.at(-1) === node ? nodeText.slice(0, nodeText.length - 2) : nodeText;
          }
        }

        if (curText.length) children.push({ type: 'span', text: curText });
        else if (isEmojiElement(children.at(-1))) {
          children.push({ type: 'span', text: '' });
        }
      } else {
        children = [{ type: 'span', text: '' }];
      }
    }

    const node: Element = {
      type,
      lang: (isCodeBlock && currentLang) || '',
      startCodeBlock: inCodeBlock,
      children,
      empty: !text.length,
    };

    if (!partialMarkdown) {
      const res = /```([A-Za-z0-9-]*)$/.exec(text);
      if (res && !inCodeBlock) currentLang = res[1] ?? '';
      if (blocks.length % 2 === 0) inCodeBlock = !inCodeBlock;
      if (!inCodeBlock) currentLang = null;
    }

    descendants.push(node);
  }

  return descendants;
};

import { Transforms } from 'slate';

import type {
  Descendant, Editor, Range, SelectionOperation,
} from 'slate';

export default (editor: Editor, setDescendants: (descendants: Descendant[]) => void) => (descendants: Descendant[]) => {
  if (!editor.operations.length) return;

  const isSelectionChange = editor.operations.every((op) => op.type === 'set_selection');
  if (isSelectionChange) {
    const [{ newProperties, properties }] = editor.operations as SelectionOperation[];
    if (newProperties && properties && 'anchor' in newProperties) {
      const { anchor } = newProperties as Range;
      const { anchor: prevAnchor } = properties as Range;
      if (anchor?.path.length === 3) {
        const { path: [, nodePos] } = anchor;
        const { path: [, prevNodePos] } = prevAnchor;

        if (Math.abs(nodePos - prevNodePos) !== 1) return;

        const path = anchor.path.slice(0, 2);
        path[1] += nodePos > prevNodePos ? 1 : -1;

        Transforms.select(editor, {
          anchor: { path, offset: 0 },
          focus: { path, offset: 0 },
          offset: 0,
          classNames: [],
        });
      }
    }
  } else {
    setDescendants(descendants);
  }
};

import { Node, Transforms } from 'slate';

import type { KeyboardEvent, KeyboardEventHandler } from 'react';
import type { CustomRange, Editor, Element } from 'slate';

export default (editor: Editor, partialMarkdown: boolean, propsHandler: undefined | KeyboardEventHandler<HTMLDivElement>) => (event: KeyboardEvent<HTMLDivElement>) => {
  propsHandler?.(event);
  if (event.defaultPrevented) return;

  const { selection } = editor;
  if (event.key === 'Backspace' && selection) {
    normalizeBackspace(editor, selection, event);
  } else if (partialMarkdown && event.key === 'Enter') {
    event.preventDefault();
  }
};

function normalizeBackspace(editor: Editor, selection: CustomRange, event: KeyboardEvent<HTMLDivElement>) {
  const { anchor, focus } = selection;
  const collapsed = anchor.path.every((p, idx) => focus.path[idx] === p) && anchor.offset === focus.offset;
  const selectionAtBeginning = anchor.path[1] === 0 && (anchor.offset === 0 || focus.offset === 0);

  if (selectionAtBeginning) {
    const element = Node.get(editor, [anchor.path[0]]) as Element;
    if ((collapsed && element.empty) || element.type === 'blockQuote') {
      let prevent = false;
      if (element.type === 'blockQuote') {
        prevent = true;
        Transforms.setNodes(editor, { ...element, type: 'div' });
      }
      if (editor.selection && !collapsed) {
        prevent = true;
        Transforms.delete(editor, { at: editor.selection });
      }
      if (prevent) event.preventDefault();
    }
  }
}

import { Editor, Element, Transforms } from 'slate';

import { isEmojiElement, isEmojiNode } from './common';
import flattenNodeText from './flattenNodeText';

import type { InteractiveParser } from 'simple-markdown';
import type { BasePoint, CustomElement, Path } from 'slate';

function isOdd(num: number) {
  return num % 2 === 1;
}

// does a quick pass checking for any indicators that the whole structure will need to be reevaluated
// and then does that if so
function handleEditor(editor: Editor, update: boolean): void {
  let inCodeBlock = false;
  let inMultilineBlockQuote = false;
  let currentLang: null | string = null;
  let childLocation = 0;
  for (const child of editor.children) {
    if (Element.isElement(child)) {
      const childText = flattenNodeText(child);

      const codeBlockEndCount = childText.split('```').length - 1;
      const isFullCodeBlock = inCodeBlock && codeBlockEndCount === 0;

      inMultilineBlockQuote = inMultilineBlockQuote || /^ *>>> /.test(childText);
      const isBlockQuote = !isFullCodeBlock && (inMultilineBlockQuote || /^ *> /.test(childText));

      if (!update) {
        if (
          (isFullCodeBlock && child.type !== 'codeBlock')
          || (isFullCodeBlock && child.lang !== currentLang)
          || (!isFullCodeBlock && child.type === 'codeBlock')
          || (child.startCodeBlock !== inCodeBlock)
          || (isBlockQuote && child.type !== 'blockQuote')
          // || (!isBlockQuote && child.type === 'blockQuote')
        ) {
          return handleEditor(editor, true);
        }
      } else {
        let type: Element['type'];
        if (isFullCodeBlock) {
          type = 'codeBlock';
        } else if (isBlockQuote) {
          type = 'blockQuote';
          if (/^ *>>> /.test(childText) || /^ *> /.test(childText)) {
            Transforms.insertText(editor, `${childText.replace(/^ *>(>>)? /, '')}`, { at: [childLocation] });
          }
        } else {
          type = 'div';
        }

        Transforms.setNodes(editor, {
          type,
          lang: (isFullCodeBlock && currentLang) || '',
          startCodeBlock: inCodeBlock,
          children: child.children,
        }, { at: [childLocation] });

        ++childLocation;
      }

      const res = /```([A-Za-z0-9-]+)$/.exec(childText);
      if (res && !inCodeBlock) currentLang = res[1] ?? '';
      else if (res?.[0] && inCodeBlock && currentLang) currentLang = '';

      if (isOdd(codeBlockEndCount)) inCodeBlock = !inCodeBlock;
      if (!inCodeBlock) currentLang = null;
    }
  }

  return undefined;
}

function fixSelection(editor: Editor, elementPath: number, expectedPosition: number) {
  const currentAnchor = editor.selection?.anchor?.path;
  if (currentAnchor?.[0] === elementPath && currentAnchor?.[1] === expectedPosition - 2) {
    const point: BasePoint = { path: [elementPath, expectedPosition], offset: 0 };
    Transforms.setSelection(editor, { anchor: point, focus: point });
  }
}

// https://stackoverflow.com/questions/48678359/ios-11-safari-html-disable-smart-punctuation
const BAD_APOSTROPHE_CODEPOINTS = ['\u2018', '\u2019'] as const;
const BAD_QUOTATION_CODEPOINTS = ['\u201C', '\u201D'] as const;
const BAD_CODEPOINTS = [...BAD_APOSTROPHE_CODEPOINTS, ...BAD_QUOTATION_CODEPOINTS];

function handleElement(editor: Editor, parseEmoji: InteractiveParser, node: CustomElement, path: Path): void {
  const firstChild = node.children[0];

  const nodeText = flattenNodeText(node);
  if (!nodeText && !node.empty) {
    Transforms.setNodes(editor, { ...node, empty: true }, { at: path });
    return;
  }

  if (isEmojiElement(firstChild)) {
    Transforms.insertNodes(editor, [{
      type: 'span',
      text: '',
    }], {
      at: [path[0], 0],
    });
    return;
  }

  const lastChild = node.children.at(-1);
  if (isEmojiElement(lastChild)) {
    Transforms.insertNodes(editor, [{
      type: 'span',
      text: '',
    }], {
      at: [path[0], node.children.length],
    });
    fixSelection(editor, path[0], node.children.length);
    return;
  }

  if (lastChild?.type === 'span' && node.children.length > 1 && !lastChild.text && !isEmojiElement(node.children.at(-2))) {
    Transforms.delete(editor, {
      at: [path[0], node.children.length - 1],
    });
    return;
  }

  for (let i = 0; i < node.children.length; ++i) {
    const prevChild = node.children[i - 1];
    const child = node.children[i];
    if (isEmojiElement(child)) {
      if (isEmojiElement(prevChild)) {
        Transforms.insertNodes(editor, [{
          type: 'span',
          text: '',
        }], {
          at: [path[0], i],
        });
        fixSelection(editor, path[0], i);
        return;
      }
    }

    const childText = flattenNodeText(child, false);
    if (childText.length) {
      let fixedText = childText;
      if (BAD_CODEPOINTS.some((s) => fixedText.includes(s))) {
        const { selection } = editor;
        // eslint-disable-next-line no-loop-func
        while (BAD_CODEPOINTS.some((s) => fixedText.includes(s))) {
          let apostrophe = true;
          let idx = fixedText.indexOf(BAD_APOSTROPHE_CODEPOINTS[0]);
          if (idx === -1) idx = fixedText.indexOf(BAD_APOSTROPHE_CODEPOINTS[1]);
          if (idx === -1) {
            apostrophe = false;
            idx = fixedText.indexOf(BAD_QUOTATION_CODEPOINTS[0]);
          }
          if (idx === -1) idx = fixedText.indexOf(BAD_QUOTATION_CODEPOINTS[1]);
          fixedText = `${fixedText.slice(0, idx)}${' '}${fixedText.slice(idx + 1)}`;

          Transforms.insertText(editor, apostrophe ? "'" : '"', {
            at: {
              anchor: { path: [path[0], i], offset: idx },
              focus: { path: [path[0], i], offset: idx + 1 },
              classNames: [],
            },
          });
        }
        if (selection) Transforms.setSelection(editor, selection);
        return;
      }

      const ast = parseEmoji(childText);
      if (ast.some(isEmojiNode)) {
        let offset = 0;

        for (const cur of ast) {
          if (isEmojiNode(cur)) {
            Transforms.insertNodes(editor, [
              {
                type: 'emoji',
                lang: '',
                startCodeBlock: false,
                ast: cur,
                children: [{ type: 'span', text: '' }],
                empty: false,
              },
            ], {
              at: {
                anchor: { path: [path[0], i], offset },
                focus: { path: [path[0], i], offset: offset + cur.content.length },
                classNames: [],
              },
            });
            return;
          }

          offset += (cur.content as string).length ?? 0;
        }
      }
    }
  }
}

export default (editor: Editor, partialMarkdown: boolean, parseEmoji: InteractiveParser) => {
  const { normalizeNode } = editor;

  editor.normalizeNode = (entry) => {
    const [node, path] = entry;

    if (Editor.isEditor(node)) {
      if (!partialMarkdown) return handleEditor(editor, false);
    } else if (Element.isElement(node) && !isEmojiElement(node)) {
      return handleElement(editor, parseEmoji, node, path);
    }

    return normalizeNode(entry);
  };

  return editor;
};

