import classNames from 'classnames';
import { memo, useRef } from 'react';
import {
  mergeProps, useFocusRing, useId, useTextField,
} from 'react-aria';
import { mergeRefs } from 'react-merge-refs';

import NullableComponent from './NullableComponent';
import Tooltip from './dynamics/Tooltip';

import type { AriaTextFieldProps } from 'react-aria';
import type { Ref } from 'react';

import styles from '~/styles';
import { extractDataProps } from '~/utils';

type Props = AriaTextFieldProps
& {
  inputMode: Required<AriaTextFieldProps>['inputMode'];
  value: string;
  fragment?: true;
  outerClassName?: string;
  labelClassName?: string;
  inputClassName?: string;
  descriptionClassName?: string;
  errorClassName?: string;
  altFocus?: boolean;
  subLabel?: string;
  subLabelClassName?: string;
  tooltip?: string;
  TooltipIcon?: SvgComponent;
};

function TextField({ ref: propRef, ...props }: Props & { ref?: Ref<HTMLInputElement> }) {
  const {
    label, fragment = false, description, errorMessage, outerClassName, labelClassName,
    inputClassName, descriptionClassName, errorClassName, altFocus, subLabel, subLabelClassName,
    tooltip, TooltipIcon,
  } = props;

  if (fragment && outerClassName) throw new Error('Cannot use outerClassName with fragment');

  const dataProps = extractDataProps(props);
  const hasDataProps = Object.keys(dataProps).length > 0;

  if (hasDataProps && fragment) throw new Error('Cannot use data props with fragment');

  const localRef = useRef<HTMLInputElement>(null);
  const ref = mergeRefs([localRef, propRef]);

  const {
    labelProps, inputProps, descriptionProps, errorMessageProps,
    // @ts-expect-error asd
  } = useTextField({ ...props, id: useId(props.id) }, ref);
  const { isFocusVisible, focusProps } = useFocusRing();

  const body = (
    <>
      <NullableComponent show={label}>
        <div className={styles.flex({ cy: true, gap: 1 })}>
          <label
            suppressHydrationWarning
            className={classNames('inline-block', labelClassName)}
            {...mergeProps(labelProps, focusProps)}
          >
            {label}
          </label>
          {subLabel && (
            <span className={classNames('text-sm italic text-mute', subLabelClassName)}>{`(${subLabel})`}</span>
          )}
          {tooltip && TooltipIcon && (
            <Tooltip portal label={tooltip} enterDelay={200}>
              <TooltipIcon className='h-5 w-5' />
            </Tooltip>
          )}
        </div>
      </NullableComponent>
      <input
        ref={ref}
        className={classNames(
          inputClassName,
          isFocusVisible && !altFocus && 'focus-visible',
          isFocusVisible && altFocus && 'focus-visible-alt',
          'no-drag !transition-none focus:placeholder:text-transparent disabled:opacity-50',
        )}
        {...mergeProps(inputProps, !label ? focusProps : {})}
        suppressHydrationWarning
      />
      {description && <div className={classNames('text-xs', descriptionClassName)} {...descriptionProps}>{description}</div>}
      {errorMessage && typeof errorMessage !== 'function' && <div className={classNames('text-xs font-semibold text-error', errorClassName)} {...errorMessageProps}>{errorMessage as React.ReactNode}</div>}
    </>
  );

  if (fragment) return body;

  return <div className={outerClassName} {...dataProps}>{body}</div>;
}

export default memo(TextField);

