import { act, useState } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import BottomPortal, { BottomPortalContainer, BottomPortalProvider } from '../BottomPortal';

import { mountDom, unmountDom } from './helpers/dom';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

const handle = { hide: () => {} };

const Host = () => {
  const [shown, setShown] = useState(true);
  handle.hide = () => setShown(false);
  return (
    <BottomPortalProvider>
      <BottomPortalContainer />
      {shown && (
        <BottomPortal open title="Pick one" level={0} setOpen={() => {}}>
          <p>portal body</p>
        </BottomPortal>
      )}
    </BottomPortalProvider>
  );
};

let appContainer: HTMLElement;
beforeEach(() => {
  appContainer = document.createElement('div');
  appContainer.id = 'app-container';
  document.body.appendChild(appContainer);
});
afterEach(() => {
  unmountDom();
  appContainer.remove();
});

describe('bottom portal, an entry whose owner unmounts', () => {
  it('shows an open entry\'s content while its owner is mounted', () => {
    mountDom(<Host />);

    expect(appContainer.textContent).toContain('portal body');
  });

  it('removes the entry when its owner unmounts while it is open', () => {
    mountDom(<Host />);
    expect(appContainer.textContent).toContain('portal body');

    act(() => { handle.hide(); });

    expect(appContainer.textContent).not.toContain('portal body');
  });
});

