/**
 * `TransitionHeightElement`'s imperative height/visibility management, mounted and driven end to
 * end (not read as source text). React's style prop and imperative `ref.style.*` writes are
 * mutually exclusive for the same CSS properties, so this component manages `display`/`height`
 * entirely through refs — never a `style` prop — and gates every `display: none` behind an
 * `e.target` check on `transitionend` so a bubbled child event can't hide the wrapper early.
 */
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { describe, expect, it, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

import TransitionHeightElement from '../TransitionHeightElement';

function mount(props: Record<string, unknown>) {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = createRoot(container);
  act(() => {
    root.render(
      <TransitionHeightElement {...props}><p>content</p></TransitionHeightElement>,
    );
  });
  return { container, root, wrapper: container.firstElementChild as HTMLElement };
}

describe('TransitionHeightElement — first render, closed', () => {
  it('unmount=true: sets display:none and height:0 imperatively', () => {
    const { wrapper } = mount({ isOpen: false, unmount: true });
    expect(wrapper.style.display).toBe('none');
    expect(wrapper.style.height).toBe('0px');
  });

  it('unmount=false: sets display:block (not none) and height:0, keeps overflow-hidden baseline', () => {
    const { wrapper } = mount({ isOpen: false, unmount: false });
    expect(wrapper.style.display).toBe('block');
    expect(wrapper.style.height).toBe('0px');
    expect(wrapper.className).toContain('overflow-hidden');
  });
});

describe('TransitionHeightElement — className baseline', () => {
  it('unmount=false keeps overflow-hidden in the className regardless of isOpen', () => {
    expect(mount({ isOpen: true, unmount: false }).wrapper.className).toContain('overflow-hidden');
    expect(mount({ isOpen: false, unmount: false }).wrapper.className).toContain('overflow-hidden');
  });
});

describe('TransitionHeightElement — no style prop fights the imperative writes', () => {
  it('an unrelated re-render (same isOpen) does not reset the imperatively-set style', () => {
    const { root, wrapper } = mount({ isOpen: true });
    act(() => {
      root.render(<TransitionHeightElement isOpen={false}><p>content</p></TransitionHeightElement>);
    });
    const heightAfterClose = wrapper.style.height;
    act(() => {
      root.render(
        <TransitionHeightElement isOpen={false} className="extra"><p>content</p></TransitionHeightElement>,
      );
    });
    expect(wrapper.style.height).toBe(heightAfterClose);
  });
});

describe('TransitionHeightElement — open/close transitions add overflow-hidden imperatively', () => {
  it('opening (after first render) adds overflow-hidden and sets display:block', () => {
    const { root, wrapper } = mount({ isOpen: false });
    act(() => {
      root.render(<TransitionHeightElement isOpen><p>content</p></TransitionHeightElement>);
    });
    expect(wrapper.className).toContain('overflow-hidden');
    expect(wrapper.style.display).toBe('block');
  });

  it('closing (after first render) adds overflow-hidden and sets height:0', () => {
    const { root, wrapper } = mount({ isOpen: true });
    act(() => {
      root.render(<TransitionHeightElement isOpen={false}><p>content</p></TransitionHeightElement>);
    });
    expect(wrapper.className).toContain('overflow-hidden');
    expect(wrapper.style.height).toBe('0px');
  });
});

describe('TransitionHeightElement — onTransitionEnd target guard', () => {
  it('matching target while closing: removes overflow-hidden and sets display:none', () => {
    const { root, wrapper } = mount({ isOpen: true, unmount: true });
    act(() => {
      root.render(<TransitionHeightElement isOpen={false} unmount><p>content</p></TransitionHeightElement>);
    });
    act(() => { wrapper.dispatchEvent(new Event('transitionend', { bubbles: true })); });
    expect(wrapper.className).not.toContain('overflow-hidden');
    expect(wrapper.style.display).toBe('none');
  });

  it('matching target while opening (not closing): removes overflow-hidden but leaves display alone', () => {
    const { root, wrapper } = mount({ isOpen: false, unmount: true });
    act(() => {
      root.render(<TransitionHeightElement isOpen unmount><p>content</p></TransitionHeightElement>);
    });
    const displayBefore = wrapper.style.display;
    act(() => { wrapper.dispatchEvent(new Event('transitionend', { bubbles: true })); });
    expect(wrapper.className).not.toContain('overflow-hidden');
    expect(wrapper.style.display).toBe(displayBefore);
  });

  it('a non-matching (bubbled child) target does not touch overflow-hidden or display', () => {
    const { root, container, wrapper } = mount({ isOpen: true, unmount: true });
    act(() => {
      root.render(<TransitionHeightElement isOpen={false} unmount><p>content</p></TransitionHeightElement>);
    });
    const inner = container.querySelector('.h-fit') as HTMLElement;
    const classNameBefore = wrapper.className;
    const displayBefore = wrapper.style.display;
    act(() => { inner.dispatchEvent(new Event('transitionend', { bubbles: true })); });
    expect(wrapper.className).toBe(classNameBefore);
    expect(wrapper.style.display).toBe(displayBefore);
  });
});

