'use client';

import { useQueryClient } from '@tanstack/react-query';
import { getQueryKey } from '@trpc/react-query';
import { useSession } from 'next-auth/react';
import {
  createContext, memo, use, useCallback, useEffect, useMemo, useRef, useState,
} from 'react';
import { useUpdateEffect } from 'react-use';

import type { PropsWithChildren } from 'react';

import { api } from '~/utils/api';
import { useMounted, useParsePathname, useToggleState } from '~/utils/hooks';
import useUpdatePreferences from '~/utils/hooks/useUpdatePreferences';

interface State {
  guildId: null | string;
  guild: null | undefined | Guild;
  channels: DiscordChannel[];
  webhooks: Webhook[];
  setGuildId: StateSetter<string>;
  clearError: VoidFunction;
  hasLoaded: boolean;

  isLoading: boolean;
  isLoadingChannels: boolean;
  isFetching: boolean;
  isFetchingChannels: boolean;
  refetchAll: VoidFunction;
}

const Context = createContext<State | null>(null);
export const useGuild = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('Guild components must be wrapped in <Guild />');
  }

  return context;
};

function attachChannelsToWebhooks(
  { channels, webhooks }:
  { channels: DiscordChannel[], webhooks: Webhook[] },
) {
  if (webhooks) {
    webhooks.forEach((wh) => {
      wh.channel = channels?.find((c) => c.id === wh.channel_id);
    });
    webhooks.sort((a, b) => {
      if (!a.channel) return 1;
      if (!b.channel) return -1;
      return a.channel.name.localeCompare(b.channel.name);
    });
  }
}

function useValue() {
  const { data: session } = useSession();

  const { guildId: paramGuildId } = useParsePathname();
  const [guildId, setGuildId] = useState(paramGuildId);
  const [hasLoaded, {
    setTrue: setHasLoaded,
    setFalse: unsetHasLoaded,
  }] = useToggleState(!guildId);
  const mounted = useMounted();

  const guildIdRef = useRef(guildId);
  useEffect(() => {
    guildIdRef.current = guildId;
  }, [guildId]);

  useUpdateEffect(() => {
    if (paramGuildId) {
      if (paramGuildId !== guildIdRef.current) {
        unsetHasLoaded();
      }
      setGuildId(paramGuildId);
    }
  }, [paramGuildId]);

  const {
    isLoading, isFetching, data: guild, status: guildStatus,
  } = api.guild.getGuild.useQuery(guildId ?? '', {
    enabled: !!(guildId && session),
    // initialData: () => session?.hydration.guild,
    retry: 1,
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  // Replaces onSettled callback removed in RQ5
  useEffect(() => {
    if (guildStatus !== 'pending') setHasLoaded();
  }, [guildStatus]);

  const {
    isLoading: isLoadingChannels, isFetching: isFetchingChannels, data: channelsAndHooks,
  } = api.guild.getWebhooksAndChannels.useQuery(guildId ?? '', {
    enabled: !!(guild && session),
    retry: 1,
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  // Replaces onSuccess callback removed in RQ5
  useEffect(() => {
    if (channelsAndHooks) attachChannelsToWebhooks(channelsAndHooks);
  }, [channelsAndHooks]);

  const { channels, webhooks } = useMemo(
    () => channelsAndHooks ?? { channels: [], webhooks: [] },
    [channelsAndHooks],
  );

  useUpdatePreferences({
    recentGuild: guildId ?? session?.user?.preferences?.recentGuild,
  });

  const client = useQueryClient();

  const state: State = {
    guildId,
    guild,
    channels,
    webhooks,
    setGuildId,
    clearError: useCallback(() => {
      void client.removeQueries({ queryKey: getQueryKey(api.guild.getGuild) });
    }, [client]),

    isLoading: !!(mounted && isLoading && guildId && guildId !== '0'),
    isFetching,
    isLoadingChannels: !!(mounted && isLoadingChannels && guild),
    isFetchingChannels,
    hasLoaded,
    // error,
    // showAuthErrorModal,
    // hideAuthErrorModal,
    refetchAll: useCallback(() => {
      void client.invalidateQueries({
        predicate(query) {
          if (query.state.fetchStatus === 'fetching') return false;
          const [path1, path2] = query.queryKey[0] as string[];
          return (
            path1 === 'guild'
            && path2 === 'getGuild'
          ) || (
            path1 === 'guild'
            && path2 === 'getWebhooksAndChannels'
          );
        },
      });
    }, []),
  };

  return useMemo(() => state, Object.values(state));
}

const Provider = memo(
  ({ children }: PropsWithChildren) => (
    <Context.Provider value={useValue()}>
      {children}
    </Context.Provider>
  ),
);
Provider.displayName = 'GuildProvider';
export default Provider;

import {
  createContext, memo, use, useEffect, useMemo, useState,
} from 'react';

import type { PropsWithChildren } from 'react';
import type { MarkdownParsers } from 'simple-markdown';

type State = MarkdownParsers | undefined;

export const Context = createContext<State | null>(null);
export const useMarkdown = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('Markdown components must be wrapped in <Markdown />');
  }

  return context;
};

function useValue(prop?: State) {
  const [markdown, setMarkdown] = useState<State>(prop);
  useEffect(() => {
    if (!markdown) {
      import('~/utils/markdown').then((m) => setMarkdown(m.default)).catch(console.error);
    }
  }, []);
  return useMemo(() => markdown, [markdown]);
}

const Provider = memo(
  ({ children, passthrough }: PropsWithChildren<{ passthrough?: State }>) => <Context.Provider value={useValue(passthrough)}>{children}</Context.Provider>,
);
Provider.displayName = 'MarkdownProvider';
export default Provider;

