import { act } from 'react';
import {
  describe, expect, it, vi, afterEach,
} from 'vitest';

import { normalizeForHash } from '../usePusher';

import { mountInMessageProvider } from './helpers/mountMessageProvider';

import type { ContentLossOption } from '~/utils';

import { unmountDom } from '~/components/__tests__/helpers/dom';
import { useMessage } from '~/providers/MessageProvider';
import { hashMessage, validateContentRequirements } from '~/utils';

const V2_WITH_EMPTY_EMBED = {
  flags: 32768,
  content: '',
  embeds: [{}],
  components: [{ type: 17, components: [{ type: 10, content: 'x' }] }],
};

const V2_WITH_CONTENT = {
  flags: 32768,
  content: 'hi',
  embeds: [],
  components: [{ type: 17, components: [{ type: 10, content: 'x' }] }],
};

const hoisted = vi.hoisted(() => ({
  inputs: [] as unknown[],
  stored: {
    id: '42', name: 'Stored', updatedAt: 1, data: {} as Record<string, unknown>,
  },
}));

vi.mock('~/env.mjs', async () => (await import('./helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', async () => (await import('./helpers/messageProviderDeps')).navigationMock('/message/m/42/edit'));
vi.mock('next-auth/react', async () => (await import('./helpers/messageProviderDeps')).AUTH_MOCK);
vi.mock('~/providers/GuildProvider', async () => (await import('./helpers/messageProviderDeps')).GUILD_PROVIDER_MOCK);
vi.mock('~/providers/WebhookProvider', async () => (await import('./helpers/messageProviderDeps')).WEBHOOK_PROVIDER_MOCK);
vi.mock('~/providers/ConfirmationProvider', async () => (await import('./helpers/messageProviderDeps')).CONFIRMATION_PROVIDER_MOCK);
vi.mock('~/utils/api', async () => {
  const { buildApiMock } = await import('./helpers/messageProviderDeps');
  return buildApiMock({
    queryData: { 'message.getOne': () => hoisted.stored },
    onMutation: { 'message.upsert': (_opts, input) => { hoisted.inputs.push(input); } },
  });
});

afterEach(() => {
  unmountDom();
  hoisted.inputs.length = 0;
  window.localStorage.clear();
});

let ctx: ReturnType<typeof useMessage> | null = null;
const Probe: FC = () => {
  ctx = useMessage();
  return null;
};

function current() {
  expect(ctx).toBeTruthy();
  return ctx as ReturnType<typeof useMessage>;
}

function mountStored(data: Record<string, unknown>) {
  hoisted.stored.data = data;
  act(() => { mountInMessageProvider(<Probe />); });
}

function writtenAndHeld() {
  expect(hoisted.inputs).toHaveLength(1);
  const written = (hoisted.inputs[0] as { message: ActiveMessage }).message;
  const held = current().message as ActiveMessage;
  expect(hashMessage(normalizeForHash(held))).toBe(hashMessage(normalizeForHash(written)));
  return { written, held };
}

describe('MessageProvider — Save of a stored V2 message beside an empty embed', () => {
  it('writes it as V2 without the embed, and the editor holds exactly what was written', () => {
    mountStored(V2_WITH_EMPTY_EMBED);
    expect(current().message?.data.embeds).toHaveLength(1);

    act(() => { current().saveMessage(); });

    expect(current().pendingSaveChoice).toBe(null);
    expect(hoisted.inputs).toHaveLength(1);
    const written = (hoisted.inputs[0] as { message: ActiveMessage }).message;
    expect(written.data.embeds).toEqual([]);
    expect(written.data.flags).toBe(32768);
    expect(written.data.components).toEqual([{ type: 17, components: [{ type: 10, content: 'x' }] }]);

    const held = current().message as ActiveMessage;
    expect(held.data.embeds).toEqual([]);
    expect(hashMessage(normalizeForHash(held))).toBe(hashMessage(normalizeForHash(written)));
    expect(validateContentRequirements(held.data)).toBeUndefined();
  });
});

describe('MessageProvider — the choice save of a stored V2 message with content', () => {
  function chooseAndSave(mode: MessageMode) {
    mountStored(V2_WITH_CONTENT);
    expect(current().editableState.messageMode).toBe('v2');
    act(() => { current().saveMessage(); });
    expect(hoisted.inputs).toHaveLength(0);
    const option = current().pendingSaveChoice?.options.find((o) => o.mode === mode);
    expect(option).toBeDefined();
    act(() => { current().commitSaveChoice(option as ContentLossOption); });
    expect(current().pendingSaveChoice).toBe(null);
    return writtenAndHeld();
  }

  it('Save as Classic: the editor holds the classic message that was written, in Classic mode', () => {
    const { written, held } = chooseAndSave('classic');
    expect(written.data.components).toEqual([]);
    expect(written.data.content).toBe('hi');
    expect(held.data.components).toEqual([]);
    expect(held.data.content).toBe('hi');
    expect(current().editableState.messageMode).toBe('classic');
  });

  it('Save as Components V2: the editor holds the V2 message that was written, in V2 mode', () => {
    const { written, held } = chooseAndSave('v2');
    expect(written.data.content).toBe('');
    expect(held.data.content).toBe('');
    expect(held.data.components).toHaveLength(1);
    expect(current().editableState.messageMode).toBe('v2');
  });
});

