import { act } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import { mountInMessageProvider } from './helpers/mountMessageProvider';

import type { FC } from 'react';

import { unmountDom } from '~/components/__tests__/helpers/dom';
import { useMessage } from '~/providers/MessageProvider';
import { INTRO_MESSAGE } from '~/utils/copyIntroMessage';

const hoisted = vi.hoisted(() => ({
  pathname: '/message/m/0/edit',
  status: 'unauthenticated' as 'authenticated' | 'unauthenticated' | 'loading',
  search: '',
  fromCode: undefined as unknown,
  mutOpts: [] as Record<string, unknown>[],
  inputs: [] as unknown[],
  stored: {
    id: '42', name: 'Stored', updatedAt: 1000, data: { content: 'saved copy' } as Record<string, unknown>,
  },
}));

vi.mock('pusher-js', () => ({
  default: function Pusher() {
    return {
      subscribe: () => ({ bind: () => undefined, unbind: () => undefined }),
      unsubscribe: () => undefined,
      disconnect: () => undefined,
    };
  },
}));
vi.mock('~/env.mjs', async () => (await import('./helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', () => ({
  useRouter: () => ({
    push: () => undefined, replace: () => undefined, refresh: () => undefined, back: () => undefined,
  }),
  usePathname: () => hoisted.pathname,
  useSearchParams: () => new URLSearchParams(hoisted.search),
}));
vi.mock('next-auth/react', () => ({
  useSession: () => ({ status: hoisted.status, data: hoisted.status === 'authenticated' ? {} : null }),
  signIn: () => undefined,
}));
vi.mock('~/providers/GuildProvider', async () => (await import('./helpers/messageProviderDeps')).GUILD_PROVIDER_MOCK);
vi.mock('~/providers/WebhookProvider', async () => (await import('./helpers/messageProviderDeps')).WEBHOOK_PROVIDER_MOCK);
vi.mock('~/providers/ConfirmationProvider', () => ({
  useConfirmation: () => ({ showConfirmation: () => undefined, withConfirmation: (fn: unknown) => fn }),
}));
vi.mock('~/utils/api', async () => {
  const { buildApiMock } = await import('./helpers/messageProviderDeps');
  return buildApiMock({
    queryData: {
      'message.getOne': () => (hoisted.pathname.includes('/m/0/') ? undefined : hoisted.stored),
      'message.getFromCode': () => hoisted.fromCode,
    },
    onMutation: {
      'message.upsert': (opts, input) => { hoisted.mutOpts.push(opts); hoisted.inputs.push(input); },
    },
  });
});

let ctx: ReturnType<typeof useMessage> | null = null;
const Probe: FC = () => {
  ctx = useMessage();
  return null;
};
const cur = () => ctx as ReturnType<typeof useMessage>;
const content = () => (cur().message?.data as { content?: string }).content;

const TAB_KEY = 'messageDraftTab';
const openTab = (id: string) => { window.sessionStorage.setItem(TAB_KEY, id); };
const mount = () => { act(() => { mountInMessageProvider(<Probe />); }); };
const visit = (pathname: string, status = hoisted.status) => {
  hoisted.pathname = pathname;
  hoisted.status = status;
  act(() => { cur().toggleHelp(); });
};
const DRAFT_NAME = 'Name the user gave the draft';
const DRAFT_EMBED = { title: 'An embed title', description: 'An embed body' };
const draftData = (text: string) => ({ content: text, embeds: [DRAFT_EMBED] });
const restoredData = (text: string) => ({
  content: text, embeds: [{ ...DRAFT_EMBED, _key: expect.any(String) as unknown }],
});
const shown = () => ({ data: cur().message?.data, name: cur().message?.name });
const typeFullDraft = (text: string) => {
  act(() => { cur().updateMessage({ data: draftData(text) as never }); });
};
const typeDraft = (text: string) => {
  act(() => { cur().updateMessage({ data: { ...cur().message?.data, content: text } as never }); });
};

beforeEach(() => {
  hoisted.pathname = '/message/m/0/edit';
  hoisted.status = 'unauthenticated';
  hoisted.search = '';
  hoisted.fromCode = undefined;
  hoisted.stored = {
    id: '42', name: 'Stored', updatedAt: 1000, data: { content: 'saved copy' },
  };
  openTab('A');
});

afterEach(() => {
  unmountDom();
  hoisted.mutOpts.length = 0;
  hoisted.inputs.length = 0;
  window.localStorage.clear();
  window.sessionStorage.clear();
});

describe('MessageProvider, a signed-out draft at route 0', () => {
  it('is restored after sign-in, opening a saved message, and returning to route 0', () => {
    mount();
    typeFullDraft('my draft');

    visit('/message/m/42/edit', 'authenticated');
    visit('/message/m/0/edit');

    expect(shown()).toEqual({ data: restoredData('my draft'), name: 'New Message' });
  });

  it('is restored after sign-in and a reload', () => {
    mount();
    typeFullDraft('my draft');
    unmountDom();

    hoisted.status = 'authenticated';
    mount();

    expect(shown()).toEqual({ data: restoredData('my draft'), name: 'New Message' });
  });

  it('is restored in a tab opened later, when it was the last edited', () => {
    mount();
    typeFullDraft('my draft');
    unmountDom();

    openTab('B');
    mount();

    expect(shown()).toEqual({ data: restoredData('my draft'), name: 'New Message' });
  });
});

describe('MessageProvider, unsaved edits on a saved message when the session is lost', () => {
  const edited = () => {
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';
    mount();
    typeFullDraft('unsaved edits on 42');
  };
  const unsavedEdits = { data: restoredData('unsaved edits on 42'), name: 'Stored' };

  it('are shown again after signing in and opening the message', () => {
    edited();

    visit('/message/m/0/edit', 'unauthenticated');
    visit('/message/m/42/edit', 'authenticated');

    expect(shown()).toEqual(unsavedEdits);
  });

  it('are not shown at route 0 meanwhile, which shows its own draft', () => {
    edited();

    visit('/message/m/0/edit', 'unauthenticated');

    expect(content()).toBe(INTRO_MESSAGE.data.content);
  });

  it('are shown after a reload, as before', () => {
    edited();
    unmountDom();

    mount();

    expect(shown()).toEqual(unsavedEdits);
  });

  it('leave no stored draft once they are typed back to the saved copy', () => {
    edited();
    expect(Object.keys(JSON.parse(window.localStorage.getItem('messageDrafts') as string) as object)).toEqual(['42']);

    act(() => { cur().updateMessage({ data: { content: 'saved copy' } as never }); });

    expect(window.localStorage.getItem('messageDrafts')).toBe('{}');
  });

  it('survive opening another saved message', () => {
    edited();

    visit('/message/m/43/edit');
    visit('/message/m/42/edit');

    expect(shown()).toEqual(unsavedEdits);
  });
});

describe('MessageProvider, two tabs at route 0', () => {
  const draftIn = (tab: string, text: string) => {
    openTab(tab);
    mount();
    typeFullDraft(text);
    unmountDom();
  };

  it('shows each tab its own last draft after a reload', () => {
    draftIn('A', 'from A');
    draftIn('B', 'from B');

    openTab('A');
    mount();
    expect(shown()).toEqual({ data: restoredData('from A'), name: 'New Message' });
    unmountDom();

    openTab('B');
    mount();
    expect(shown()).toEqual({ data: restoredData('from B'), name: 'New Message' });
  });

  it('shows a new tab the draft edited most recently', () => {
    draftIn('A', 'from A');
    draftIn('B', 'from B');

    openTab('C');
    mount();

    expect(shown()).toEqual({ data: restoredData('from B'), name: 'New Message' });
  });

  it('shows a new tab a draft whose tab has closed', () => {
    draftIn('A', 'from A');

    openTab('C');
    mount();

    expect(shown()).toEqual({ data: restoredData('from A'), name: 'New Message' });
  });

  it('shows the intro message, and writes nothing, in a new tab with no draft anywhere', () => {
    mount();

    expect(content()).toBe(INTRO_MESSAGE.data.content);
    expect(window.localStorage.getItem('messageDrafts')).toBeNull();
  });
});

describe('MessageProvider, a share code opened at route 0', () => {
  const SHARED = { messageId: '1135299649184485458', guildId: '1', data: { content: 'shared by code' } };

  it('becomes this tab\'s route-0 draft, shown when route 0 is opened again without the code', () => {
    hoisted.search = 'code=abc';
    hoisted.fromCode = SHARED;
    mount();
    expect(content()).toBe('shared by code');
    unmountDom();

    hoisted.search = '';
    hoisted.fromCode = undefined;
    mount();

    expect(shown()).toEqual({ data: { content: 'shared by code' }, name: 'New Message' });
  });
});

describe('MessageProvider, the store a browser holds from before', () => {
  it('restores a stored route-0 draft that has no id', () => {
    window.localStorage.setItem('message', JSON.stringify({ name: DRAFT_NAME, updatedAt: 5, data: draftData('kept from before') }));

    mount();

    expect(shown()).toEqual({ data: restoredData('kept from before'), name: DRAFT_NAME });
  });

  it('restores a stored copy of message 42 that is newer than its saved copy', () => {
    window.localStorage.setItem('message', JSON.stringify({
      id: '42', name: 'Name kept with the local copy', updatedAt: 9999, data: draftData('newer local copy'),
    }));
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';

    mount();

    expect(shown()).toEqual({ data: restoredData('newer local copy'), name: 'Name kept with the local copy' });
  });

  it('shows the saved copy when the stored copy is exactly as new', () => {
    window.localStorage.setItem('message', '{"id":"42","name":"Stored","updatedAt":1000,"data":{"content":"same-age local copy"}}');
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';

    mount();

    expect(content()).toBe('saved copy');
  });

  it('shows the saved copy when the stored copy is older', () => {
    window.localStorage.setItem('message', '{"id":"42","name":"Stored","updatedAt":5,"data":{"content":"older local copy"}}');
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';

    mount();

    expect(content()).toBe('saved copy');
  });
});

describe('MessageProvider, a stored route-0 draft', () => {
  it('is shown with its own data and name', () => {
    window.localStorage.setItem('messageDrafts', JSON.stringify({
      '0:A': { data: draftData('seeded draft'), name: DRAFT_NAME, editedAt: 5 },
    }));

    mount();

    expect(shown()).toEqual({ data: restoredData('seeded draft'), name: DRAFT_NAME });
  });
});

describe('MessageProvider, a stored draft of a saved message', () => {
  it('is shown with its own data and name when it is newer than the saved copy', () => {
    window.localStorage.setItem('messageDrafts', JSON.stringify({
      42: { data: draftData('stored with the draft'), name: 'Name stored with the draft', editedAt: 9999 },
    }));
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';

    mount();

    expect(shown()).toEqual({ data: restoredData('stored with the draft'), name: 'Name stored with the draft' });
  });
});

describe('MessageProvider, the legacy message key', () => {
  it('holds the route-0 draft last written, for the code that reads it', () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(1_700_000_000_000);
    mount();
    typeFullDraft('revert-safe');
    vi.useRealTimers();

    const legacy = JSON.parse(window.localStorage.getItem('message') as string) as Record<string, unknown>;

    expect(Object.keys(legacy).sort()).toEqual(['data', 'name', 'updatedAt']);
    expect(legacy).toEqual({ name: 'New Message', updatedAt: 1_700_000_000_000, data: restoredData('revert-safe') });
  });
});

describe('MessageProvider, the draft after a save', () => {
  const respond = (index: number, id: string) => {
    act(() => {
      (hoisted.mutOpts[index].onSuccess as (m: unknown, v: unknown) => void)(
        { ...(hoisted.inputs[index] as { message: object }).message, id },
        hoisted.inputs[index],
      );
    });
  };
  const draftKeys = () => Object.keys(JSON.parse(window.localStorage.getItem('messageDrafts') ?? '{}') as object);

  it('is removed from route 0 when a creating save succeeds', () => {
    hoisted.status = 'authenticated';
    mount();
    typeDraft('to be saved');
    act(() => { cur().saveMessage(); });

    respond(0, '55');

    expect(draftKeys()).toEqual([]);
    expect(window.localStorage.getItem('message')).toBeNull();
  });

  it('of a saved message is removed when this tab saves what the draft holds', () => {
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';
    mount();
    typeDraft('to be saved');
    act(() => { cur().saveMessage(); });

    respond(0, '42');

    expect(draftKeys()).toEqual([]);
  });

  it('of a saved message stays when an edit was typed after Save', () => {
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';
    mount();
    typeDraft('to be saved');
    act(() => { cur().saveMessage(); });
    typeDraft('typed after Save');

    respond(0, '42');

    expect(draftKeys()).toEqual(['42']);
  });
});

describe('MessageProvider, reloading a saved message', () => {
  it('discards the stored edits and shows the saved copy', async () => {
    window.localStorage.setItem('messageDrafts', '{"42":{"data":{"content":"stale edits"},"name":"Stored","editedAt":9999}}');
    hoisted.status = 'authenticated';
    hoisted.pathname = '/message/m/42/edit';
    mount();
    expect(content()).toBe('stale edits');

    hoisted.stored = { ...hoisted.stored };
    await act(async () => { cur().reloadMessage(); });
    act(() => { cur().toggleHelp(); });

    expect(content()).toBe('saved copy');
    expect(window.localStorage.getItem('messageDrafts')).toBe('{}');
  });
});

describe('MessageProvider, hasChanged for every session status', () => {
  it.each(['authenticated', 'unauthenticated', 'loading'] as const)('is false for an unedited message when %s', (status) => {
    hoisted.status = status;
    mount();

    expect(cur().hasChanged).toBe(false);
  });

  it.each(['authenticated', 'unauthenticated', 'loading'] as const)('is true for an edited message when %s', (status) => {
    hoisted.status = status;
    mount();
    typeDraft('edited');

    expect(cur().hasChanged).toBe(true);
  });
});

