'use client';

import { useQueryClient } from '@tanstack/react-query';
import { useSession } from 'next-auth/react';
import {
  createContext, memo, use, useCallback, useEffect, useMemo,
} from 'react';
import { toast } from 'react-toastify';

import type { PropsWithChildren } from 'react';

import { api } from '~/utils/api';
import { useParsePathname } from '~/utils/hooks';

interface State {
  messages: PartialApiMessage[];
  isLoading: boolean;
  refetch: VoidFunction;
}

const Context = createContext<State | null>(null);
export const useMessages = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('Messages components must be wrapped in <Messages />');
  }

  return context;
};
function useValue() {
  const { data: session } = useSession();
  const { folderId } = useParsePathname();

  const { isLoading, data: messages, error: messagesError } = api.message.get.useQuery(folderId ?? '', {
    enabled: !!(folderId && session),
    retry: false,
    staleTime: Infinity,
    refetchOnWindowFocus: false,
  });

  // Replaces onError callback removed in RQ5
  useEffect(() => {
    if (messagesError) toast.error(messagesError.message);
  }, [messagesError]);

  const client = useQueryClient();
  const state: State = {
    messages: messages ?? [],
    isLoading,
    refetch: useCallback(() => {
      void client.invalidateQueries({
        predicate(query) {
          const [path1, path2] = query.queryKey[0] as string[];
          return path1 === 'message' && path2 === 'get' && query.state.fetchStatus !== 'fetching';
        },
      });
    }, []),
  };

  return useMemo(() => state, Object.values(state));
}

const Provider = memo(
  ({ children }: PropsWithChildren) => (
    <Context.Provider value={useValue()}>
      {children}
    </Context.Provider>
  ),
);
Provider.displayName = 'MessagesProvider';
export default Provider;

'use client';

import { useRouter } from 'next/navigation';
import {
  createContext, memo, use, useMemo, useRef,
} from 'react';
import { useLatest } from 'react-use';

import type { PropsWithChildren } from 'react';

import ConfirmationDialog from '~/components/ConfirmationDialog';
import ConfirmationProvider, { useConfirmation } from '~/providers/ConfirmationProvider';
import { leaveWithoutAlert } from '~/utils/leaveWithoutAlert';

export type NavigationGuard = (destination: string) => boolean;

export interface GuardedLink {
  href: string;
  external?: boolean;
  replace?: boolean;
  scroll?: boolean;
}

interface State {
  register: (guard: NavigationGuard) => VoidFunction;
  intercept: (link: GuardedLink) => boolean;
}

const NO_GUARD: State = { register: () => () => {}, intercept: () => false };

const Context = createContext<State>(NO_GUARD);
export const useNavigationGuard = () => use(Context);

const Guard = ({ children }: PropsWithChildren) => {
  const { showConfirmation } = useConfirmation();
  const routerRef = useLatest(useRouter());
  const guardRef = useRef<NavigationGuard | null>(null);

  const value = useMemo<State>(() => ({
    register(guard) {
      guardRef.current = guard;
      return () => {
        if (guardRef.current === guard) guardRef.current = null;
      };
    },
    intercept({
      href, external, replace, scroll,
    }) {
      if (!guardRef.current?.(href)) return false;

      showConfirmation({
        enabled: true,
        title: 'You have unsaved changes!',
        message: 'Are you sure you want to leave this page? Changes you made may not be saved.',
        confirmText: 'Leave Page',
        onConfirm: () => {
          if (external) void leaveWithoutAlert(async () => window.location[replace ? 'replace' : 'assign'](href));
          else routerRef.current[replace ? 'replace' : 'push'](href, { scroll });
        },
      });
      return true;
    },
  }), [showConfirmation]);

  return (
    <Context.Provider value={value}>
      {children}
      <ConfirmationDialog />
    </Context.Provider>
  );
};

const Provider = memo(({ children }: PropsWithChildren) => (
  <ConfirmationProvider>
    <Guard>{children}</Guard>
  </ConfirmationProvider>
));
Provider.displayName = 'NavigationGuardProvider';
export default Provider;

