'use client';

import {
  createContext, memo, use, useCallback, useMemo, useRef,
} from 'react';
import { useLatest } from 'react-use';

import type { PropsWithChildren } from 'react';

import { api } from '~/utils/api';

type InitProps = {
  messages: PartialApiMessage[];
};

type State = {
  messages: PartialApiMessage[];
  isLoading: boolean;
  refetchIfStale: VoidFunction;
};

export const Context = createContext<State | null>(null);
export const usePartialMessages = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('PartialMessages components must be wrapped in <PartialMessages />');
  }

  return context;
};

function useValue({ messages: init }: InitProps) {
  const hasFetchedRef = useRef(false);
  const {
    data: messages, refetch, isFetching, isStale,
  } = api.message.getAll.useQuery(undefined, {
    notifyOnChangeProps: ['isFetching', 'data', 'isStale'],
    enabled: hasFetchedRef.current,
    refetchOnWindowFocus: false,
    retry: false,
    staleTime: 60_000,
    initialData: init,
  });

  const isStaleRef = useLatest(isStale);

  const state: State = {
    messages,
    isLoading: isFetching,
    refetchIfStale: useCallback(() => {
      if (!hasFetchedRef.current || isStaleRef.current) {
        hasFetchedRef.current = true;
        void refetch();
      }
    }, []),
  };

  return useMemo(() => state, Object.values(state));
}

const Provider = memo(
  ({ children, ...props }: PropsWithChildren<InitProps>) => <Context.Provider value={useValue(props)}>{children}</Context.Provider>,
);
Provider.displayName = 'MessagesProvider';
export default Provider;

