'use client';

import {
  createContext, memo, use, useCallback, useEffect, useMemo, useState,
} from 'react';
import { useUpdateEffect } from 'react-use';

import type { APIMessage as Message } from 'discord-api-types/v10';
import type { PropsWithChildren } from 'react';

import { MESSAGE_LOAD_FAILED_ERROR } from '~/constants';
import { useGuild } from '~/providers/GuildProvider';
import { isValidUrl, makeEditable, voided } from '~/utils';
import constructWebhookUrl from '~/utils/constructWebhookUrl';
import { useLoading } from '~/utils/hooks';
import parseMessageId from '~/utils/parseMessageId';

export type OldMessage = Omit<Message, keyof EditableMessageData> & EditableMessageData;
export interface State {
  url: string;
  threadId: string;
  threadName: string;
  isWebhookLoading: boolean;

  selectedWebhook: Webhook | null;
  messageIdOrUrl: string;
  oldMessage: OldMessage | null;
  oldMessageError: string | null;
  isOldMessageLoading: boolean;

  setUrl: StateSetter<string>;
  setThreadId: StateSetter<string>;
  setThreadName: StateSetter<string>;

  setSelectedWebhook: (wh: Webhook | null) => void;
  setMessageIdOrUrl: StateSetter<string>;
  resetWebhook: VoidFunction;
  clearOldMessage: VoidFunction;
}

export const Context = createContext<State | null>(null);
export const useWebhook = () => {
  const context = use(Context);

  if (context === null) {
    throw new Error('Webhook components must be wrapped in <Webhook />');
  }

  return context;
};

function useValue() {
  const { channels } = useGuild();

  const [url, setUrl] = useState('');
  const [threadId, setThreadId] = useState('');
  const [messageIdOrUrl, setMessageIdOrUrl] = useState('');
  const [threadName, setThreadName] = useState('');

  const [selectedWebhook, setSelectedWebhook] = useState<Webhook | null>(null);
  const [isWebhookLoading, withLoadingWebhook] = useLoading();
  useUpdateEffect(() => {
    let isStale = false;
    setSelectedWebhook(null);
    if (isValidUrl(url)) {
      voided(async () => {
        const wh = await withLoadingWebhook(
          fetch(url).then<Webhook | null>((res) => (res.status === 200 ? res.json() : null)),
        ).catch(() => null);
        if (isStale) return;
        if (wh) {
          wh.channel = channels?.find((c) => c.id === wh.channel_id);
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          wh.token = url.split('/').find((part) => part.length > 32)!;
        }
        setSelectedWebhook(wh);
      })();
    }
    return () => { isStale = true; };
  }, [url]);

  const [oldMessage, setOldMessage] = useState<OldMessage | null>(null);
  const [oldMessageError, setOldMessageError] = useState<string | null>(null);

  const clearOldMessage = useCallback(() => {
    setMessageIdOrUrl('');
    setOldMessage(null);
    setOldMessageError('');
  }, []);

  const resetWebhook = useCallback(() => {
    setUrl('');
    setThreadId('');
    setThreadName('');
    setSelectedWebhook(null);
    clearOldMessage();
  }, []);

  useUpdateEffect(clearOldMessage, [selectedWebhook]);

  const [isOldMessageLoading, withLoadingMessage] = useLoading();
  useEffect(() => {
    let isStale = false;
    const messageId = parseMessageId(messageIdOrUrl);
    if (selectedWebhook?.token && messageId) {
      voided(async () => {
        await withLoadingMessage(fetch(`${constructWebhookUrl(selectedWebhook, messageId, threadId)}`).then(async (res) => {
          const data = await res.json();
          if (isStale) return;
          if (res.ok) {
            setOldMessage(makeEditable({
              data: { ...data, username: data.author.username },
            } as { data: MessageData }).data as OldMessage);
            setOldMessageError('');
          } else {
            setOldMessage(null);
            if (res.status === 404) {
              setOldMessageError('Message not found. Hint: Webhooks can only edit their own messages.');
            } else if (res.status === 403) {
              setOldMessageError('You do not have permission to view this message.');
            } else if (res.status === 401) {
              setOldMessageError('Invalid webhook token.');
            } else if (res.status === 400) {
              setOldMessageError('Invalid webhook id.');
            } else {
              setOldMessageError((data as { message: string }).message ?? res.statusText);
            }
          }
        })).catch(() => {
          if (isStale) return;
          setOldMessage(null);
          setOldMessageError(MESSAGE_LOAD_FAILED_ERROR);
        });
      })();
    } else {
      setOldMessage(null);
      setOldMessageError('');
    }
    return () => { isStale = true; };
  }, [selectedWebhook, messageIdOrUrl, threadId]);

  const state: State = {
    url,
    threadId,
    threadName,
    isWebhookLoading,

    selectedWebhook,
    messageIdOrUrl,
    oldMessage,
    oldMessageError,
    isOldMessageLoading,

    setUrl,
    setThreadId,
    setThreadName,

    setSelectedWebhook,
    setMessageIdOrUrl,
    resetWebhook,
    clearOldMessage,
    // setSelectedWebhook: wrappedSetValidatedWebhook,
  };

  return useMemo(() => state, Object.values(state));
}

const Provider = memo(
  ({ children }: PropsWithChildren) => <Context.Provider value={useValue()}>{children}</Context.Provider>,
);
Provider.displayName = 'WebhookProvider';
export default Provider;

