// ============================================================
// Tests: discordMessageImportShape (lenient)
// ============================================================

describe('discordMessageImportShape (lenient import)', () => {
  it('accepts a valid message identically to strict shape', () => {
    const msg = {
      content: 'Hello',
      components: [makeTextDisplay(), makeSeparator()],
    };
