import { describe, it, expect, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import {
  discordMessageImportShape,
  topLevelComponentShape,
  containerChildShape,
  SUPPORTED_TOP_LEVEL_TYPES,
  SUPPORTED_CONTAINER_CHILD_TYPES,
  describeUnsupportedComponentTypes,
} from '~/server/api/utils/shapes';
import {
  makeLinkButton, makeThumbnail, makeTextDisplay, makeSection, makeContainer,
} from '~/utils/__tests__/helpers/components';

describe('SUPPORTED_TOP_LEVEL_TYPES equals the discriminant set topLevelComponentShape accepts', () => {
  it('the top-level filter set and the schema discriminant set are the same set, asserted over the sets themselves', () => {
    const schemaDiscriminants = new Set(
      (topLevelComponentShape.options as { shape: { type: { value: number } } }[])
        .map((option) => option.shape.type.value),
    );
    expect(SUPPORTED_TOP_LEVEL_TYPES).toEqual(schemaDiscriminants);
  });

  it('the container-child filter set and the schema discriminant set are the same set', () => {
    const schemaDiscriminants = new Set(
      (containerChildShape.options as { shape: { type: { value: number } } }[])
        .map((option) => option.shape.type.value),
    );
    expect(SUPPORTED_CONTAINER_CHILD_TYPES).toEqual(schemaDiscriminants);
  });

  it('a top-level Thumbnail is filtered out, not passed through to a failing schema parse', () => {
    const result = discordMessageImportShape.safeParse({ components: [makeThumbnail()] });
    expect(result.success).toBe(true);
    if (result.success) expect(result.data.components).toEqual([]);
  });
});

describe('filterSupportedComponents filters Section accessories the same way ActionRow buttons already are', () => {
  it('drops a top-level Section whose accessory is a non-link button, keeping the rest', () => {
    const result = discordMessageImportShape.safeParse({
      components: [
        makeSection({
          type: 2, style: 1, custom_id: 'click', label: 'Custom',
        }),
        makeTextDisplay('kept'),
      ],
    });

    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.components).toEqual([{ type: 10, content: 'kept' }]);
    }
  });

  it('keeps a top-level Section whose accessory is a link button', () => {
    const result = discordMessageImportShape.safeParse({
      components: [makeSection(makeLinkButton())],
    });

    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.components).toHaveLength(1);
    }
  });

  it('drops a Section nested in a Container when its accessory is unsupported, keeping the container', () => {
    const result = discordMessageImportShape.safeParse({
      components: [
        makeContainer([
          makeSection({
            type: 2, style: 1, custom_id: 'click', label: 'Custom',
          }),
          makeTextDisplay('kept'),
        ]),
      ],
    });

    expect(result.success).toBe(true);
    if (result.success) {
      const container = result.data.components![0] as { components: unknown[] };
      expect(container.components).toEqual([{ type: 10, content: 'kept' }]);
    }
  });
});

describe('describeUnsupportedComponentTypes names what the lenient filter silently drops', () => {
  it('reports a top-level select menu by label', () => {
    const dropped = describeUnsupportedComponentTypes([
      { type: 3, custom_id: 'pick', options: [] },
      makeTextDisplay('kept'),
    ]);
    expect(dropped).toContain('Select Menu');
  });

  it('reports the unsupported accessory of a dropped Section', () => {
    const dropped = describeUnsupportedComponentTypes([
      makeSection({
        type: 2, style: 1, custom_id: 'click', label: 'Custom',
      }),
    ]);
    expect(dropped).toContain('Button');
  });

  it('reports nothing for a fully-supported message', () => {
    const dropped = describeUnsupportedComponentTypes([makeTextDisplay(), makeSection()]);
    expect(dropped).toEqual([]);
  });

  it('reports drops from unsupported container children', () => {
    const dropped = describeUnsupportedComponentTypes([
      makeContainer([{ type: 3, custom_id: 'pick', options: [] }, makeTextDisplay('kept')]),
    ]);
    expect(dropped).toContain('Select Menu');
  });
});

import { TRPCError } from '@trpc/server';
import { isApiError } from 'paracord';
import { getPostgres } from 'project-utils';

import authorizeGuildAdmin from './authorizeGuildAdmin';
import { mapMessage } from './shared';

import type { NextApiRequest } from 'next';

import redis from '~/utils/redis';

export async function getGuild(guildId: DiscordId, req: NextApiRequest) {
  try {
    await authorizeGuildAdmin(guildId, req);
    return await redis.fetchGuild(guildId);
  } catch (err) {
    if (err instanceof TRPCError) {
      if (err.code === 'NOT_FOUND') return null;
      throw err;
    }

    if (isApiError(err)) {
      switch (err.response?.status) {
        case 404: return null;
        default:
      }
    }

    console.error(err);
    throw new TRPCError({
      code: 'INTERNAL_SERVER_ERROR',
      message: 'An unknown error occurred. Please try again later or contact support.',
    });
  }

  // try {
  //   const response = await fetch(`${getBaseUrl()}/api/discord/guilds/${id}`, { headers: { cookie: document.cookie } });

  //   const guild: Guild = await response.json();

  //   return Object.keys(guild).length > 0 ? guild : null;
  // } catch (err) {
  //   console.error(err);
  // }
  // return null;
}

export async function getGuildMessages(guildId: string, req: NextApiRequest) {
  await authorizeGuildAdmin(guildId, req);

  const messages = await getPostgres()
    .selectFrom('Messages')
    .leftJoin('Guilds', 'Messages.fk_guilds_id', 'Guilds.id')
    .leftJoin('ScheduledMessages', 'ScheduledMessages.fk_messages_id', 'Messages.id')
    .select([
      'Messages.id', 'Messages.createdAt', 'Messages.updatedAt', 'Messages.name',
      'Messages.data', 'Messages.previewImageNonce',
      'Messages.recentMessageId', 'Messages.recentThreadId', 'Messages.recentWebhookId',
      'Guilds.guildId as guildId',
      'ScheduledMessages.id as scheduledMessageId', 'ScheduledMessages.cron as scheduledMessageCron',
      'ScheduledMessages.error as scheduledMessageError', 'ScheduledMessages.sendAt as scheduledMessageSendAt',
      'ScheduledMessages.sent as scheduledMessageSent',
    ])
    .where(({
      exists, selectFrom,
    }) => exists(selectFrom('Guilds')
      .select('Guilds.id')
      .where('Guilds.guildId', '=', guildId)
      .whereRef('Messages.fk_guilds_id', '=', 'Guilds.id')))
    .execute();

  return messages.map(mapMessage);
}

export async function getWebhooksAndChannels(guildId: DiscordId, req: NextApiRequest) {
  try {
    await authorizeGuildAdmin(guildId, req);
    return await redis.fetchWebhooksAndChannels(guildId);
  } catch (err) {
    if (err instanceof TRPCError) throw err;

    if (isApiError(err)) {
      switch (err.response?.status) {
        case 404:
          throw new TRPCError({
            code: 'NOT_FOUND',
            message: 'The bot is not in this server.',
          });
        default:
      }
    }

    console.error(err);
    throw new TRPCError({
      code: 'INTERNAL_SERVER_ERROR',
      message: 'An unknown error occurred. Please try again later or contact support.',
    });
  }
}

import { z } from 'zod';

import {
  MAX_ACTION_ROW_BUTTONS, MAX_ALLOWED_MENTION_IDS, MAX_BUTTON_LABEL_LENGTH,
  MAX_COMPONENTS_DISPLAYABLE_TEXT,
  MAX_EMBEDS, MAX_EMBED_AUTHOR_NAME_LENGTH, MAX_EMBED_DESCRIPTION_LENGTH,
  MAX_EMBED_FIELDS, MAX_EMBED_FIELD_NAME_LENGTH, MAX_EMBED_FIELD_VALUE_LENGTH,
  MAX_EMBED_FOOTER_TEXT_LENGTH, MAX_EMBED_TITLE_LENGTH,
  MAX_MEDIA_GALLERY_ITEMS,
  MAX_MESSAGE_CONTENT_LENGTH, MAX_MESSAGE_NAME_LENGTH, MAX_NAME_LENGTH,
  MAX_SECTION_TEXT_COMPONENTS,
  MAX_TEXT_DISPLAY_CONTENT_LENGTH,
  MAX_TOTAL_COMPONENTS,
} from '~/constants';

export interface RecentMessageData {
  id: string;
  recentWebhookId: string;
  recentThreadId: null | string;
  recentMessageId: string;
}

export interface IncomingMessage {
  id?: string;
  guildId?: null | string;
  name: string;
  data: MessageData;
}

export interface UpdateMessage {
  id: string;
  name: string;
  data: MessageData;
}

export const discordIdShape = z.string().regex(/^[0-9]{17,23}$/);

export function boundedArray<T extends z.ZodTypeAny>(element: T, max: number) {
  return z.array(z.unknown()).superRefine((list, ctx) => {
    if (list.length > max) {
      ctx.addIssue({
        code: z.ZodIssueCode.too_big,
        maximum: max,
        type: 'array',
        inclusive: true,
        exact: false,
        fatal: true,
      });
    }
  }).pipe(z.array(element)) as unknown as
    z.ZodType<z.output<z.ZodArray<T>>, z.ZodTypeDef, z.input<z.ZodArray<T>>>;
}

type UnionOptions = readonly [z.ZodTypeAny, z.ZodTypeAny, ...z.ZodTypeAny[]];

function isolatedUnion<T extends UnionOptions>(options: T) {
  const union = z.union(options);
  return z.any().transform((value, ctx) => {
    const result = union.safeParse(value);
    if (result.success) return result.data as unknown;
    const fatal = result.error.issues.some(({ code }) => code === z.ZodIssueCode.invalid_union);
    result.error.issues.forEach((issue) => ctx.addIssue({ ...issue, fatal }));
    return z.NEVER;
  }) as unknown as z.ZodType<z.output<T[number]>, z.ZodTypeDef, z.input<T[number]>>;
}

const MAX_REFUSAL_ISSUES = 20;

class StopChecking extends Error {}

function reduceIssue({ code, path, message }: z.ZodIssue) {
  return { code, path, message } as z.ZodIssue;
}

export function cappedInput<S extends z.ZodTypeAny>(schema: S) {
  return {
    _input: undefined as unknown as z.input<S>,
    _output: undefined as unknown as z.output<S>,
    async parseAsync(value: unknown): Promise<z.output<S>> {
      const seen: z.ZodIssue[] = [];
      const errorMap: z.ZodErrorMap = (issue, ctx) => {
        const message = issue.message ?? ctx.defaultError;
        seen.push({ ...issue, message } as z.ZodIssue);
        if (seen.length > MAX_REFUSAL_ISSUES) throw new StopChecking();
        return { message };
      };
      let result: z.SafeParseReturnType<z.input<S>, z.output<S>>;
      try {
        result = schema.safeParse(value, { errorMap });
      } catch (error) {
        if (!(error instanceof StopChecking)) throw error;
        throw new z.ZodError([...seen.slice(0, MAX_REFUSAL_ISSUES).map(reduceIssue), {
          code: z.ZodIssueCode.custom,
          path: [],
          message: `Stopped checking after ${MAX_REFUSAL_ISSUES} errors`,
        }]);
      }
      // eslint-disable-next-line @typescript-eslint/no-unsafe-return
      if (result.success) return result.data;
      throw new z.ZodError(result.error.issues.map(reduceIssue));
    },
  };
}

const ALLOWED_MENTION_PARSE_TYPES = ['user', 'here', 'everyone'] as const;

type LiteralOptions<T extends readonly string[]> = {
  -readonly [K in keyof T]: z.ZodLiteral<T[K]>;
};
type AllowedMentionParseOptions = LiteralOptions<typeof ALLOWED_MENTION_PARSE_TYPES>;

const MAX_MESSAGE_ID = 9223372036854775807n;

export const messageIdShape = z.string()
  .regex(/^[0-9]{1,19}$/)
  .transform((id) => BigInt(id))
  .refine((id) => id <= MAX_MESSAGE_ID)
  .transform((id) => id.toString());
export const userOrDiscordIdShape = z.string().regex(/^(0|[0-9]{17,23})$/);

// Components V2 Zod schemas

const emojiShape = z.object({
  id: z.string().optional(),
  name: z.string().optional(),
  animated: z.boolean().optional(),
});

const linkButtonShape = z.object({
  type: z.literal(2),
  style: z.literal(5),
  label: z.string().trim().max(MAX_BUTTON_LABEL_LENGTH).optional(),
  emoji: emojiShape.optional(),
  url: z.string().trim().url(),
  disabled: z.boolean().optional(),
});

const actionRowShape = z.object({
  type: z.literal(1),
  components: boundedArray(linkButtonShape, MAX_ACTION_ROW_BUTTONS),
});

const textDisplayShape = z.object({
  type: z.literal(10),
  content: z.string().max(MAX_TEXT_DISPLAY_CONTENT_LENGTH),
});

const thumbnailShape = z.object({
  type: z.literal(11),
  media: z.object({ url: z.string().trim().url() }),
  description: z.string().optional(),
  spoiler: z.boolean().optional(),
});

const sectionShape = z.object({
  type: z.literal(9),
  components: boundedArray(textDisplayShape, MAX_SECTION_TEXT_COMPONENTS),
  accessory: isolatedUnion([thumbnailShape, linkButtonShape]),
});

const mediaGalleryItemShape = z.object({
  media: z.object({ url: z.string().trim().url() }),
  description: z.string().optional(),
  spoiler: z.boolean().optional(),
});

const mediaGalleryShape = z.object({
  type: z.literal(12),
  items: boundedArray(mediaGalleryItemShape, MAX_MEDIA_GALLERY_ITEMS),
});

const fileShape = z.object({
  type: z.literal(13),
  file: z.object({ url: z.string().trim().url() }),
  spoiler: z.boolean().optional(),
});

const separatorShape = z.object({
  type: z.literal(14),
  divider: z.boolean(),
  spacing: isolatedUnion([z.literal(1), z.literal(2)]),
});

export const containerChildShape = z.discriminatedUnion('type', [
  actionRowShape,
  textDisplayShape,
  sectionShape,
  mediaGalleryShape,
  fileShape,
  separatorShape,
]);

const containerShape = z.object({
  type: z.literal(17),
  components: boundedArray(containerChildShape, MAX_TOTAL_COMPONENTS),
  accent_color: z.number().int().min(0).max(0xffffff)
    .optional(),
  spoiler: z.boolean().optional(),
});

export const topLevelComponentShape = z.discriminatedUnion('type', [
  actionRowShape,
  textDisplayShape,
  sectionShape,
  mediaGalleryShape,
  fileShape,
  separatorShape,
  containerShape,
]);

export const embedShape = z.object({
  author: z.object({
    name: z.string().trim().max(MAX_EMBED_AUTHOR_NAME_LENGTH),
    url: z.string().trim().url().optional(),
    icon_url: z.string().trim().url().optional(),
  }).optional(),
  url: z.string().trim().url().optional(),
  description: z.string().trim().max(MAX_EMBED_DESCRIPTION_LENGTH).optional(),
  color: z.number().int().min(0).max(0xffffff)
    .optional(),
  title: z.string().trim().max(MAX_EMBED_TITLE_LENGTH).optional(),
  fields: boundedArray(
    z.object({
      name: z.string().trim().max(MAX_EMBED_FIELD_NAME_LENGTH),
      value: z.string().trim().max(MAX_EMBED_FIELD_VALUE_LENGTH),
      inline: z.boolean().optional(),
    }),
    MAX_EMBED_FIELDS,
  ).optional(),
  timestamp: z.string().trim().datetime().optional(),
  footer: z.object({
    text: z.string().trim().max(MAX_EMBED_FOOTER_TEXT_LENGTH),
    icon_url: z.string().trim().url().optional(),
  }).optional(),
  image: z.object({
    url: z.string().trim().url(),
  }).optional(),
  thumbnail: z.object({
    url: z.string().trim().url(),
  }).optional(),
});

function sumDisplayableText(
  components: { type: number, content?: string, components?: unknown[] }[],
): number {
  let total = 0;
  for (const c of components) {
    if (c.type === 10 && typeof c.content === 'string') {
      total += c.content.length;
    } else if ((c.type === 9 || c.type === 17) && Array.isArray(c.components)) {
      total += sumDisplayableText(c.components as typeof components);
    }
  }
  return total;
}

function refineDisplayableText(data: { components?: unknown[] }, ctx: z.RefinementCtx) {
  if (!data.components) return;
  const total = sumDisplayableText(data.components as Parameters<typeof sumDisplayableText>[0]);
  if (total > MAX_COMPONENTS_DISPLAYABLE_TEXT) {
    ctx.addIssue({
      code: z.ZodIssueCode.too_big,
      maximum: MAX_COMPONENTS_DISPLAYABLE_TEXT,
      type: 'string',
      inclusive: true,
      path: ['components'],
      message: `Components displayable text size exceeds maximum size of ${MAX_COMPONENTS_DISPLAYABLE_TEXT}`,
    });
  }
}

const discordMessageBaseShape = z.object({
  content: z.string().trim().max(MAX_MESSAGE_CONTENT_LENGTH).optional(),
  username: z.string().trim().max(MAX_NAME_LENGTH).optional(),
  avatar_url: z.string().trim().url().optional(),
  allowed_mentions: z.object({
    parse: boundedArray(
      isolatedUnion(ALLOWED_MENTION_PARSE_TYPES.map((type) => z.literal(type)) as unknown as AllowedMentionParseOptions),
      ALLOWED_MENTION_PARSE_TYPES.length,
    ).optional(),
    users: boundedArray(discordIdShape, MAX_ALLOWED_MENTION_IDS).optional(),
    roles: boundedArray(discordIdShape, MAX_ALLOWED_MENTION_IDS).optional(),
    replied_user: z.boolean().optional(),
  }).optional(),
  embeds: boundedArray(embedShape, MAX_EMBEDS).optional(),
  components: boundedArray(topLevelComponentShape, MAX_TOTAL_COMPONENTS).optional(),
  flags: z.number().int().nonnegative().optional(),
});

export const discordMessageShape = discordMessageBaseShape
  .superRefine(refineDisplayableText) as z.ZodEffects<typeof discordMessageBaseShape, MessageData>;

const LINK_BUTTON_STYLE = 5;
const SECTION_TYPE = 9;
const ACTION_ROW_TYPE = 1;
const CONTAINER_TYPE = 17;
const BUTTON_TYPE = 2;
const THUMBNAIL_TYPE = 11;

export const SUPPORTED_TOP_LEVEL_TYPES = new Set([1, 9, 10, 12, 13, 14, 17]);
export const SUPPORTED_CONTAINER_CHILD_TYPES = new Set([1, 9, 10, 12, 13, 14]);

const COMPONENT_TYPE_LABELS: Record<number, string> = {
  [BUTTON_TYPE]: 'Button',
  3: 'Select Menu',
  4: 'Text Input',
  5: 'User Select Menu',
  6: 'Role Select Menu',
  7: 'Mentionable Select Menu',
  8: 'Channel Select Menu',
  [THUMBNAIL_TYPE]: 'Thumbnail',
};

function labelFor(type: number): string {
  return COMPONENT_TYPE_LABELS[type] ?? `type ${type}`;
}

function isSupportedAccessory(accessory: unknown): boolean {
  if (typeof accessory !== 'object' || accessory === null) return false;
  const { type, style } = accessory as { type: number, style?: number };
  if (type === THUMBNAIL_TYPE) return true;
  return type === BUTTON_TYPE && style === LINK_BUTTON_STYLE;
}

function accessoryLabel(accessory: unknown): string {
  if (typeof accessory !== 'object' || accessory === null) return labelFor(SECTION_TYPE);
  return labelFor((accessory as { type: number }).type);
}

function filterActionRowButtons(
  row: Record<string, unknown>,
  dropped?: Set<string>,
): Record<string, unknown> | null {
  const buttons = Array.isArray(row.components) ? row.components as Record<string, unknown>[] : [];
  const kept = buttons.filter((button) => {
    if (button.type === BUTTON_TYPE && button.style === LINK_BUTTON_STYLE) return true;
    dropped?.add(labelFor(button.type as number));
    return false;
  });
  if (kept.length === 0) return null;
  return { ...row, components: kept };
}

function filterSection(
  section: Record<string, unknown>,
  dropped?: Set<string>,
): Record<string, unknown> | null {
  if (!isSupportedAccessory(section.accessory)) {
    dropped?.add(accessoryLabel(section.accessory));
    return null;
  }
  return section;
}

function filterContainerChild(
  child: Record<string, unknown>,
  dropped?: Set<string>,
): Record<string, unknown> | null {
  if (!SUPPORTED_CONTAINER_CHILD_TYPES.has(child.type as number)) {
    dropped?.add(labelFor(child.type as number));
    return null;
  }
  if (child.type === ACTION_ROW_TYPE) return filterActionRowButtons(child, dropped);
  if (child.type === SECTION_TYPE) return filterSection(child, dropped);
  return child;
}

function filterTopLevelComponent(
  component: Record<string, unknown>,
  dropped?: Set<string>,
): Record<string, unknown> | null {
  if (!SUPPORTED_TOP_LEVEL_TYPES.has(component.type as number)) {
    dropped?.add(labelFor(component.type as number));
    return null;
  }
  if (component.type === ACTION_ROW_TYPE) return filterActionRowButtons(component, dropped);
  if (component.type === SECTION_TYPE) return filterSection(component, dropped);
  if (component.type === CONTAINER_TYPE && Array.isArray(component.components)) {
    const children = (component.components as Record<string, unknown>[])
      .map((child) => (typeof child === 'object' && child !== null ? filterContainerChild(child, dropped) : null))
      .filter((child): child is Record<string, unknown> => child !== null);
    if (children.length === 0) return null;
    return { ...component, components: children };
  }
  return component;
}

function filterSupportedComponents(components: unknown): unknown {
  if (!Array.isArray(components)) return components;
  return (components as unknown[])
    .map((c) => (typeof c === 'object' && c !== null ? filterTopLevelComponent(c as Record<string, unknown>) : null))
    .filter(Boolean);
}

export function describeUnsupportedComponentTypes(components: unknown): string[] {
  const dropped = new Set<string>();
  if (!Array.isArray(components)) return [];
  (components as unknown[]).forEach((c) => {
    if (typeof c === 'object' && c !== null) filterTopLevelComponent(c as Record<string, unknown>, dropped);
  });
  return [...dropped];
}

export function describeDroppedComponentTypesNotice(
  droppedComponentTypes: readonly string[],
): string {
  return `Not supported on Hooks.gg: ${droppedComponentTypes.join(', ')}`;
}

/** Lenient schema for JSON import — filters unsupported component types instead of rejecting. */
export const discordMessageImportShape = discordMessageBaseShape.extend({
  components: z.preprocess(
    filterSupportedComponents,
    boundedArray(topLevelComponentShape, MAX_TOTAL_COMPONENTS).optional(),
  ),
}).superRefine(refineDisplayableText);

export const recentMessageDataShape = z.object({
  id: messageIdShape,
  recentWebhookId: discordIdShape,
  recentThreadId: discordIdShape.nullable(),
  recentMessageId: discordIdShape,
}) satisfies z.ZodType<RecentMessageData>;

export const messageShape = z.object({
  name: z.string().min(1).max(MAX_MESSAGE_NAME_LENGTH),
  guildId: discordIdShape.nullable().optional(),
  data: discordMessageShape,
}) satisfies z.ZodType<IncomingMessage>;

export const partialMessageShape = messageShape.extend({
  id: z.string().optional(),
  name: z.string().min(1).max(MAX_MESSAGE_NAME_LENGTH).optional(),
}) satisfies z.ZodType<Omit<IncomingMessage, 'name' | 'guildId'> & Partial<Pick<IncomingMessage, 'name' | 'guildId'>>>;

export const optionalIdMessageShape = messageShape.extend({
  id: messageIdShape.optional(),
}) satisfies z.ZodType<IncomingMessage>;

export const idMessageShape = messageShape.extend({
  id: z.string(),
}) satisfies z.ZodType<UpdateMessage>;

import { TRPCError } from '@trpc/server';
import { waitUntil } from '@vercel/functions';
import { sql } from 'kysely';
import { getPostgres } from 'project-utils';
import Pusher from 'pusher';

import { isMessageValid } from './messageValidity';
import { mintNonce, runPreviewContinuation } from './previewImage';

import type { InsertObject, Kysely } from 'kysely';
import type { DatabaseSchema } from 'project-utils';
import type { IncomingMessage, RecentMessageData } from './shapes';

import { MAX_MESSAGES } from '~/constants';
import { env } from '~/env.mjs';
import { genMessageChannelKey, hashMessage } from '~/utils';

type Select = { dbUserId: string } | { guild: { id: string } };
type MessageOwner = { dbUserId: string } | { guildId: string };
function isUserSelect(select: Select): select is { dbUserId: string } {
  return 'dbUserId' in select;
}

type DatabaseMessage = {
  id: string;
  name: string;
  createdAt: Date;
  guildId?: string | null;
  updatedAt: Date;
  previewImageNonce: null | string;
  recentWebhookId: null | string;
  recentThreadId: null | string;
  recentMessageId: null | string;
  data: unknown;
};

interface DatabaseScheduledMessage extends DatabaseMessage {
  scheduledMessageId: string | null;
  scheduledMessageCron: string | null;
  scheduledMessageError: string | null;
  scheduledMessageSendAt: Date | null;
  scheduledMessageSent: boolean | null;
}

function isScheduledMessage(
  message: DatabaseMessage | DatabaseScheduledMessage,
): message is DatabaseScheduledMessage {
  return 'scheduledMessageId' in message;
}

export function mapMessage(
  message: DatabaseMessage | DatabaseScheduledMessage,
) {
  const {
    id, guildId, createdAt, updatedAt, name, previewImageNonce, data,
    recentWebhookId, recentThreadId, recentMessageId,
  } = message;
  const tmp: ApiMessage = {
    id: String(id),
    createdAt: createdAt.getTime(),
    updatedAt: updatedAt.getTime(),
    previewImageNonce,
    name,
    data: data as MessageData,
    recentWebhookId,
    recentThreadId,
    recentMessageId,
  };

  if (guildId) tmp.guildId = guildId;

  if (
    isScheduledMessage(message)
    && message.scheduledMessageId
    && message.scheduledMessageSendAt
    && message.scheduledMessageSent !== null
  ) {
    const {
      scheduledMessageCron, scheduledMessageError, scheduledMessageId,
      scheduledMessageSendAt, scheduledMessageSent,
    } = message;
    tmp.scheduledMessage = {
      id: scheduledMessageId,
      cron: scheduledMessageCron,
      error: scheduledMessageError,
      sendAt: scheduledMessageSendAt.getTime(),
      sent: scheduledMessageSent,
    };
  }

  return tmp;
}

function mapPartialApiMessage({
  id, createdAt, updatedAt, name, guildId, previewImageNonce,
}: Pick<DatabaseMessage, 'id' | 'createdAt' | 'updatedAt' | 'name' | 'previewImageNonce' | 'guildId'>) {
  const tmp: PartialApiMessage = {
    id,
    createdAt: createdAt.getTime(),
    updatedAt: updatedAt.getTime(),
    name,
    previewImageNonce,
  };

  if (guildId) tmp.guildId = guildId;
  return tmp;
}

export async function getUserRecentMessages(
  messageIds: string[],
  dbUserId: string,
): Promise<PartialApiMessage[]> {
  if (!messageIds.length) return [];

  const messages = getPostgres()
    .selectFrom('Messages')
    .leftJoin('Guilds', 'Messages.fk_guilds_id', 'Guilds.id')
    .select([
      'Messages.id', 'Messages.createdAt', 'Messages.updatedAt', 'Messages.name',
      'Messages.previewImageNonce', 'Guilds.guildId as guildId',
    ])
    .where('Messages.id', 'in', messageIds)
    .where(({ or, eb }) => or([
      eb('Messages.fk_users_id', '=', dbUserId),
      eb('Messages.fk_guilds_id', 'is not', null),
    ]))
    .execute();

  return (await messages).map(mapPartialApiMessage);
}

export async function getUserMessages(dbUserId: string) {
  const messages = await getPostgres()
    .selectFrom('Messages')
    .select([
      'Messages.id', 'Messages.createdAt', 'Messages.updatedAt', 'Messages.name',
      'Messages.previewImageNonce',
    ])
    .where('Messages.fk_users_id', '=', dbUserId)
    .execute();

  return messages.map(mapPartialApiMessage);
}

export async function getMessage(id: string) {
  const message = await getPostgres()
    .selectFrom('Messages')
    .leftJoin('Guilds', 'Messages.fk_guilds_id', 'Guilds.id')
    .leftJoin('ScheduledMessages', 'ScheduledMessages.fk_messages_id', 'Messages.id')
    .select([
      'Messages.id', 'Messages.createdAt', 'Messages.updatedAt', 'Messages.name',
      'Messages.data', 'Messages.previewImageNonce',
      'Messages.recentMessageId', 'Messages.recentThreadId', 'Messages.recentWebhookId',
      'Guilds.guildId as guildId',
      'ScheduledMessages.id as scheduledMessageId', 'ScheduledMessages.cron as scheduledMessageCron',
      'ScheduledMessages.error as scheduledMessageError', 'ScheduledMessages.sendAt as scheduledMessageSendAt',
      'ScheduledMessages.sent as scheduledMessageSent',
    ])
    .where('Messages.id', '=', id)
    .executeTakeFirstOrThrow();
  return mapMessage(message);
}

export async function getPartialMessages(
  userId: string,
  guilds: UserGuild[],
) {
  const query = getPostgres()
    .selectFrom('Messages')
    .leftJoin('Guilds', 'Messages.fk_guilds_id', 'Guilds.id')
    .select([
      'Messages.id', 'Messages.createdAt', 'Messages.updatedAt', 'Messages.name',
      'Messages.previewImageNonce', 'Guilds.guildId as guildId',
    ]);

  const messages = await (guilds.length
    ? query.where(({
      or, exists, eb, selectFrom,
    }) => or([
      eb('Messages.fk_users_id', '=', userId),
      exists(selectFrom('Guilds')
        .select('Guilds.id')
        .where('Guilds.guildId', 'in', guilds.map(({ id }) => id))
        .whereRef('Messages.fk_guilds_id', '=', 'Guilds.id')),
    ]))
    : query.where('Messages.fk_users_id', '=', userId)
  ).execute();

  return messages.map(mapPartialApiMessage);
}

async function upsertGuild(guildId: string) {
  const guild = await getPostgres()
    .insertInto('Guilds')
    .values({ guildId, provider: 'discord' })
    .onConflict((oc) => oc.columns(['provider', 'guildId']).doUpdateSet({ guildId }))
    .returning(['id'])
    .executeTakeFirstOrThrow();

  return guild.id;
}

export function buildMessageValues(
  message: Pick<IncomingMessage, 'name' | 'data'>,
  select: { dbUserId: string } | { guild: { id: string } },
): Omit<InsertObject<DatabaseSchema, 'Messages'>, 'fk_guilds_id'> & { fk_guilds_id?: string | null } {
  return {
    updatedAt: new Date(),
    name: message.name,
    data: message.data,
    valid: isMessageValid(message.data),
    fk_users_id: isUserSelect(select) ? select.dbUserId : null,
  };
}

export function buildInsertMessageQuery(
  database: Kysely<DatabaseSchema>,
  values: InsertObject<DatabaseSchema, 'Messages'>,
) {
  return database
    .insertInto('Messages')
    .values(values)
    .returning([
      'id',
      sql<string>`(extract(epoch from clock_timestamp()) * 1000000)::bigint::text`.as('savedAtMicros'),
    ]);
}

export function buildUpdateOwnedMessageQuery(
  database: Kysely<DatabaseSchema>,
  id: string,
  values: InsertObject<DatabaseSchema, 'Messages'>,
) {
  const query = database
    .updateTable('Messages')
    .set({
      name: values.name,
      data: values.data,
      valid: values.valid,
      updatedAt: values.updatedAt,
    })
    .where('id', '=', id);

  return (values.fk_guilds_id
    ? query.where('fk_guilds_id', '=', values.fk_guilds_id as string)
    : query.where('fk_users_id', '=', values.fk_users_id as string)
  ).returning([
    'id',
    sql<string>`(extract(epoch from clock_timestamp()) * 1000000)::bigint::text`.as('savedAtMicros'),
  ]);
}

export async function upsertMessage(
  message: IncomingMessage,
  select: Select,
) {
  const database = getPostgres();
  const guildRowId = isUserSelect(select) ? null : await upsertGuild(select.guild.id);
  const values: InsertObject<DatabaseSchema, 'Messages'> = {
    ...buildMessageValues(message, select),
    fk_guilds_id: guildRowId,
  };

  const updated = message.id
    ? await buildUpdateOwnedMessageQuery(database, message.id, values).executeTakeFirst()
    : undefined;

  let saved = updated;
  if (!saved) {
    const messageCountQuery = database.selectFrom('Messages').select(database.fn.countAll().as('count'));
    const { count: messageCount } = await (guildRowId
      ? messageCountQuery.where('fk_guilds_id', '=', guildRowId)
      : messageCountQuery.where('fk_users_id', '=', values.fk_users_id as string)
    ).executeTakeFirstOrThrow();
    if (Number(messageCount) >= MAX_MESSAGES) {
      throw new TRPCError({
        code: 'BAD_REQUEST',
        message: `You have reached the limit of ${MAX_MESSAGES} messages per ${isUserSelect(select) ? 'user' : 'guild'}.`,
      });
    }

    saved = await buildInsertMessageQuery(database, values).executeTakeFirstOrThrow();
  }

  const { id, savedAtMicros } = saved;
  const newMessagePromise = getMessage(id);

  waitUntil(runPreviewContinuation({ id, nonce: mintNonce(savedAtMicros), message: message.data }));

  if (updated && message.id) {
    const pusher = new Pusher({
      appId: env.PUSHER_APP_ID,
      key: env.NEXT_PUBLIC_PUSHER_KEY,
      secret: env.PUSHER_SECRET,
      cluster: env.NEXT_PUBLIC_PUSHER_CLUSTER,
      useTLS: true,
    });

    await pusher.trigger(genMessageChannelKey(message.id), 'message-update', JSON.stringify(hashMessage(message)));
  }

  return newMessagePromise;
}

export async function updateRecentMessageData(
  message: RecentMessageData,
  owner: MessageOwner,
) {
  const query = getPostgres()
    .updateTable('Messages')
    .set({
      recentWebhookId: message.recentWebhookId,
      recentThreadId: message.recentThreadId,
      recentMessageId: message.recentMessageId,
    })
    .where('id', '=', message.id);

  await ('dbUserId' in owner
    ? query.where('fk_users_id', '=', owner.dbUserId)
    : query.where('fk_guilds_id', 'in', (eb) => eb
      .selectFrom('Guilds')
      .select('Guilds.id')
      .where('Guilds.guildId', '=', owner.guildId))
  ).execute();
}

export async function deleteOwnedMessage(id: string, owner: MessageOwner) {
  const query = getPostgres()
    .deleteFrom('Messages')
    .where('id', '=', id);

  const deleted = await ('dbUserId' in owner
    ? query.where('fk_users_id', '=', owner.dbUserId)
    : query.where('fk_guilds_id', 'in', (eb) => eb
      .selectFrom('Guilds')
      .select('Guilds.id')
      .where('Guilds.guildId', '=', owner.guildId))
  ).returning('id').execute();

  return deleted.length > 0;
}

