/**
 * The ingress converter (`discordResponseToMessage`) does not normalise a Discord message
 * carrying both classic content and V2 components together — it preserves the conflict, so a
 * record fetched through the bot/webhook/code import paths can produce a row-E draft (structural
 * V2 components plus classic content), and that draft trips the persist gate
 * (`gateBeforePersist`). Controls confirm the gate is not simply always true.
 *
 * `NewMessageModal`'s own wiring — whether its Save button actually lets a user act on a row-E
 * draft — is covered (and its current limits recorded, in a handoff under `agent-output/handoff/`)
 * separately, in `NewMessageModal.persist-gate-wiring.test.tsx`.
 */
import { describe, expect, it, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import discordResponseToMessage from '~/utils/discordResponseToMessage';
import { gateBeforePersist } from '~/utils';

const IS_V2 = 1 << 15;
const CONTAINER = { type: 17, components: [{ type: 10, content: 'x' }] };

const apiMessage = (over: Record<string, unknown> = {}) => ({
  author: { id: '1', username: 'u', avatar: null, discriminator: '0' },
  content: 'hi',
  embeds: [],
  components: [CONTAINER],
  flags: IS_V2,
  ...over,
});

describe('the ingress converter can produce a row-E draft', () => {
  it('the converter does NOT normalise: content, components and the flag all survive together', () => {
    const { data } = discordResponseToMessage(apiMessage() as never);
    expect(data.content).toBe('hi');
    expect(data.flags).toBe(IS_V2);
    expect(data.components as unknown[]).toHaveLength(1);
  });

  it('that output trips the persist gate', () => {
    const { data } = discordResponseToMessage(apiMessage() as never);
    const gate = gateBeforePersist(data as never);
    expect(gate.mustAsk).toBe(true);
    expect(gate.options).toHaveLength(2);
  });

  it('each option names what it would drop, so a caller has something truthful to render', () => {
    const { data } = discordResponseToMessage(apiMessage() as never);
    const { options } = gateBeforePersist(data as never);
    expect(options?.map((o) => o.mode).sort()).toEqual(['classic', 'v2']);
    options?.forEach((o) => expect(o.dropSet.length).toBeGreaterThan(0));
  });
});

describe('controls: mustAsk is not simply always true', () => {
  it('a classic-only Discord message does NOT trip the gate', () => {
    const { data } = discordResponseToMessage(apiMessage({ components: [], flags: 0 }) as never);
    expect(gateBeforePersist(data as never).mustAsk).toBe(false);
  });

  it('a V2-only Discord message (no classic body) does NOT trip the gate', () => {
    const { data } = discordResponseToMessage(apiMessage({ content: '' }) as never);
    expect(gateBeforePersist(data as never).mustAsk).toBe(false);
  });

  it('a flagged classic message (row D) does NOT trip the gate — it resolves without asking', () => {
    const { data } = discordResponseToMessage(apiMessage({ components: [] }) as never);
    expect(gateBeforePersist(data as never).mustAsk).toBe(false);
  });
});

