import { describe, it, expect, vi } from 'vitest';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import { genUuid, rekeyComponent } from '~/utils';
import {
  MAX_SECTION_TEXT_COMPONENTS,
  MAX_ACTION_ROW_BUTTONS,
  MAX_MEDIA_GALLERY_ITEMS,
} from '~/constants';

// ============================================================
// Helper: build component fixtures with _key values
// ============================================================

function makeEditableTextDisplay(content = 'Hello'): EditableTextDisplay {
  return { type: 10, content, _key: genUuid() } as EditableTextDisplay;
}

function makeEditableLinkButton(label = 'Click'): EditableLinkButton {
  return {
    type: 2, style: 5, url: 'https://example.com', label, _key: genUuid(),
  } as EditableLinkButton;
}

function makeEditableThumbnail(): EditableThumbnail {
  return {
    type: 11, media: { url: 'https://example.com/img.png' }, _key: genUuid(),
  } as EditableThumbnail;
}

function makeEditableSection(textCount = 1): EditableSection {
  return {
    type: 9,
    components: Array.from({ length: textCount }, (_, i) => makeEditableTextDisplay(`Text ${i}`)),
    accessory: makeEditableThumbnail(),
    _key: genUuid(),
  } as EditableSection;
}

function makeEditableMediaGalleryItem(): EditableMediaGalleryItem {
  return {
    media: { url: 'https://example.com/img.png' },
    _key: genUuid(),
  } as EditableMediaGalleryItem;
}

// ============================================================
// Section Text Display Actions
// ============================================================

describe('Section text display actions', () => {
  describe('deleteTextComponent', () => {
    it('removes the text display at the given index from a multi-text section', () => {
      const section = makeEditableSection(3);
      const idx = 1;
      const original = section.components[idx];

      const result = section.components.filter((_, i) => i !== idx);

      expect(result).toHaveLength(2);
      expect(result).not.toContainEqual(original);
      expect(result[0]).toBe(section.components[0]);
      expect(result[1]).toBe(section.components[2]);
    });

    it('returns empty array when deleting the sole text display (triggers auto-remove)', () => {
      const section = makeEditableSection(1);

      const result = section.components.filter((_, i) => i !== 0);

      expect(result).toHaveLength(0);
    });
  });

  describe('duplicateTextComponent', () => {
    it('clones the text display with a new _key and inserts after original', () => {
      const section = makeEditableSection(2);
      const idx = 0;
      const original = section.components[idx];

      const clone: EditableTextDisplay = { ...original, _key: genUuid() };
      const next = [...section.components];
      next.splice(idx + 1, 0, clone);

      expect(next).toHaveLength(3);
      expect(next[0]).toBe(original);
      expect(next[1].content).toBe(original.content);
      expect(next[1]._key).not.toBe(original._key);
      expect(next[2]).toBe(section.components[1]);
    });

    it('is gated by MAX_SECTION_TEXT_COMPONENTS (no-op at limit)', () => {
      const section = makeEditableSection(MAX_SECTION_TEXT_COMPONENTS);

      const canDuplicate = section.components.length < MAX_SECTION_TEXT_COMPONENTS;

      expect(canDuplicate).toBe(false);
    });
  });

  describe('moveTextComponentUp', () => {
    it('swaps the text display with the one above it', () => {
      const section = makeEditableSection(3);
      const idx = 1;
      const next = [...section.components];
      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];

      expect(next[0]).toBe(section.components[1]);
      expect(next[1]).toBe(section.components[0]);
      expect(next[2]).toBe(section.components[2]);
    });

    it('is not available for the first item', () => {
      const canMoveUp = 0 > 0;
      expect(canMoveUp).toBe(false);
    });
  });

  describe('moveTextComponentDown', () => {
    it('swaps the text display with the one below it', () => {
      const section = makeEditableSection(3);
      const idx = 1;
      const next = [...section.components];
      [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];

      expect(next[0]).toBe(section.components[0]);
      expect(next[1]).toBe(section.components[2]);
      expect(next[2]).toBe(section.components[1]);
    });

    it('is not available for the last item', () => {
      const section = makeEditableSection(3);
      const lastIdx = section.components.length - 1;
      const canMoveDown = lastIdx < section.components.length - 1;
      expect(canMoveDown).toBe(false);
    });
  });
});

