// Container Child Duplicate
// ============================================================

describe('Container child duplicate', () => {
  it('deep-clones a section child with fresh _key values via rekeyComponent', () => {
    const child = makeEditableSection(2);
    const originalKey = child._key;
    const originalChildKeys = child.components.map((c) => c._key);

    const cloned = rekeyComponent(
      child as EditableTopLevelComponent,
    ) as EditableContainerChild;

    expect(cloned._key).not.toBe(originalKey);
    expect((cloned as EditableSection).components[0]._key).not.toBe(originalChildKeys[0]);
    expect((cloned as EditableSection).components[1]._key).not.toBe(originalChildKeys[1]);
    expect((cloned as EditableSection).components[0].content).toBe(child.components[0].content);
  });

  it('splices the clone after the original in the children array', () => {
    const children: EditableContainerChild[] = [
      makeEditableTextDisplay('A') as EditableContainerChild,
      makeEditableSection(1) as EditableContainerChild,
      makeEditableTextDisplay('B') as EditableContainerChild,
    ];
    const idx = 1;

    const clone = rekeyComponent(
      children[idx] as EditableTopLevelComponent,
    ) as EditableContainerChild;
    const next = [...children];
    next.splice(idx + 1, 0, clone);

    expect(next).toHaveLength(4);
    expect(next[1]).toBe(children[1]);
    expect(next[2]._key).not.toBe(children[1]._key);
    expect(next[3]).toBe(children[2]);
  });
});

