import { DISCORD_V2_SEND_CORPUS } from './helpers/discordV2SendCorpus';

import { isMessageValid } from '~/server/api/utils/messageValidity';
import { validateMessage } from '~/utils/limits';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

const V2_FLAG = 32768;

const withBody = (body: object) => ({ username: 'Probe', ...body }) as unknown as MessageData;
const v2 = (components: object[]) => withBody({ flags: V2_FLAG, components });
const structural = (components: object[]) => withBody({ flags: 0, components });

const refused = DISCORD_V2_SEND_CORPUS.filter((m) => m.discord === 'refused');
const accepted = DISCORD_V2_SEND_CORPUS.filter((m) => m.discord === 'accepted');

describe('validateMessage over the shapes Discord was measured on', () => {
  it('covers the whole measured population', () => {
    expect(refused).toHaveLength(86);
    expect(accepted).toHaveLength(34);
  });

  it.each(refused)('refuses a message Discord refused: $shape', (member) => {
    expect(validateMessage(withBody(member.body))).not.toBe('');
  });

  it.each(accepted)('sends a message Discord accepted: $shape', (member) => {
    expect(validateMessage(withBody(member.body))).toBe('');
  });
});

describe('isMessageValid over the shapes Discord was measured on', () => {
  it.each(refused)('records a message Discord refused as not valid: $shape', (member) => {
    expect(isMessageValid(withBody(member.body))).toBe(false);
  });

  it.each(accepted)('records a message Discord accepted as valid: $shape', (member) => {
    expect(isMessageValid(withBody(member.body))).toBe(true);
  });
});

describe('which messages the component checks apply to', () => {
  const emptyRow = { type: 1, components: [] };

  it('refuses an empty Action Row when only the V2 flag makes the message V2', () => {
    expect(validateMessage(v2([emptyRow]))).not.toBe('');
  });

  it('refuses an empty Text Display when only the component types make the message V2', () => {
    expect(validateMessage(structural([makeTextDisplay('')]))).not.toBe('');
  });

  it('leaves a classic message with a link button in every refused button shape as it was', () => {
    const buttons = [
      makeLinkButton({ url: '' }),
      makeLinkButton({ url: 'abc' }),
      makeLinkButton({ url: 'ftp://example.com/x' }),
      makeLinkButton({ label: undefined }),
    ];
    for (const button of buttons) {
      expect(validateMessage(withBody({ content: 'Hi', flags: 0, components: [makeActionRow([button])] }))).toBe('');
    }
    expect(validateMessage(withBody({ content: 'Hi', flags: 0, components: [emptyRow] }))).toBe('');
  });
});

describe('whitespace in a Text Display and a link button label', () => {
