type Placement = 'top' | 'container' | 'section';

interface Fault {
  readonly name: string;
  readonly word: string;
  readonly kind: 'child' | 'accessory' | 'button' | 'item';
  readonly piece: object;
}

const okImage = 'https://example.com/a.png';
const faults: readonly Fault[] = [
  {
    name: 'empty Text Display', word: 'Text Display', kind: 'child', piece: makeTextDisplay(''),
  },
  {
    name: 'Text Display with no content', word: 'Text Display', kind: 'child', piece: { type: 10 },
  },
  {
    name: 'Section with no text', word: 'Section', kind: 'child', piece: { type: 9, components: [], accessory: makeThumbnail() },
  },
  {
    name: 'Section with no accessory', word: 'Section', kind: 'child', piece: { type: 9, components: [makeTextDisplay()] },
  },
  {
    name: 'empty Media Gallery', word: 'Media Gallery', kind: 'child', piece: { type: 12, items: [] },
  },
  {
    name: 'empty Container', word: 'Container', kind: 'child', piece: { type: 17, components: [] },
  },
  {
    name: 'empty Action Row', word: 'Action Row', kind: 'child', piece: { type: 1, components: [] },
  },
  {
    name: 'File', word: 'File', kind: 'child', piece: makeFile(),
  },
  {
    name: 'Thumbnail with no image URL', word: 'Thumbnail', kind: 'accessory', piece: { type: 11, media: { url: '' } },
  },
  {
    name: 'Thumbnail with no media', word: 'Thumbnail', kind: 'accessory', piece: { type: 11 },
  },
  {
    name: 'Thumbnail with an invalid URL', word: 'Thumbnail', kind: 'accessory', piece: { type: 11, media: { url: 'abc' } },
  },
  {
    name: 'Thumbnail with an empty description', word: 'Thumbnail', kind: 'accessory', piece: { ...makeThumbnail(), description: '' },
  },
  {
    name: 'Thumbnail with a 1025-character description', word: 'Thumbnail', kind: 'accessory', piece: { ...makeThumbnail(), description: 'a'.repeat(1025) },
  },
  {
    name: 'gallery item with no image URL', word: 'Media Gallery item', kind: 'item', piece: { media: { url: '' } },
  },
  {
    name: 'gallery item with no media', word: 'Media Gallery item', kind: 'item', piece: {},
  },
  {
    name: 'gallery item with an invalid URL', word: 'Media Gallery item', kind: 'item', piece: { media: { url: 'abc' } },
  },
  {
    name: 'gallery item with an empty description', word: 'Media Gallery item', kind: 'item', piece: { media: { url: okImage }, description: '' },
  },
  {
    name: 'gallery item with a 1025-character description', word: 'Media Gallery item', kind: 'item', piece: { media: { url: okImage }, description: 'a'.repeat(1025) },
  },
  {
    name: 'link button with no URL', word: 'link button', kind: 'button', piece: makeLinkButton({ url: '' }),
  },
  {
    name: 'link button with the URL key absent', word: 'link button', kind: 'button', piece: makeLinkButton({ url: undefined }),
  },
  {
    name: 'link button with an invalid URL', word: 'link button', kind: 'button', piece: makeLinkButton({ url: 'abc' }),
  },
  {
    name: 'link button with an ftp URL', word: 'link button', kind: 'button', piece: makeLinkButton({ url: 'ftp://example.com/x' }),
  },
  {
    name: 'link button with no label or emoji', word: 'link button', kind: 'button', piece: makeLinkButton({ label: undefined }),
  },
];

const okPieces = {
  child: makeTextDisplay('hello'),
  accessory: makeThumbnail(),
  button: makeLinkButton(),
  item: { media: { url: okImage } },
} as const;

const sibling = () => makeTextDisplay('hello');

function place(kind: Fault['kind'], piece: object, where: Placement): object[] {
  let host: object;
  switch (kind) {
    case 'child': host = where === 'section' ? { type: 9, components: [sibling(), piece, sibling()], accessory: makeThumbnail() } : piece; break;
    case 'accessory': host = makeSection(piece as Record<string, unknown>); break;
    case 'button': host = makeActionRow([okPieces.button, piece as Record<string, unknown>, okPieces.button]); break;
    default: host = { type: 12, items: [okPieces.item, piece, okPieces.item] };
  }
  if (where === 'container') return [makeContainer([sibling(), host as Record<string, unknown>, sibling()])];
  return where === 'top' ? [sibling(), host, sibling()] : [host];
}

const placementsOf = (fault: Fault): Placement[] => (fault.word === 'Text Display' ? ['top', 'container', 'section'] : ['top', 'container']);

describe('each refused component fault at every placement', () => {
  const cases = faults.flatMap((f) => placementsOf(f).map((where) => [f.name, where, f] as const));

  it.each(cases)('refuses a %s at %s', (_name, where, fault) => {
    expect(validateMessage(v2(place(fault.kind, fault.piece, where)))).not.toBe('');
  });

  it.each(['top', 'container', 'section'] as const)('sends a filled piece of each kind at %s', (where) => {
    for (const kind of ['child', 'accessory', 'button', 'item'] as const) {
      expect(validateMessage(v2(place(kind, okPieces[kind], where)))).toBe('');
    }
  });
});

describe('the reason a refusal gives', () => {
  const reason = (fault: Fault) => validateMessage(v2(place(fault.kind, fault.piece, 'top')));

  const existing = [
    'Components V2 messages cannot contain embeds or content.',
    'Message must have content, embeds, or components.',
    'This username is not allowed.',
    'This username contains invalid characters.',
    'This username is too short or too long.',
    'Embeds exceed 6000 characters.',
    'Components text exceeds 4000 characters.',
    'Message has 41 components; the limit is 40.',
    'Message is too long.',
  ];

  it.each(faults)('names the component type for a $name', (fault) => {
    expect(reason(fault)).toContain(fault.word);
  });

  it('gives every fault a reason of its own, apart from the reasons already in use', () => {
    const reasons = faults
      .filter((f) => f.name !== 'Text Display with no content' && f.name !== 'Thumbnail with no media'
        && f.name !== 'gallery item with no media' && f.name !== 'link button with the URL key absent')
      .map(reason);
    expect(new Set(reasons).size).toBe(reasons.length);
    for (const r of reasons) expect(existing).not.toContain(r);
  });

  it('gives the absent form the same reason as the empty form', () => {
    const byName = (n: string) => reason(faults.find((f) => f.name === n) as Fault);
    expect(byName('Text Display with no content')).toBe(byName('empty Text Display'));
    expect(byName('Thumbnail with no media')).toBe(byName('Thumbnail with no image URL'));
    expect(byName('gallery item with no media')).toBe(byName('gallery item with no image URL'));
    expect(byName('link button with the URL key absent')).toBe(byName('link button with no URL'));
  });
});

import {
