} from 'vitest';

import { computeLoadDiff, describeLoadDiff } from '~/utils';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

const V2_FLAG = 32768; // literal, not imported
const CONTAINER = { type: 17, components: [{ type: 10, content: 'hello' }] };
const ACTION_ROW = { type: 1, components: [] }; // NOT a V2 component type

type Mode = 'classic' | 'v2' | 'choice';

const CELLS: { id: string, draft: Record<string, unknown>, d17Row: string, expected: Mode }[] = [
  {
    id: 'bit=0 v2=0 classic=0',
    draft: {},
    d17Row: 'no flag and no V2 components',
    expected: 'classic',
  },
  {
    id: 'bit=0 v2=0 classic=1',
    draft: { content: 'hi' },
    d17Row: 'no flag and no V2 components',
    expected: 'classic',
  },
  {
    id: 'bit=0 v2=1 classic=0',
    draft: { components: [CONTAINER] },
    d17Row: 'V2 components without the flag and without content',
    expected: 'v2',
  },
  {
    id: 'bit=0 v2=1 classic=1',
    draft: { content: 'hi', components: [CONTAINER] },
    d17Row: 'V2 components together with content or embeds',
    expected: 'choice',
  },
  {
    id: 'bit=1 v2=0 classic=0',
    draft: { flags: V2_FLAG },
    d17Row: 'the flag over components within the schema and no content',
    expected: 'v2',
  },
  {
