    expect(showV2PatchWarning(message as never, { id: '123' } as never, false)).toBe(false);
  });

  it('does not warn when there is no prior sent message (oldMessage null)', () => {
    const message = { data: { flags: IS_COMPONENTS_V2_FLAG } };
    expect(showV2PatchWarning(message as never, null, true)).toBe(false);
  });

  it('does not warn for a classic message being edited', () => {
