import { describe, it, expect, vi } from 'vitest';
import { decompress } from 'compress-json';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

const stored: Record<string, string> = {};

vi.mock('~/utils/redis/client', () => ({
  getClient: () => ({
    get: async (key: string) => stored[key] ?? null,
    setnx: async (key: string, value: string) => { stored[key] = value; return 1; },
    set: async (key: string, value: string) => { stored[key] = value; return 'OK'; },
    expire: async () => 1,
    ttl: async () => 3600,
  }),
}));

import commands from 'bot/serverCommands';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';
import { author } from '~/utils/__tests__/helpers/discord';

describe('bot/serverCommands.ts get_message forwards components and flags through to the store', () => {
  it('persists the resolved message\'s components and flag bit via messageStore.store', async () => {
    let jsonPayload: unknown;
    const res = {
      status: () => ({ end: () => undefined, json: (payload: unknown) => { jsonPayload = payload; } }),
    };

    const interaction = {
      member: { user: { id: 'user-1' } },
      guild_id: 'guild-1',
      data: {
        type: 3,
        target_id: 'msg-1',
        resolved: {
          messages: {
            'msg-1': {
              id: 'msg-1',
              author: author(),
              content: '',
              embeds: [],
              flags: IS_COMPONENTS_V2_FLAG,
              components: [{ type: 10, content: 'kept' }],
              channel_id: 'chan-1',
            },
          },
        },
      },
    };

    await commands.get_message(
      {} as never,
      res as never,
      interaction as never,
    );

    expect(jsonPayload).toBeDefined();

    const [rawStoredValue] = Object.values(stored);
    const record = decompress(JSON.parse(rawStoredValue) as Parameters<typeof decompress>[0]) as StoredMessage;

    expect(record.data.components).toEqual([{ type: 10, content: 'kept' }]);
    expect(record.data.flags).toBe(IS_COMPONENTS_V2_FLAG);
    expect(record.droppedComponentTypes).toEqual([]);
  });
});

