import {
  describe, it, expect, vi,
} from 'vitest';

import {
  hasV2Components,
  hasClassicContent,
  hasV2Content,
  stripKeys,
  injectComponentKeys,
} from '~/utils';
import { validateMessage, validateDisplayableTextCount } from '~/utils/limits';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

// Mock SVG components imported by utils/index.ts
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import {
  makeLinkButton, makeActionRow, makeTextDisplay, makeThumbnail, makeSection,
  makeContainer, makeSeparator,
} from '~/utils/__tests__/helpers/components';

// ============================================================
// Tests: hasV2Components
// ============================================================

describe('hasV2Components', () => {
  it('returns true when components contain V2 type (TextDisplay)', () => {
    expect(hasV2Components([makeTextDisplay()])).toBe(true);
  });

  it('returns true for Section (type 9)', () => {
    expect(hasV2Components([makeSection()])).toBe(true);
  });

  it('returns true for Container (type 17)', () => {
    expect(hasV2Components([makeContainer()])).toBe(true);
  });

  it('returns true for Separator (type 14)', () => {
    expect(hasV2Components([makeSeparator()])).toBe(true);
  });

  it('returns false for legacy ActionRow only (type 1)', () => {
    expect(hasV2Components([makeActionRow()])).toBe(false);
  });

  it('returns false for empty array', () => {
    expect(hasV2Components([])).toBe(false);
  });

  it('returns false for undefined', () => {
    expect(hasV2Components(undefined)).toBe(false);
  });

  it('returns true when mixing ActionRow + V2 types', () => {
    expect(hasV2Components([makeActionRow(), makeTextDisplay()])).toBe(true);
  });
});

// ============================================================
// Tests: hasClassicContent
// ============================================================

describe('hasClassicContent', () => {
  it('returns true when content is non-empty', () => {
    expect(hasClassicContent({ content: 'hello' })).toBe(true);
  });

  it('returns true when embeds array has entries', () => {
    expect(hasClassicContent({ embeds: [{ title: 'Test' }] })).toBe(true);
  });

  it('returns true when both content and embeds exist', () => {
    expect(hasClassicContent({ content: 'hello', embeds: [{ title: 'T' }] })).toBe(true);
  });

  it('returns false for empty content and no embeds', () => {
    expect(hasClassicContent({ content: '' })).toBe(false);
  });

  it('returns false for empty content and empty embeds', () => {
    expect(hasClassicContent({ content: '', embeds: [] })).toBe(false);
  });

  it('returns false for undefined content and embeds', () => {
    expect(hasClassicContent({})).toBe(false);
  });

  it('returns false for whitespace-only content', () => {
    expect(hasClassicContent({ content: '   ' })).toBe(false);
  });
});

// ============================================================
// Tests: hasV2Content
// ============================================================

describe('hasV2Content', () => {
  it('returns true when components have V2 types', () => {
    expect(hasV2Content([makeTextDisplay()])).toBe(true);
  });

  it('returns false when only legacy ActionRows exist', () => {
    expect(hasV2Content([makeActionRow()])).toBe(false);
  });

  it('returns false for empty array', () => {
    expect(hasV2Content([])).toBe(false);
  });

  it('returns false for undefined', () => {
    expect(hasV2Content(undefined)).toBe(false);
  });

  it('returns true for Container type (17)', () => {
    expect(hasV2Content([makeContainer()])).toBe(true);
  });
});

// ============================================================
// Tests: stripKeys does not delete content/embeds under V2
// ============================================================
// No serialiser on the persist/seed/hash paths may remove content or embeds on its own — that
// choice belongs to the persisting writer (gateBeforePersist + the user's choice), not the
// serialiser. stripKeys is identity-modulo-`_key`s plus the V2 bit set from structure, over every
// input.

describe('stripKeys retains embeds/content under V2 components', () => {
  it('keeps embeds when V2 components are present', () => {
    const message = {
      data: {
        embeds: [{ title: 'Kept' }],
        components: [injectComponentKeys(makeTextDisplay())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.embeds![0]).toMatchObject({ title: 'Kept' });
  });

  it('keeps content when V2 components are present', () => {
    const message = {
      data: {
        content: 'Kept',
        components: [injectComponentKeys(makeTextDisplay())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Kept');
  });

  it('keeps both embeds and content when V2 components are present, and still sets the bit', () => {
    const message = {
      data: {
        content: 'text',
        embeds: [{ title: 'embed' }],
        components: [injectComponentKeys(makeContainer([makeTextDisplay()]))] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.embeds![0]).toMatchObject({ title: 'embed' });
    expect(result.data.content).toBe('text');
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('does NOT strip embeds/content when only legacy ActionRows present', () => {
    const message = {
      data: {
        content: 'Keep this',
        embeds: [{ title: 'Keep this too' }],
        components: [injectComponentKeys(makeActionRow())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Keep this');
    expect(result.data.embeds![0].title).toBe('Keep this too');
  });

  it('does NOT strip embeds/content when no components present', () => {
    const message = {
      data: {
        content: 'Keep',
        embeds: [{ title: 'Also keep' }],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Keep');
    expect(result.data.embeds![0].title).toBe('Also keep');
  });

  it('preserves components, flags, content and embeds together', () => {
    const message = {
      data: {
        content: 'keep',
        embeds: [{ title: 'keep too' }],
        components: [injectComponentKeys(makeTextDisplay('keep'))] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.components).toHaveLength(1);
    expect((result.data.components![0] as { content: string }).content).toBe('keep');
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
    expect(result.data.content).toBe('keep');
    expect(result.data.embeds![0]).toMatchObject({ title: 'keep too' });
  });
});

// ============================================================
// Tests: validateMessage mutual exclusivity
// ============================================================

describe('validateMessage mutual exclusivity', () => {
  it('returns error string for message with V2 components AND embeds', () => {
    const data = {
