    expect(payload.flags).toBe(32768);
    expect(payload.components).toEqual([{ type: 17, components: [{ type: 10, content: 'hi' }] }]);
  });

  it('carries classic content, username and embeds unchanged', () => {
    const message = {
      data: { content: 'hello', username: 'Bot', embeds: [{ _key: 'e1', title: 'T' }] },
    };
    const payload = saveAsPayload(message as never);
    expect(payload).toEqual({ content: 'hello', username: 'Bot', embeds: [{ title: 'T' }] });
  });
});

describe('jsonModalSeed (JsonModalBody seed)', () => {
  it('shows the whole message including components and flags', () => {
    const message = {
      data: {
        flags: 32768,
        components: [{ _key: 'a', type: 17, components: [] }],
      },
    };
    const seed = jsonModalSeed(message as never);
    const parsed = JSON.parse(seed);
    expect(parsed.flags).toBe(32768);
    expect(parsed.components).toEqual([{ type: 17, components: [] }]);
  });
});

