import { act, useEffect, useState } from 'react';
import {
  afterEach, beforeEach, describe, expect, it, vi,
} from 'vitest';

import useValidateWebhook from '../useValidateWebhook';

import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

type Result = ReturnType<typeof useValidateWebhook>;

const HOOK_URL_A = 'https://discord.com/api/webhooks/111/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
const HOOK_URL_B = 'https://discord.com/api/webhooks/222/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb';
const FAILURE_TEXT = 'Could not load the message. Check your connection and try again.';

let result: Result;
let setProps: (next: { url: string, input: string }) => void;
const Probe = ({ initial }: { initial: { url: string, input: string } }) => {
  const [props, set] = useState(initial);
  setProps = set;
  const value = useValidateWebhook(props.url, props.input);
  useEffect(() => { result = value; });
  return null;
};

const fetchMock = vi.fn();

function deferred<T>() {
  let resolve!: (v: T) => void;
  let reject!: (e: unknown) => void;
  const promise = new Promise<T>((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

function jsonResponse(body: unknown, status = 200) {
  return {
    ok: status === 200, status, statusText: 'x', json: () => Promise.resolve(body),
  };
}

function messageBody(content: string) {
  return {
    id: '9',
    content,
    author: { id: '1', username: 'hook' },
    embeds: [],
    components: [],
    attachments: [],
    flags: 0,
    type: 0,
  };
}

function webhookBody(id: string) {
  return { id, token: 'x'.repeat(40), name: 'hook' };
}

async function render(url: string, input: string) {
  mountDom(<Probe initial={{ url, input }} />);
  await act(async () => {});
}

async function update(url: string, input: string) {
  await act(async () => { setProps({ url, input }); });
}

beforeEach(() => {
  fetchMock.mockReset();
  fetchMock.mockResolvedValue(jsonResponse({ message: 'unused' }, 404));
  vi.stubGlobal('fetch', fetchMock);
});
afterEach(() => {
  unmountDom();
  vi.unstubAllGlobals();
});

function messageFetches() {
  return fetchMock.mock.calls.map((c) => String(c[0])).filter((u) => u.includes('/messages/'));
}

describe('useValidateWebhook, message box input class', () => {
  it('fetches the message for a whole-string id', async () => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    fetchMock.mockResolvedValue(jsonResponse(messageBody('m')));
    await render(HOOK_URL_A, '123456789012345678');
    expect(messageFetches()).toEqual([`${HOOK_URL_A}/messages/123456789012345678`]);
  });

  it.each([
    'discord.com',
    'www.discord.com',
    'canary.discord.com',
    'ptb.discord.com',
    'discordapp.com',
    'www.discordapp.com',
    'canary.discordapp.com',
    'ptb.discordapp.com',
  ])('fetches the link\'s own message id for https://%s links', async (host) => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    fetchMock.mockResolvedValue(jsonResponse(messageBody('m')));
    await render(HOOK_URL_A, `https://${host}/channels/111/222/333`);
    expect(messageFetches()).toEqual([`${HOOK_URL_A}/messages/333`]);
  });

  it.each([
    'abc123',
    'see 12345 here',
    'https://example.com/channels/1/2/3',
    'https://discord.com/channels/1/2/3/extra',
    'http://discord.com/channels/1/2/3',
  ])('does not fetch for "%s", and shows nothing', async (input) => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    await render(HOOK_URL_A, input);
    expect(messageFetches()).toEqual([]);
    expect(result.message).toBeNull();
    expect(result.messageError).toBeNull();
  });

  it('trims surrounding whitespace before testing the id', async () => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    fetchMock.mockResolvedValue(jsonResponse(messageBody('m')));
    await render(HOOK_URL_A, '  123  ');
    expect(messageFetches()).toEqual([`${HOOK_URL_A}/messages/123`]);
  });
});

describe('useValidateWebhook, fetch failures', () => {
  it('shows "Invalid URL" and no webhook when the webhook fetch rejects', async () => {
    fetchMock.mockRejectedValue(new Error('network down'));
    await render(HOOK_URL_A, '');
    await act(async () => {});
    expect(result.webhook).toBeNull();
    expect(result.webhookError).toBe('Invalid URL');
    expect(result.isLoading).toBe(false);
  });

  it('shows the connection error when the message fetch rejects', async () => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    fetchMock.mockRejectedValue(new Error('network down'));
    await render(HOOK_URL_A, '123456789012345678');
    await act(async () => {});
    expect(result.message).toBeNull();
    expect(result.messageError).toBe(FAILURE_TEXT);
  });

  it('keeps Discord\'s own refusal text for a refused webhook url', async () => {
    fetchMock.mockResolvedValue(jsonResponse({ message: 'Unknown Webhook' }, 404));
    await render(HOOK_URL_A, '');
    expect(result.webhook).toBeNull();
    expect(result.webhookError).toBe('Unknown Webhook');
  });

  it('keeps Discord\'s own refusal text for a refused message', async () => {
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    fetchMock.mockResolvedValue(jsonResponse({ message: 'Unknown Message' }, 404));
    await render(HOOK_URL_A, '123456789012345678');
    expect(result.messageError).toBe('Unknown Message');
  });
});

describe('useValidateWebhook, overlapping validations', () => {
  it('applies the latest url\'s webhook when an earlier url resolves last', async () => {
    const first = deferred<ReturnType<typeof jsonResponse>>();
    const second = deferred<ReturnType<typeof jsonResponse>>();
    fetchMock.mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);
    await render(HOOK_URL_A, '');
    await update(HOOK_URL_B, '');
    await act(async () => { second.resolve(jsonResponse(webhookBody('222'))); });
    await act(async () => { first.resolve(jsonResponse(webhookBody('111'))); });
    expect(result.webhook?.id).toBe('222');
  });

  it('applies the latest input\'s message when an earlier input resolves last', async () => {
    const first = deferred<ReturnType<typeof jsonResponse>>();
    const second = deferred<ReturnType<typeof jsonResponse>>();
    fetchMock.mockResolvedValueOnce(jsonResponse(webhookBody('111')));
    await render(HOOK_URL_A, '');
    fetchMock.mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);
    await update(HOOK_URL_A, '111');
    await update(HOOK_URL_A, '222');
    await act(async () => { second.resolve(jsonResponse(messageBody('two'))); });
    await act(async () => { first.resolve(jsonResponse(messageBody('one'))); });
    expect(result.message?.content).toBe('two');
  });
});

