'use client';

import equal from 'fast-deep-equal';
import { usePathname } from 'next/navigation';
import {
  useCallback, useEffect, useMemo, useRef, useState,
} from 'react';

import voided from '../voided';

import type { DependencyList, KeyboardEvent } from 'react';

export * from './useLocalStorage';
export { default as useWindowEventListener } from './useWindowEventListener';

export const useMounted = (delay?: number) => {
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    if (!delay) {
      setMounted(true);
    } else {
      setTimeout(() => { setMounted(true); }, delay);
    }
  }, []);
  return mounted;
};

export const useSSRBoolean = (value: boolean) => {
  const mounted = useMounted();
  return mounted ? value : false;
};

const BLUR_KEYS = new Set(['Escape']);
export function useStandardBlurKeys() {
  return useCallback<(e: KeyboardEvent<HTMLElement>) => void>((e) => {
    if (BLUR_KEYS.has(e.key)) {
      e.preventDefault();
      e.currentTarget.blur();
    }
  }, []);
}

export function usePassedProp<T>(prop: T | (() => T)) {
  const [localProp, setLocalProp] = useState<T>(prop);
  useEffect(() => { setLocalProp(() => (prop instanceof Function ? prop() : prop)); }, [prop]);
  return [localProp, setLocalProp] as const;
}

export function useToggleState(
  initial: boolean | (() => boolean) = false,
  cb: ((b: boolean) => void) = () => {},
) {
  const [bool, setShow] = useState(initial);
  const toggle = useCallback(() => { setShow((b) => { setTimeout(() => { cb(!b); }); return !b; }); }, []);
  const setTrue = useCallback(() => { setShow(true); cb(true); }, []);
  const setFalse = useCallback(() => { setShow(false); cb(false); }, []);
  const set = useCallback((b: boolean) => { setShow(b); cb(b); }, []);
  return [bool, {
    toggle, setTrue, setFalse, set,
  }] as const;
}

interface OptionStates<T extends string> {
  states: Record<T, boolean>;
  current: T | null;
  unset: () => void;
  setters: Record<T, (b?: boolean) => void>;
}
export function useOptionState
  <T extends string>(options: T[], initial: T | null = null): OptionStates<T> {
  const [current, setCurrent] = useState(initial);

  // eslint-disable-next-line @typescript-eslint/prefer-reduce-type-parameter
  const states = useMemo(() => options.reduce((acc, option) => { acc[option] = current === option; return acc; }, {} as Record<T, boolean>), [current]);

  const setters = useMemo(() => options.reduce((acc, option) => {
    acc[option] = (b?: boolean) => {
      if (b === undefined) setCurrent(option);
      else if (b) setCurrent(option);
      else setCurrent(null);
    }; return acc;
  // eslint-disable-next-line @typescript-eslint/prefer-reduce-type-parameter
  }, {} as Record<T, (b?: boolean) => void>), []);
  const unset = useCallback(() => setCurrent(null), []);

  return {
    states, current, unset, setters,
  };
}

export type StateCallback<T> = (cb: ((prevState: T) => T)) => void;
type Callback<T, K extends keyof T> = (val: T[K]) => void;
export function useStateSetter
  <T extends Record<string, unknown>, K extends keyof T = keyof T>(
  state: T,
  key: K,
  setState: StateCallback<T>,
) {
  const field = state[key];
  const setField = useCallback<Callback<T, K>>((val: T[K]) => setState((prevState) => ({ ...prevState, [key]: val })), [key, setState]);
  return [field, setField] as const;
}

type DocumentEventListener<K extends keyof DocumentEventMap> = ((data: DocumentEventMap[K]) => void);
export function useDocumentEventListener
  <K extends keyof DocumentEventMap>(
  event: K,
  callback: undefined | DocumentEventListener<K>,
  deps: unknown[] = [],
  options: AddEventListenerOptions = {},
) {
  useEffect(() => {
    if (callback) {
      const cb: DocumentEventListener<K> = (data) => { callback(data); };
      document.addEventListener(event, cb, options);
      return () => document.removeEventListener(event, cb, options);
    }
    return undefined;
  }, [...deps]);
}

type ElementEventListener<K extends keyof HTMLElementEventMap> = ((data: HTMLElementEventMap[K]) => void);
export function useElementEventListener
<K extends keyof HTMLElementEventMap>(
  element: null | HTMLElement | string,
  event: K,
  callback: ElementEventListener<K>,
  deps: unknown[] = [],
) {
  useEffect(() => {
    const el = typeof element === 'string' ? document.querySelector(element) as HTMLElement : element;
    const cb: ElementEventListener<K> = (data) => { callback(data); };
    el?.addEventListener(event, cb);
    return () => el?.removeEventListener(event, cb);
  }, [element, ...deps]);
}

function isDependencyList(deps: DependencyList | unknown): deps is DependencyList {
  return Array.isArray(deps);
}

export function useTimerCallback(
  effect: AsyncEffectCallback,
  timeout: number,
  deps: Record<string, unknown> | DependencyList,
  shouldSchedule?: boolean,
) {
  const ref = useRef<Record<string, unknown> | DependencyList>(deps);
  if (!isDependencyList(deps)) {
    if (!equal(deps, ref.current)) ref.current = deps;
    deps = [ref.current];
  }

  const timerRef = useRef<NodeJS.Timeout | undefined>(undefined);
  useEffect(() => {
    clearTimeout(timerRef.current);
    if (shouldSchedule) timerRef.current = setTimeout(voided(effect), timeout);
  }, [...deps, shouldSchedule]);
}

export const useLoading = (delay?: number) => {
  const [isLoading, { setTrue: start, setFalse: stop }] = useToggleState(false);
  const withLoading = useCallback(<T>(promise: Promise<T>) => {
    start();
    return promise.finally(delay ? () => { setTimeout(stop, delay); } : stop);
  }, [start, stop]);

  return [isLoading, withLoading] as const;
};

export function useComponentResetKey() {
  const [key, setKey] = useState(1);
  return [key, useCallback(() => setKey((old) => ++old), [])] as const;
}

export function useParsePathname() {
  const pathname = usePathname();
  const folderId = pathname?.match(/^\/message\/f\/(\d+)\/?/)?.[1];
  const messageId = pathname?.match(/^\/message\/m\/(\d+)\/?/)?.[1];
  const state = {
    folderId,
    guildId: folderId && folderId !== '0' ? folderId : '',
    messageId,
  };
  return useMemo(() => state, [folderId, messageId]);
}
