type WindowEventListener<K extends keyof WindowEventMap> = ((data: WindowEventMap[K]) => void);
const useWindowEventListener = <K extends keyof WindowEventMap>(event: K, callback: WindowEventListener<K>, deps: unknown[] = [], options: AddEventListenerOptions | undefined = {}) => {
  useEffect(() => {
    const cb: WindowEventListener<K> = (data) => { callback(data); };
    window.addEventListener(event, cb, options);
    return () => window.removeEventListener(event, cb, options);
  }, deps);
};

