export function makeEditable<T extends Partial<ActiveMessage> | Partial<ApiMessage>>(
  message: T,
): ActiveMessage {
  const casted = JSON.parse(JSON.stringify(message)) as ActiveMessage;
  for (const embed of casted.data.embeds ?? []) {
    if (!embed._key) embed._key = genUuid();
    for (const field of embed.fields ?? []) {
      if (!field._key) field._key = genUuid();
    }
  }
  if (casted.data.components) {
    casted.data.components = casted.data.components.map(injectComponentKeys);
  }

  return casted;
}

export function injectComponentKeys(component: Record<string, unknown>): EditableTopLevelComponent {
  const c = { ...component };
  if (!c._key) c._key = genUuid();

  // Action row → inject keys into child buttons
  if (c.type === 1 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map((child) => {
      if (!child._key) child._key = genUuid();
      return child;
    });
  }

  // Section → inject keys into text display children + accessory
  if (c.type === 9) {
    if (Array.isArray(c.components)) {
      c.components = (c.components as Record<string, unknown>[]).map((child) => {
        if (!child._key) child._key = genUuid();
        return child;
      });
    }
    if (c.accessory && typeof c.accessory === 'object') {
      const acc = { ...(c.accessory as Record<string, unknown>) };
      if (!acc._key) acc._key = genUuid();
      c.accessory = acc;
    }
  }

  // Media gallery → inject keys into items
  if (c.type === 12 && Array.isArray(c.items)) {
    c.items = (c.items as Record<string, unknown>[]).map((item) => {
      if (!item._key) item._key = genUuid();
      return item;
    });
  }

  // Container → recurse into children
  if (c.type === 17 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(injectComponentKeys);
  }

  return c as unknown as EditableTopLevelComponent;
}

/** Deep-clones a component and regenerates all `_key` values recursively. */
export function rekeyComponent(c: EditableTopLevelComponent): EditableTopLevelComponent {
  const stripped = stripComponentKeys(
    JSON.parse(JSON.stringify(c)) as Record<string, unknown>,
  );
  return injectComponentKeys(stripped);
}

function stripComponentKeys(
  component: Record<string, unknown>,
): Record<string, unknown> {
  const c = { ...component };
  delete c._key;

  if (c.type === 1 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
  }

  if (c.type === 9) {
    if (Array.isArray(c.components)) {
      c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
    }
    if (c.accessory && typeof c.accessory === 'object') {
      const { _key: _, ...rest } = c.accessory as Record<string, unknown>;
      c.accessory = rest;
    }
  }

  if (c.type === 12 && Array.isArray(c.items)) {
    c.items = (c.items as Record<string, unknown>[]).map((item) => {
      const { _key: _, ...rest } = item as Record<string, unknown>;
      return rest;
    });
  }

  if (c.type === 17 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
  }

  return c;
}

export function stripKeys<T extends { data?: EditableMessageData }>(message: T) {
  const casted = JSON.parse(JSON.stringify(message));
  for (const embed of casted.data?.embeds ?? []) {
    delete embed._key;
    for (const field of embed.fields ?? []) {
      delete field._key;
    }
  }
  if (Array.isArray(casted.data?.components)) {
    casted.data.components = (casted.data.components as Record<string, unknown>[])
      .map(stripComponentKeys);

    const hasV2 = (casted.data.components as { type: number }[]).some(
      (c) => V2_COMPONENT_TYPES.has(c.type),
    );
    if (hasV2) {
      casted.data.flags = ((casted.data.flags as number) || 0) | IS_COMPONENTS_V2_FLAG;
    }
  }

  return casted as ApiMessage;
}

export function saveAsPayload(message: Pick<ActiveMessage, 'data'>): MessageData {
  return stripKeys(message).data;
}

export function jsonModalSeed(message: null | undefined | ActiveMessage): string {
  return JSON.stringify(stripKeys(message ?? {}).data, null, 2);
}

const DISCORD_EPOCH = 1420070400000;
export function timestampFromSnowflake(snowflake: string): number {
  const bits = BigInt(snowflake).toString(2).padStart(64, '0');
  return parseInt(bits.substring(0, 42), 2) + DISCORD_EPOCH;
}

export default class SumMap<K> extends Map<K, number> {
  public upsert(key: K, ...values: number[]) {
    let item = this.get(key);
    if (!item) {
      item = 0;
    }
    for (const val of values) item += val;
    this.set(key, item);
  }
}

import UpsertSetMap from './UpsertSetMap';
import UpsertArrayMap from './UpsertArrayMap';
import ExtendedMap from './ExtendedMap';

type InnerMap<V, T> = ExtendedMap<V, T> | UpsertArrayMap<V, T> | UpsertSetMap<V, T>;
type InnerMapType = 'map' | 'array' | 'set';

type MFromM<V, T, M extends InnerMapType> =
M extends 'map' ? ExtendedMap<V, T>
: M extends 'array' ? UpsertArrayMap<V, T>
: UpsertSetMap<V, T>;

type TFromM<T, M extends InnerMapType> =
M extends 'map' ? T
: M extends 'array' ? T[]
: Set<T>;

export default class UpsertMapMap<K, V, T, M extends InnerMapType> {
  #type: M;

  #map: Map<K, InnerMap<V, T>>;

  #InnerMap: new () => InnerMap<V, T>;

  public constructor(type: M) {
    this.#type = type;

    this.#map = new Map();
    switch (type) {
      case 'map':
        this.#InnerMap = ExtendedMap<V, T>;
        break;
      case 'array':
        this.#InnerMap = UpsertArrayMap<V, T>;
        break;
      default:
        this.#InnerMap = UpsertSetMap<V, T>;
    }
  }

  public get type() {
    return this.#type;
  }

  public get size() {
    return this.#map.size;
  }

  public upsert(key: K, innerKey: V, value: T) {
    let values = this.#map.get(key);
    if (!values) {
      values = new this.#InnerMap();
      this.#map.set(key, values);
    }
    values.upsert(innerKey, value);
  }

  public get(key: K): undefined | MFromM<V, T, M>;

  public get(key: K, innerKey?: V): undefined | TFromM<T, M>;

  public get(key: K, innerKey?: V) {
    const val = this.#map.get(key);
    return innerKey === undefined || val === undefined ? val : val.get(innerKey);
  }

  public delete(key: K, innerKey?: V) {
    if (innerKey === undefined) this.#map.delete(key);
    else this.#map.get(key)?.delete(innerKey);
  }

  public keys(): IterableIterator<K> {
    return this.#map.keys();
  }

  public values() {
    return this.#map.values() as IterableIterator<MFromM<V, T, M>>;
  }

  public entries() {
    return this.#map.entries() as IterableIterator<[K, MFromM<V, T, M>]>;
  }

  public* items(): Generator<[K, V, T]> {
    for (const [k, inner] of this.#map.entries()) {
      if (inner instanceof ExtendedMap) {
        for (const [v, t] of inner.entries()) {
          yield [k, v, t];
        }
      } else {
        for (const [v, values] of inner.entries()) {
          for (const t of values) {
            yield [k, v, t];
          }
        }
      }
    }
  }
}

export { default as UpsertSetMap } from './UpsertSetMap';
export { default as UpsertArrayMap } from './UpsertArrayMap';
export { default as UpsertMapMap } from './UpsertMapMap';
export { default as SumMap } from './SumMap';
export { default as ExtendedMap } from './ExtendedMap';
export { default as AggregateMap } from './AggregateMap';

export function makeMap<T, K extends keyof T>(items: T[], key: K): Map<T[K], T>;
export function makeMap<T, K extends keyof T, U extends keyof T>(items: T[], key: K, valueKey: U): Map<T[K], T[U]>;
export function makeMap<T, K extends keyof T, U extends keyof T>(items: T[], key: K, valueKey?: U): Map<T[K], T[U] | T> {
  const map = new Map<T[K], T | T[U]>();
  for (const item of items) map.set(item[key], valueKey ? item[valueKey] : item);
  return map;
}

type RecordKey = string | number | symbol;
export function makeObject<T, K extends KeysMatching<T, RecordKey>>(items: T[], key: K): Record<RecordKey, T> {
  const obj = {} as Record<RecordKey, T>;
  for (const item of items) obj[item[key] as unknown as RecordKey] = item;
  return obj;
}

