import classNames from 'classnames';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
import utc from 'dayjs/plugin/utc';
import { useCallback, useMemo, useState } from 'react';

import AnchoredPopover from '~/components/AnchoredPopover';
import Button from '~/components/Button';
import Calendar from '~/components/dynamics/Calendar';
import styles from '~/styles';

dayjs.extend(relativeTime);
dayjs.extend(utc);

const TIMESTAMP_TO_DAYJS_FORMAT: Record<string, string> = {
  t: 'LT',
  T: 'LTS',
  d: 'L',
  D: 'LL',
  f: 'LLL',
  F: 'LLLL',
};

type Props = {
  timestamp: number;
  format: undefined | string;
  state: SimpleMarkdown.State;
};
const MarkdownTimestamp: FC<Props> = ({ timestamp, format = 'f', state }) => {
  // const [isCalendarOpen, { toggle: toggleCalendar, setFalse: hideCalendar }] = useToggleState();

  let date = dayjs(timestamp * 1000);
  if (!state.mounted) date = date.utc();

  const [localDate, setLocalDate] = useState<null | Date>(date.toDate());
  const [localFormat, setLocalFormat] = useState<string>(format);

  const dayjsDate = dayjs(localDate ?? date.toDate());
  const dayjsFormat = TIMESTAMP_TO_DAYJS_FORMAT[localFormat];

  const label = dayjsFormat ? dayjsDate.format(dayjsFormat) : dayjsDate.fromNow();
  const fullLabel = dayjsDate.format(TIMESTAMP_TO_DAYJS_FORMAT.F);

  const index = useMemo(() => {
    state.indexes = state.indexes ?? { timestamp: 0 };
    state.indexes.timestamp = state.indexes.timestamp ?? 0;
    return state.indexes.timestamp++;
  }, []);

  const onChange = useCallback(() => {
    if (
      !localDate
      || !state.onChange
      || (
        localDate.getTime() === date.toDate().getTime()
        && localFormat === format
      )
    ) return;
    const newTimestamp = Math.floor(localDate.getTime() / 1000).toString();

    state.onChange(
      /<t:([0-9]+)(?::([tTdDfFR]))?>/g,
      `<t:${newTimestamp}:${localFormat}>`,
      index,
    );
  }, [state.onChange, index, localDate, localFormat]);

  if (!state.onChange) {
    return (
      <span
        aria-label={fullLabel}
        className="discord-visualizer__content-timestamp"
      >
        {label}
      </span>
    );
  }

  return (
    <AnchoredPopover placement='bottom' arrow>
      <AnchoredPopover.Trigger
        aria-label={fullLabel}
        className="discord-visualizer__content-timestamp"
      >
        {label}
      </AnchoredPopover.Trigger>
      <AnchoredPopover.Child
        className="flex"
        afterLeave={onChange}
        {...styles.transition({
          transition: 'transition ease-out min-w-fit',
          enter: 'duration-[10000]',
          leave: 'duration-[10000]',
          closed: 'translate-y-4 flipped:-translate-y-4 opacity-0',
          opened: 'translate-y-2 flipped:-translate-y-2 opacity-100',
        })}
      >
        <Calendar
          value={localDate ?? new Date()}
          onChange={setLocalDate}
        />
        <div className='flex flex-col bg-tertiary p-4 text-sm'>
          <h2 id="format-title">Format</h2>
          <ul aria-labelledby='format-title' className="!m-0 ">
            {Object.keys(TIMESTAMP_TO_DAYJS_FORMAT).map((f) => (
              <li key={f} className='block'>
                <Button
                  className={classNames(styles.button.primaryHover, 'w-full rounded p-2', f === localFormat && 'bg-primary')}
                  onPress={() => setLocalFormat(f)}
                >
                  {dayjsDate.format(TIMESTAMP_TO_DAYJS_FORMAT[f])}
                </Button>
              </li>
            ))}
            <li className='block'>
              <Button
                className={classNames(styles.button.primaryHover, 'w-full rounded p-2', localFormat === 'R' && 'bg-primary')}
                onPress={() => setLocalFormat('R')}
              >
                {dayjsDate.fromNow()}
              </Button>
            </li>
          </ul>
        </div>
      </AnchoredPopover.Child>
    </AnchoredPopover>
  );
};

export default MarkdownTimestamp;

import { IS_COMPONENTS_V2_FLAG } from '~/constants/messageLimits';
import { hasV2Components } from '~/utils';

type ModeSwitchDraft = Pick<Partial<MessageData>, 'content' | 'embeds' | 'components' | 'flags'>;

export function isMessageV2(data: Pick<Partial<MessageData>, 'flags' | 'components'>): boolean {
  return hasV2Components(data.components as undefined | { type: number }[])
    || !!((data.flags as number | undefined ?? 0) & IS_COMPONENTS_V2_FLAG);
}

export function detectMessageMode(
  msg: null | undefined | Pick<ActiveMessage, 'data'>,
): MessageMode | null {
  if (!msg) return null;
  return isMessageV2(msg.data) ? 'v2' : 'classic';
}

export function showV2PatchWarning(
  message: null | undefined | Pick<ActiveMessage, 'data'>,
  oldMessage: unknown,
  showEdit: boolean,
): boolean {
  return showEdit && !!oldMessage && !!message && isMessageV2(message.data);
}

export function switchToV2<T extends ModeSwitchDraft>(prev: T): T {
  return {
    ...prev,
    content: '',
    embeds: [],
    flags: ((prev.flags as number | undefined) ?? 0) | IS_COMPONENTS_V2_FLAG,
  };
}

export function switchToClassic<T extends ModeSwitchDraft>(prev: T): T {
  const next: T = {
    ...prev,
    components: (prev.components ?? []).filter(
      (c) => (c as { type: number }).type === 1,
    ),
  };
  next.flags = ((next.flags as number | undefined) ?? 0) & ~IS_COMPONENTS_V2_FLAG;
  return next;
}

export function applyModeSwitch<T extends ModeSwitchDraft>(targetMode: MessageMode, prev: T): T {
  return targetMode === 'v2' ? switchToV2(prev) : switchToClassic(prev);
}

export default <T extends object>(object: T, excluded: string[]) => (Object.keys(object) as string[])
  .reduce<T>((result, key) => {
    if (excluded.indexOf(key) === -1) {
      result[key as keyof T] = object[key as keyof T];
    }

    return result;
  // eslint-disable-next-line @typescript-eslint/prefer-reduce-type-parameter
  }, {} as T);

