import { TRPCError } from '@trpc/server';
import { compress, decompress } from 'compress-json';
import { getPostgres } from 'project-utils';

import Deferred from '../Deferred';
import { getApi } from '../discord';
import hasDiscordPermissions from '../hasDiscordPermissions';
import { UpsertArrayMap } from '../maps';
import pushSorted from '../pushSorted';
import voided from '../voided';

import { getClient, getSubscriber } from './client';
import formatKey from './formatKey';

import type { Compressed } from 'compress-json';
import type { APIChannel as Channel, APIWebhook as DiscordWebhook, APIGuild as Guild } from 'discord-api-types/v10';

import { TEXT_CHANNEL_TYPES, VOICE_CHANNEL_TYPES } from '~/constants';
import { env } from '~/env.mjs';

if (typeof window !== 'undefined') throw Error('This file should only be imported on the server.');

const UPDATE_CHANNEL = 'local_updates';
const WAITING_MAP = new UpsertArrayMap<string, WaitingRequest>();

interface HotCacheOptions {
  expireSeconds: number;
  timeoutSeconds?: number;
  // maxAge?: null | number;
}

interface CacheUpdateMessage {
  key: string;
  item: unknown;
  error?: string;
}

interface WaitingRequest {
  timeout: NodeJS.Timeout;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  deferred: Deferred<any>;
}

async function subscribeToUpdates() {
  await getSubscriber().subscribe(UPDATE_CHANNEL);
  getSubscriber().on('message', (channel: string, message: string) => {
    if (channel !== UPDATE_CHANNEL) return;

    const { key, item } = JSON.parse(message) as CacheUpdateMessage;
    const deferred = WAITING_MAP.get(key);
    if (deferred) resolveDeferred(key, item, deferred);
  });
}
void subscribeToUpdates();

async function wait<T>(key: string, timeoutSeconds: number): Promise<T> {
  const deferred = new Deferred<T>();
  const timeout = setTimeout(voided(async () => {
    const cached = await getItem<T>(key);
    if (cached) resolveDeferred(key, cached.item, WAITING_MAP.get(key) ?? []);
    else deferred.reject(`fetch timed out. key: ${key}`);
  }), timeoutSeconds * 1e3);

  WAITING_MAP.upsert(key, { deferred, timeout });

  const cached = await getItem<T>(key);
  if (cached) {
    resolveDeferred(key, cached.item, WAITING_MAP.get(key) ?? []);
  }

  return deferred.promise;
}

// eslint-disable-next-line class-methods-use-this
async function getItem<T>(key: string): Promise<{ item: T } | null> {
  const cachedItem = await getClient().get(key);
  if (cachedItem !== null) {
    try {
      const item = JSON.parse(cachedItem) as Compressed;
      return { item: (typeof item === 'object' && !!item ? decompress(item) : item) as T };
    } catch (err) {
      console.error('Bad cache item.');
      console.error(err);
      console.error(cachedItem);
      await getClient().del(key);
      return null;
    }
  }
  return null;
}

function resolveDeferred<T>(key: string, item: T, waiting: WaitingRequest[]) {
  WAITING_MAP.delete(key);
  for (const { timeout, deferred } of waiting) {
    clearTimeout(timeout);
    deferred.resolve(item);
  }
}

async function getFromCache<T>(
  key: string | string[],
  options: HotCacheOptions,
  fetch: () => Promise<T>,
): Promise<T> {
  // const { expireSeconds, timeoutSeconds = 10, maxAge = null } = options ?? {};
  const { expireSeconds, timeoutSeconds = 10 } = options ?? {};

  key = Array.isArray(key) ? formatKey(...key) : key;

  // if (maxAge !== null) {
  //   const ttl = await getClient().ttl(key);
  //   const age = expireSeconds - ttl;
  //   if (age > maxAge) {
  //     void getClient().del(key);
  //   }
  // }

  const cachedItem = await getItem<T>(key);
  if (cachedItem) return cachedItem.item;

  const mutexKey = `${key}-mutex`;

  const acquired = await getClient().set(mutexKey, 0, 'EX', 5, 'NX');
  if (!acquired) return wait<T>(key, timeoutSeconds);

  try {
    const item = await fetch();
    if (item === undefined) throw Error(`Fetch \`${key}\` returned undefined. Cannot set cache.`);
    await setToCache(key, item, expireSeconds);

    const message: CacheUpdateMessage = { key, item };
    void getClient().publish(UPDATE_CHANNEL, JSON.stringify(message));
    return item;
  } finally {
    await getClient().del(mutexKey);
  }
}

function setToCache<T>(key: string, item: T, expireSeconds: number) {
  const cacheItem = JSON.stringify(typeof item === 'object' && item ? compress(item as unknown as object) : item);
  return getClient().set(key, cacheItem, 'EX', expireSeconds);
}

async function refreshUserAccessToken(accountId: DatabaseId, refreshToken: string) {
  const myHeaders = new Headers();
  myHeaders.append('Content-Type', 'application/x-www-form-urlencoded');

  const urlencoded = new URLSearchParams();
  urlencoded.append('client_id', env.NEXT_PUBLIC_DISCORD_CLIENT_ID);
  urlencoded.append('client_secret', env.DISCORD_CLIENT_SECRET);
  urlencoded.append('grant_type', 'refresh_token');
  urlencoded.append('refresh_token', refreshToken);

  const res = await fetch('https://discord.com/api/v10/oauth2/token', {
    method: 'POST',
    headers: myHeaders,
    body: urlencoded,
  })
    .then((response) => response.json() as Promise<RefreshTokenResponse>);
  if ('error' in res) {
    console.error(res.error);
    return null;
  }

  const { access_token, refresh_token, expires_in } = res;

  const updatedAccount = {
    access_token,
    refresh_token,
    expires_at: Math.floor((Date.now() / 1000) + expires_in),
  };
  await getPostgres().updateTable('Accounts').set({
    ...updatedAccount,
    // where: { id: accountId },
    // data: updatedAccount,
  })
    .where('id', '=', `${accountId}`)
    .execute();

  return updatedAccount;
}

type RefreshTokenResponse = {
  access_token: string;
  refresh_token: string;
  expires_in: number;
} | { error: string };
function fetchUserAccount(userId: DatabaseId) {
  return getFromCache(
    ['user-access-token', userId.toString()],
    { expireSeconds: 600 },
    async () => {
      const account = await getPostgres().selectFrom('Accounts')
        .select(['id', 'access_token', 'refresh_token', 'providerAccountId', 'expires_at'])
        .where('userId', '=', `${userId}`)
        .executeTakeFirstOrThrow();

      const { id, ...rest } = account;
      if (!account.refresh_token) return null;
      if (!account.expires_at || (account.expires_at * 1e3) < Date.now()) {
        const updatedAccount = await refreshUserAccessToken(id, account.refresh_token);
        if (!updatedAccount) return null;
        return {
          ...rest,
          ...updatedAccount,
        };
      }

      return rest;
    },
  );
}

function sortByName(a: UserGuild, b: UserGuild) {
  if (a.name.toLowerCase() < b.name.toLowerCase()) return -1;
  if (a.name.toLowerCase() > b.name.toLowerCase()) return 1;
  return 0;
}

function fetchUserGuilds(userId: DiscordId, accessToken: string) {
  return getFromCache(
    ['user-guilds', userId],
    { expireSeconds: 600 },
    async () => {
      const guilds = await fetch(`${env.DISCORD_URL}/users/@me/guilds`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      }).then((res) => res.json()) as UserGuild[];

      if (!Array.isArray(guilds)) {
        throw Error(`Failed to fetch guilds. Got: ${JSON.stringify(guilds)}`);
      }

      const trimmedGuilds: UserGuild[] = [];
      for (const guild of guilds) {
        if (guild.owner || hasDiscordPermissions(guild.permissions, ['Administrator'])) {
          pushSorted(trimmedGuilds, {
            id: guild.id,
            name: guild.name,
            icon: guild.icon,
            owner: guild.owner,
            permissions: guild.permissions,
          }, sortByName);
        }
      }

      return trimmedGuilds;
    },
  );
}

function clearUser(userId: DatabaseId, sessionToken: string, discordId?: string) {
  const pipeline = getClient().pipeline()
    .del(formatKey('user-access-token', userId.toString()))
    .del(formatKey('user-session-token', sessionToken));
  if (discordId) pipeline.del(formatKey('user-guilds', discordId));
  return pipeline.exec();
}

function fetchGuild(guildId: string) {
  return getFromCache(
    ['guild', guildId],
    { expireSeconds: 600 },
    async () => {
      const { data: guild, status } = await getApi().request<Guild>('GET', `/guilds/${guildId}`, { validateStatus: null });
      if (status === 404) {
        throw new TRPCError({
          code: 'NOT_FOUND',
          message: 'The bot is not in this server.',
        });
      }
      if (status !== 200) {
        throw new TRPCError({
          code: 'INTERNAL_SERVER_ERROR',
          message: 'An unknown error occurred. Please try again later or contact support.',
        });
      }
      return {
        id: guild.id,
        name: guild.name,
        icon: guild.icon,
        emojis: guild.emojis.map((emoji) => ({
          id: emoji.id,
          name: emoji.name,
          animated: emoji.animated,
        })),
      };
    },
  );
}

async function fetchChannels(guildId: string) {
  return getFromCache(
    ['guild', guildId, 'channels'],
    { expireSeconds: 10 },
    async () => {
      const [{ data: channels }, { data: { threads } }] = await Promise.all([
        getApi().request<Channel[]>('GET', `/guilds/${guildId}/channels`),
        getApi().request<{ threads: Array<Channel & { parent_id: string }> }>('GET', `/guilds/${guildId}/threads/active`),
      ]);

      const threadMap = new UpsertArrayMap<string, DiscordThread>();
      for (const t of threads) {
        if (t.name) {
          threadMap.upsert(t.parent_id, { id: t.id, name: t.name });
        }
      }

      const trimmedChannels: DiscordChannel[] = [];
      for (const channel of channels) {
        if (
          channel.name
          && (
            TEXT_CHANNEL_TYPES.includes(channel.type)
            || VOICE_CHANNEL_TYPES.includes(channel.type)
          )
        ) {
          trimmedChannels.push({
            id: channel.id,
            name: channel.name,
            type: channel.type,
            threads: threadMap.get(channel.id) ?? [],
          });
        }
      }

      return trimmedChannels;
    },
  );
}

function fetchChannel(channelId: string) {
  return getFromCache(
    ['channel', channelId],
    { expireSeconds: 10 },
    async () => {
      const { data: channel, status } = await getApi().request<Channel>('GET', `/channels/${channelId}`, { validateStatus: null });
      if (status !== 200) {
        switch (status) {
          case 401:
            throw new TRPCError({
              code: 'UNAUTHORIZED',
              message: 'Missing permissions. Make sure the bot has access to this channel in Discord.',
            });
          case 403:
            throw new TRPCError({
              code: 'FORBIDDEN',
              message: 'Missing permissions. Make sure the bot has access to this channel in Discord.',
            });
          case 404:
            throw new TRPCError({
              code: 'NOT_FOUND',
              message: 'Channel does not exist.',
            });
          default:
            throw new TRPCError({
              code: 'INTERNAL_SERVER_ERROR',
              message: 'An unknown error occurred. Please try again later or contact support.',
            });
        }
      }
      return channel;
    },
  );
}

function fetchWebhooks(guildId: string) {
  return getFromCache(
    ['guild', guildId, 'webhooks'],
    { expireSeconds: 10 },
    async () => {
      const { data: webhooks, status } = await getApi().request<DiscordWebhook[]>('GET', `/guilds/${guildId}/webhooks`, { validateStatus: null });
      if (status !== 200) return [];
      return webhooks.reduce<Webhook[]>((acc, webhook) => {
        if (
          webhook.type === 1
          && webhook.name
          && webhook.channel_id
          && webhook.token
          && (!webhook.user?.bot || webhook.user?.id === env.NEXT_PUBLIC_DISCORD_CLIENT_ID)
        ) {
          acc.push({
            id: webhook.id,
            name: webhook.name,
            token: webhook.token,
            avatar: webhook.avatar,
            channel_id: webhook.channel_id,
            guild_id: guildId,
          });
        }
        return acc;
      }, []);
    },
  );
}

async function fetchWebhooksAndChannels(guildId: string): Promise<{
  webhooks: Webhook[];
  channels: DiscordChannel[];
}> {
  const [webhooks, channels] = await Promise.all([
    fetchWebhooks(guildId),
    fetchChannels(guildId),
  ]);

  return {
    webhooks,
    channels,
  };
}

async function fetchAccountFromSession(sessionToken: string) {
  const cached = await getFromCache(
    ['user-session-token', sessionToken],
    { expireSeconds: 600 },
    async () => {
      const account = await getPostgres()
        .selectFrom('Accounts')
        .select(['userId', 'access_token', 'providerAccountId'])
        .where(({ selectFrom, exists }) => exists(selectFrom('Users')
          .select('id')
          .where(({ selectFrom: sf, exists: ex }) => ex(sf('Sessions')
            .select('id')
            .where('sessionToken', '=', sessionToken)
            .whereRef('Sessions.userId', '=', 'Users.id')))
          .whereRef('Users.id', '=', 'Accounts.userId')))
        .limit(1)
        .executeTakeFirst();

      if (!account) return null;
      return {
        ...account,
        userId: account.userId,
      };
    },
  );
  if (!cached) return cached;
  return {
    ...cached,
    userId: cached.userId,
  };
}

export default {
  fetchGuild,
  fetchChannels,
  fetchChannel,
  fetchWebhooksAndChannels,
  fetchWebhooks,
  fetchUserGuilds,
  fetchUserAccount,
  fetchAccountFromSession,
  clearUser,
};

export default function withLocalStorage<K extends keyof LocalStorage>(key: K, defaultValue: LocalStorage[K]) {
  function get(): LocalStorage[K] {
    if (typeof window !== 'undefined') {
      const item = localStorage.getItem(key);
      if (item === null || item === undefined) return defaultValue;
      if (item?.startsWith('{') || item?.startsWith('[')) return JSON.parse(item) as LocalStorage[K];
      return item as LocalStorage[K];
    }
    return defaultValue;
  }

  function set(value: LocalStorage[K]) {
    if (typeof window === 'undefined') return false;
    try {
      localStorage.setItem(key, typeof value === 'object' ? JSON.stringify(value) : String(value));
    } catch {
      return false;
    }
    window.dispatchEvent(new Event('storage', { bubbles: true }));
    return true;
  }

  function remove() {
    if (typeof window !== 'undefined') {
      localStorage.removeItem(key);
      window.dispatchEvent(new Event('storage'));
    }
  }

  // function clear() {
  //   if (typeof window !== 'undefined') {
  //     console.debug('clearing local storage');
  //     localStorage.clear();
  //     window.dispatchEvent(new Event('storage'));
  //   }
  // }

  return { get, remove, set };
}
